const WORDS_B2 = [
  {id:993,german:"der/die Arbeitgeber/-in",level:"B2",english:"employer",pos:"noun (m/f)",sentences:[{"de": "Der Arbeitgeber zahlt das Gehalt pünktlich zum Monatsende.", "en": "The employer pays the salary punctually at the end of the month."}, {"de": "Sie sucht einen neuen Arbeitgeber, der flexible Arbeitszeiten anbietet.", "en": "She is looking for a new employer who offers flexible working hours."}]},
  {id:994,german:"der/die Architekt/-in",level:"B2",english:"architect",pos:"noun (m/f)",sentences:[{"de": "Der Architekt hat die Pläne für das neue Gebäude entworfen.", "en": "The architect designed the plans for the new building."}, {"de": "Die Architektin wurde für ihren innovativen Entwurf ausgezeichnet.", "en": "The architect was awarded for her innovative design."}]},
  {id:995,german:"der/die Automechaniker/-in",level:"B2",english:"car mechanic",pos:"noun (m/f)",sentences:[{"de": "Der Automechaniker hat den Motorschaden schnell repariert.", "en": "The car mechanic repaired the engine damage quickly."}, {"de": "Sie arbeitet als Automechanikerin in einer großen Werkstatt.", "en": "She works as a car mechanic in a large workshop."}]},
  {id:996,german:"der Autoproduzent",level:"B2",english:"car manufacturer",pos:"noun (m)",sentences:[{"de": "Der Autoproduzent stellt jährlich Millionen von Fahrzeugen her.", "en": "The car manufacturer produces millions of vehicles annually."}, {"de": "Viele deutsche Autoproduzenten investieren stark in Elektromobilität.", "en": "Many German car manufacturers are investing heavily in electric mobility."}]},
  {id:997,german:"die Beratung",level:"B2",english:"consultation, advice",pos:"noun (f)",sentences:[{"de": "Die kostenlose Beratung beim Arbeitsamt hat ihr sehr geholfen.", "en": "The free consultation at the employment office helped her a great deal."}, {"de": "Er sucht eine professionelle Beratung in Steuerfragen.", "en": "He is looking for professional advice on tax matters."}]},
  {id:998,german:"die Betreuung",level:"B2",english:"care, supervision",pos:"noun (f)",sentences:[{"de": "Die Betreuung der Kinder während der Arbeitszeit ist gut organisiert.", "en": "The supervision of children during working hours is well organised."}, {"de": "Das Unternehmen bietet eine individuelle Betreuung seiner Kunden an.", "en": "The company offers individual care for its customers."}]},
  {id:999,german:"die Branche",level:"B2",english:"industry sector, branch",pos:"noun (f)",sentences:[{"de": "Die Technologiebranche wächst seit Jahren besonders schnell.", "en": "The technology sector has been growing particularly fast for years."}, {"de": "Er möchte in eine andere Branche wechseln und Neues lernen.", "en": "He would like to move to a different industry sector and learn new things."}]},
  {id:1000,german:"der Betrieb",level:"B2",english:"business, company, operation",pos:"noun (m)",sentences:[{"de": "Der Betrieb beschäftigt über zweihundert Mitarbeiter.", "en": "The company employs over two hundred employees."}, {"de": "Die Maschine ist außer Betrieb und muss repariert werden.", "en": "The machine is out of operation and needs to be repaired."}]},
  {id:1001,german:"der Familienbetrieb",level:"B2",english:"family business",pos:"noun (m)",sentences:[{"de": "Der Familienbetrieb wird seit drei Generationen von derselben Familie geführt.", "en": "The family business has been run by the same family for three generations."}, {"de": "Sie möchte den Familienbetrieb ihrer Eltern irgendwann übernehmen.", "en": "She would like to take over her parents' family business someday."}]},
  {id:1002,german:"die Hilfsorganisation",level:"B2",english:"aid organisation, charity",pos:"noun (f)",sentences:[{"de": "Die Hilfsorganisation verteilt Lebensmittel an bedürftige Familien.", "en": "The aid organisation distributes food to families in need."}, {"de": "Er spendet jeden Monat einen Teil seines Gehalts an eine Hilfsorganisation.", "en": "He donates a part of his salary to a charity every month."}]},
  {id:1003,german:"das internationale Unternehmen",level:"B2",english:"international company",pos:"noun (n)",sentences:[{"de": "Das internationale Unternehmen hat Niederlassungen in über fünfzig Ländern.", "en": "The international company has branches in over fifty countries."}, {"de": "Sie bewirbt sich um eine Stelle bei einem internationalen Unternehmen.", "en": "She is applying for a position at an international company."}]},
  {id:1004,german:"die Lebensmittelbranche",level:"B2",english:"food industry",pos:"noun (f)",sentences:[{"de": "Die Lebensmittelbranche steht vor großen Herausforderungen durch steigende Rohstoffpreise.", "en": "The food industry faces major challenges due to rising raw material prices."}, {"de": "Er hat nach seinem Studium in der Lebensmittelbranche angefangen zu arbeiten.", "en": "He started working in the food industry after his studies."}]},
  {id:1005,german:"der Malerbetrieb",level:"B2",english:"painting company",pos:"noun (m)",sentences:[{"de": "Der Malerbetrieb wurde vor zwanzig Jahren von seinem Vater gegründet.", "en": "The painting company was founded by his father twenty years ago."}, {"de": "Wir haben einen lokalen Malerbetrieb beauftragt, die Wohnung zu streichen.", "en": "We hired a local painting company to paint the flat."}]},
  {id:1006,german:"der soziale Bereich",level:"B2",english:"social sector",pos:"noun (m)",sentences:[{"de": "Viele junge Menschen möchten im sozialen Bereich arbeiten und anderen helfen.", "en": "Many young people want to work in the social sector and help others."}, {"de": "Im sozialen Bereich sind die Gehälter oft niedriger als in der Privatwirtschaft.", "en": "Salaries in the social sector are often lower than in the private sector."}]},
  {id:1007,german:"beschäftigen",level:"B2",english:"to employ, to occupy",pos:"verb",sentences:[{"de": "Das Unternehmen beschäftigt mehr als tausend Mitarbeiter weltweit.", "en": "The company employs more than a thousand employees worldwide."}, {"de": "Das Thema beschäftigt mich schon seit Wochen.", "en": "The topic has been occupying my mind for weeks."}]},
  {id:1008,german:"produzieren",level:"B2",english:"to produce, to manufacture",pos:"verb",sentences:[{"de": "Das Werk produziert täglich Tausende von Fahrzeugteilen.", "en": "The factory produces thousands of vehicle parts daily."}, {"de": "Sie produzieren ihre Waren ausschließlich aus nachhaltigen Materialien.", "en": "They manufacture their goods exclusively from sustainable materials."}]},
  {id:1009,german:"geistig",level:"B2",english:"mental, intellectual",pos:"adjective",sentences:[{"de": "Geistige Arbeit erfordert ebenso viel Energie wie körperliche Arbeit.", "en": "Intellectual work requires just as much energy as physical work."}, {"de": "Er hält sich durch regelmäßiges Lesen geistig fit.", "en": "He keeps himself mentally fit through regular reading."}]},
  {id:1010,german:"handwerklich",level:"B2",english:"manual, craft-related",pos:"adjective",sentences:[{"de": "Sie hat ein großes handwerkliches Geschick und repariert vieles selbst.", "en": "She has great manual skill and repairs many things herself."}, {"de": "Der handwerkliche Beruf erfordert eine solide Ausbildung.", "en": "The craft-related profession requires solid training."}]},
  {id:1011,german:"sozial",level:"B2",english:"social",pos:"adjective",sentences:[{"de": "Soziale Kompetenz ist im Berufsleben sehr wichtig.", "en": "Social competence is very important in professional life."}, {"de": "Das Unternehmen engagiert sich stark in sozialen Projekten.", "en": "The company is strongly involved in social projects."}]},
  {id:1012,german:"die Grundschule",level:"B2",english:"primary school, elementary school",pos:"noun (f)",sentences:[{"de": "Kinder besuchen in Deutschland ab dem sechsten Lebensjahr die Grundschule.", "en": "In Germany, children attend primary school from the age of six."}, {"de": "Sie arbeitet als Lehrerin an einer Grundschule in ihrer Heimatstadt.", "en": "She works as a teacher at a primary school in her hometown."}]},
  {id:1013,german:"die weiterführende Schule",level:"B2",english:"secondary school",pos:"noun (f)",sentences:[{"de": "Nach der Grundschule wechseln die Kinder auf eine weiterführende Schule.", "en": "After primary school, children move on to a secondary school."}, {"de": "Die Wahl der weiterführenden Schule ist für viele Familien eine wichtige Entscheidung.", "en": "The choice of secondary school is an important decision for many families."}]},
  {id:1014,german:"die Hauptschule",level:"B2",english:"lower secondary school",pos:"noun (f)",sentences:[{"de": "Die Hauptschule bereitet Schüler auf eine praktische Berufsausbildung vor.", "en": "The lower secondary school prepares students for practical vocational training."}, {"de": "Er hat die Hauptschule mit einem guten Abschluss beendet.", "en": "He finished lower secondary school with a good certificate."}]},
  {id:1015,german:"die Mittelschule",level:"B2",english:"middle school",pos:"noun (f)",sentences:[{"de": "Die Mittelschule ist in Bayern die Bezeichnung für die Hauptschule.", "en": "In Bavaria, the middle school is the term used for the lower secondary school."}, {"de": "Sie hat an der Mittelschule einen guten Notendurchschnitt erreicht.", "en": "She achieved a good grade average at middle school."}]},
  {id:1016,german:"die Realschule",level:"B2",english:"intermediate secondary school",pos:"noun (f)",sentences:[{"de": "Die Realschule bietet einen mittleren Bildungsabschluss nach zehn Schuljahren.", "en": "The intermediate secondary school offers a mid-level educational qualification after ten school years."}, {"de": "Nach der Realschule kann man eine Berufsausbildung beginnen oder das Abitur nachmachen.", "en": "After intermediate secondary school, one can begin vocational training or go on to take the A-level equivalent."}]},
  {id:1017,german:"die Gesamtschule",level:"B2",english:"comprehensive school",pos:"noun (f)",sentences:[{"de": "An der Gesamtschule lernen Schüler unterschiedlicher Leistungsniveaus gemeinsam.", "en": "At the comprehensive school, students of different ability levels learn together."}, {"de": "Die Gesamtschule bietet sowohl den Hauptschulabschluss als auch das Abitur an.", "en": "The comprehensive school offers both the lower secondary certificate and the A-level equivalent."}]},
  {id:1018,german:"das Gymnasium",level:"B2",english:"grammar school, academic high school",pos:"noun (n)",sentences:[{"de": "Das Gymnasium dauert in Deutschland in der Regel acht oder neun Jahre.", "en": "In Germany, grammar school usually lasts eight or nine years."}, {"de": "Sie besucht das Gymnasium und möchte danach Medizin studieren.", "en": "She attends grammar school and would like to study medicine afterwards."}]},
  {id:1019,german:"der Haupt-/Realschulabschluss",level:"B2",english:"school-leaving certificate",pos:"noun (m)",sentences:[{"de": "Mit einem Realschulabschluss hat man gute Chancen auf eine Ausbildungsstelle.", "en": "With a secondary school leaving certificate, one has good chances of getting an apprenticeship."}, {"de": "Er hat seinen Hauptschulabschluss nachgeholt, um bessere Berufschancen zu haben.", "en": "He took his lower secondary school leaving certificate later to improve his career prospects."}]},
  {id:1020,german:"das Abitur",level:"B2",english:"school-leaving exam (A-levels equivalent)",pos:"noun (n)",sentences:[{"de": "Das Abitur ist die Voraussetzung für ein Studium an einer deutschen Universität.", "en": "The Abitur is the prerequisite for studying at a German university."}, {"de": "Sie hat ihr Abitur mit einem Notendurchschnitt von 1,5 bestanden.", "en": "She passed her Abitur with a grade average of 1.5."}]},
  {id:1021,german:"die Universität",level:"B2",english:"university",pos:"noun (f)",sentences:[{"de": "Er studiert Rechtswissenschaften an der Universität München.", "en": "He studies law at the University of Munich."}, {"de": "Die Universität bietet zahlreiche internationale Austauschprogramme an.", "en": "The university offers numerous international exchange programmes."}]},
  {id:1022,german:"die Hochschule",level:"B2",english:"university, higher education institution",pos:"noun (f)",sentences:[{"de": "Sie hat an einer privaten Hochschule ihren Bachelorabschluss gemacht.", "en": "She completed her bachelor's degree at a private higher education institution."}, {"de": "Die Hochschule kooperiert eng mit der lokalen Wirtschaft.", "en": "The university of higher education cooperates closely with the local economy."}]},
  {id:1023,german:"die Fachhochschule",level:"B2",english:"university of applied sciences",pos:"noun (f)",sentences:[{"de": "An der Fachhochschule legt man großen Wert auf praxisorientiertes Lernen.", "en": "At the university of applied sciences, great importance is placed on practice-oriented learning."}, {"de": "Er studiert Informatik an einer renommierten Fachhochschule.", "en": "He studies computer science at a renowned university of applied sciences."}]},
  {id:1024,german:"die Berufsschule",level:"B2",english:"vocational school",pos:"noun (f)",sentences:[{"de": "Auszubildende besuchen die Berufsschule an ein oder zwei Tagen pro Woche.", "en": "Apprentices attend vocational school one or two days per week."}, {"de": "Die Berufsschule vermittelt sowohl theoretisches als auch praktisches Wissen.", "en": "The vocational school imparts both theoretical and practical knowledge."}]},
  {id:1025,german:"die Berufsausbildung",level:"B2",english:"vocational training, apprenticeship",pos:"noun (f)",sentences:[{"de": "Eine solide Berufsausbildung ist oft der erste Schritt in eine erfolgreiche Karriere.", "en": "A solid vocational training is often the first step towards a successful career."}, {"de": "Sie hat ihre Berufsausbildung zur Köchin in einem Sternerestaurant gemacht.", "en": "She completed her vocational training as a chef in a starred restaurant."}]},
  {id:1026,german:"der Ausbildungsberuf",level:"B2",english:"apprenticeship trade, training occupation",pos:"noun (m)",sentences:[{"de": "In Deutschland gibt es über dreihundert anerkannte Ausbildungsberufe.", "en": "In Germany there are over three hundred recognised apprenticeship trades."}, {"de": "Er überlegt, welcher Ausbildungsberuf am besten zu seinen Interessen passt.", "en": "He is considering which apprenticeship trade best matches his interests."}]},
  {id:1027,german:"der Ausbildungsvertrag",level:"B2",english:"training contract, apprenticeship contract",pos:"noun (m)",sentences:[{"de": "Vor Beginn der Ausbildung müssen beide Seiten den Ausbildungsvertrag unterschreiben.", "en": "Before training begins, both parties must sign the apprenticeship contract."}, {"de": "Im Ausbildungsvertrag sind Rechte und Pflichten des Auszubildenden festgelegt.", "en": "The training contract sets out the rights and duties of the apprentice."}]},
  {id:1028,german:"der Ausbildungsbetrieb",level:"B2",english:"training company",pos:"noun (m)",sentences:[{"de": "Der Ausbildungsbetrieb ist für die praktische Ausbildung des Azubis verantwortlich.", "en": "The training company is responsible for the practical training of the apprentice."}, {"de": "Sie hat einen Ausbildungsvertrag mit einem mittelständischen Ausbildungsbetrieb abgeschlossen.", "en": "She signed a training contract with a medium-sized training company."}]},
  {id:1029,german:"das Zeugnis",level:"B2",english:"certificate, report card, reference",pos:"noun (n)",sentences:[{"de": "Sie hat ihr Abschlusszeugnis mit Auszeichnung erhalten.", "en": "She received her final certificate with distinction."}, {"de": "Für die Bewerbung benötigt man ein aktuelles Zeugnis vom letzten Arbeitgeber.", "en": "For the application, a current reference from the last employer is required."}]},
  {id:1030,german:"die Note",level:"B2",english:"grade, mark",pos:"noun (f)",sentences:[{"de": "Er hat in Mathematik die beste Note in seiner Klasse bekommen.", "en": "He got the best grade in his class in mathematics."}, {"de": "Die Note im Abschlusszeugnis ist für viele Arbeitgeber wichtig.", "en": "The grade on the final certificate is important for many employers."}]},
  {id:1031,german:"der Notendurchschnitt",level:"B2",english:"grade average",pos:"noun (m)",sentences:[{"de": "Ihr Notendurchschnitt liegt bei 1,8, was sehr gut ist.", "en": "Her grade average is 1.8, which is very good."}, {"de": "Ein guter Notendurchschnitt erhöht die Chancen auf einen Studienplatz.", "en": "A good grade average increases the chances of getting a university place."}]},
  {id:1032,german:"das Schulfach",level:"B2",english:"school subject",pos:"noun (n)",sentences:[{"de": "Sein Lieblingsschulfach ist Biologie, weil er die Natur liebt.", "en": "His favourite school subject is biology because he loves nature."}, {"de": "In Deutschland gibt es in jedem Bundesland etwas unterschiedliche Schulfächer.", "en": "In Germany, the school subjects vary slightly from state to state."}]},
  {id:1033,german:"die Fremdsprache",level:"B2",english:"foreign language",pos:"noun (f)",sentences:[{"de": "Das Erlernen einer Fremdsprache eröffnet viele berufliche Möglichkeiten.", "en": "Learning a foreign language opens up many professional opportunities."}, {"de": "Sie spricht drei Fremdsprachen fließend: Englisch, Französisch und Spanisch.", "en": "She speaks three foreign languages fluently: English, French and Spanish."}]},
  {id:1034,german:"die Muttersprache",level:"B2",english:"mother tongue, native language",pos:"noun (f)",sentences:[{"de": "Seine Muttersprache ist Türkisch, aber er spricht Deutsch wie ein Muttersprachler.", "en": "His mother tongue is Turkish, but he speaks German like a native speaker."}, {"de": "Es ist wichtig, die Muttersprache gut zu beherrschen, bevor man Fremdsprachen lernt.", "en": "It is important to master one's native language well before learning foreign languages."}]},
  {id:1035,german:"die Sprachkenntnisse",level:"B2",english:"language skills",pos:"noun (pl)",sentences:[{"de": "Gute Sprachkenntnisse in Englisch sind in vielen Berufen unerlässlich.", "en": "Good language skills in English are indispensable in many professions."}, {"de": "Sie hat ihre Sprachkenntnisse durch einen Auslandsaufenthalt erheblich verbessert.", "en": "She significantly improved her language skills during a stay abroad."}]},
  {id:1036,german:"das Sprachniveau",level:"B2",english:"language level",pos:"noun (n)",sentences:[{"de": "Das Sprachniveau wird nach dem Gemeinsamen Europäischen Referenzrahmen von A1 bis C2 eingeteilt.", "en": "The language level is classified according to the Common European Framework of Reference from A1 to C2."}, {"de": "Für diese Stelle wird ein Sprachniveau von mindestens B2 in Englisch vorausgesetzt.", "en": "For this position, a language level of at least B2 in English is required."}]},
  {id:1037,german:"die Weiterbildung",level:"B2",english:"further education, professional development",pos:"noun (f)",sentences:[{"de": "Regelmäßige Weiterbildung ist wichtig, um im Beruf auf dem neuesten Stand zu bleiben.", "en": "Regular professional development is important to stay up to date in one's career."}, {"de": "Das Unternehmen fördert die Weiterbildung seiner Mitarbeiter durch Kursangebote.", "en": "The company supports the further education of its employees through course offerings."}]},
  {id:1038,german:"das Fernstudium",level:"B2",english:"distance learning",pos:"noun (n)",sentences:[{"de": "Das Fernstudium ermöglicht es Berufstätigen, neben der Arbeit einen Abschluss zu machen.", "en": "Distance learning enables working professionals to obtain a qualification alongside their job."}, {"de": "Sie hat ihren Masterabschluss durch ein Fernstudium erworben.", "en": "She obtained her master's degree through distance learning."}]},
  {id:1039,german:"der Abschluss",level:"B2",english:"degree, qualification, completion",pos:"noun (m)",sentences:[{"de": "Er hat seinen Abschluss in Wirtschaftswissenschaften mit Auszeichnung bestanden.", "en": "He passed his degree in economics with distinction."}, {"de": "Ohne einen formalen Abschluss ist die Jobsuche oft schwieriger.", "en": "Without a formal qualification, the job search is often more difficult."}]},
  {id:1040,german:"der Studiengang",level:"B2",english:"course of study, degree programme",pos:"noun (m)",sentences:[{"de": "Sie hat sich für einen Studiengang in Umweltwissenschaften eingeschrieben.", "en": "She has enrolled in a degree programme in environmental sciences."}, {"de": "Der Studiengang Maschinenbau ist an dieser Universität besonders beliebt.", "en": "The mechanical engineering degree programme is particularly popular at this university."}]},
  {id:1041,german:"die Zulassung",level:"B2",english:"admission, approval",pos:"noun (f)",sentences:[{"de": "Die Zulassung zum Medizinstudium ist sehr begrenzt und umkämpft.", "en": "Admission to medical school is very limited and competitive."}, {"de": "Er hat die Zulassung für seinen Wunschstudiengang erhalten.", "en": "He has received admission for his preferred degree programme."}]},
  {id:1042,german:"der Numerus clausus",level:"B2",english:"numerus clausus, grade threshold for university",pos:"noun (m)",sentences:[{"de": "Der Numerus clausus für Medizin liegt in Deutschland bei etwa 1,0.", "en": "The numerus clausus for medicine in Germany is around 1.0."}, {"de": "Wegen des hohen Numerus clausus muss sie ein Wartesemester einplanen.", "en": "Because of the high numerus clausus, she has to plan for a waiting semester."}]},
  {id:1043,german:"die Zugangsvoraussetzung",level:"B2",english:"admission requirement",pos:"noun (f)",sentences:[{"de": "Eine der Zugangsvoraussetzungen für diesen Studiengang ist das Abitur.", "en": "One of the admission requirements for this degree programme is the Abitur."}, {"de": "Er erfüllt alle Zugangsvoraussetzungen für die angestrebte Stelle.", "en": "He meets all the admission requirements for the position he is aiming for."}]},
  {id:1044,german:"die staatliche Ausbildung",level:"B2",english:"state-funded training",pos:"noun (f)",sentences:[{"de": "Die staatliche Ausbildung zum Erzieher dauert in der Regel drei Jahre.", "en": "State-funded training as a childcare worker usually lasts three years."}, {"de": "Durch staatliche Ausbildung werden viele Fachkräfte im Gesundheitswesen ausgebildet.", "en": "Many skilled workers in the healthcare sector are trained through state-funded training."}]},
  {id:1045,german:"der Lehrplan",level:"B2",english:"curriculum, syllabus",pos:"noun (m)",sentences:[{"de": "Der Lehrplan legt fest, welche Inhalte in den einzelnen Schuljahren unterrichtet werden.", "en": "The curriculum specifies what content is taught in each school year."}, {"de": "Die Schule hat ihren Lehrplan um neue Medien und digitale Kompetenzen erweitert.", "en": "The school has expanded its curriculum to include new media and digital skills."}]},
  {id:1046,german:"die Stundentafel",level:"B2",english:"timetable, lesson schedule",pos:"noun (f)",sentences:[{"de": "Die Stundentafel zeigt, wie viele Stunden pro Woche jedes Fach unterrichtet wird.", "en": "The lesson schedule shows how many hours per week each subject is taught."}, {"de": "Laut der neuen Stundentafel wird Informatik jetzt auch in der Grundschule unterrichtet.", "en": "According to the new lesson schedule, computer science is now also taught in primary school."}]},
  {id:1047,german:"das Pflichtfach",level:"B2",english:"compulsory subject",pos:"noun (n)",sentences:[{"de": "Mathematik ist ein Pflichtfach in allen deutschen Schulen.", "en": "Mathematics is a compulsory subject in all German schools."}, {"de": "Sport als Pflichtfach zu haben ist für die körperliche Entwicklung der Schüler wichtig.", "en": "Having physical education as a compulsory subject is important for students' physical development."}]},
  {id:1048,german:"das Wahlfach",level:"B2",english:"elective subject, optional subject",pos:"noun (n)",sentences:[{"de": "Als Wahlfach hat er Chinesisch gewählt, weil er sich für die Sprache interessiert.", "en": "As an elective, he chose Chinese because he is interested in the language."}, {"de": "Die Schule bietet eine breite Auswahl an Wahlfächern an.", "en": "The school offers a wide range of optional subjects."}]},
  {id:1049,german:"das Stipendium",level:"B2",english:"scholarship, grant",pos:"noun (n)",sentences:[{"de": "Sie hat ein Stipendium erhalten, das ihr das Studium im Ausland ermöglicht.", "en": "She received a scholarship that enables her to study abroad."}, {"de": "Für das Stipendium muss man hervorragende akademische Leistungen nachweisen.", "en": "To receive the scholarship, one must demonstrate outstanding academic performance."}]},
  {id:1050,german:"der/die Auszubildende",level:"B2",english:"trainee, apprentice",pos:"noun (m/f)",sentences:[{"de": "Der Auszubildende lernt im Betrieb die praktischen Seiten seines Berufs kennen.", "en": "The apprentice gets to know the practical aspects of his profession in the company."}, {"de": "Die Auszubildende ist sehr engagiert und zeigt großes Interesse an ihrem Beruf.", "en": "The trainee is very dedicated and shows great interest in her profession."}]},
  {id:1051,german:"die Probezeit",level:"B2",english:"probationary period, trial period",pos:"noun (f)",sentences:[{"de": "Während der Probezeit können sowohl Arbeitnehmer als auch Arbeitgeber das Arbeitsverhältnis kurzfristig kündigen.", "en": "During the probationary period, both employees and employers can terminate the employment relationship at short notice."}, {"de": "Sie hat die Probezeit erfolgreich bestanden und wurde fest eingestellt.", "en": "She successfully completed her probationary period and was taken on permanently."}]},
  {id:1052,german:"die Ausbildungsvergütung",level:"B2",english:"training allowance, apprentice pay",pos:"noun (f)",sentences:[{"de": "Die Ausbildungsvergütung steigt in Deutschland seit Jahren kontinuierlich an.", "en": "The training allowance has been rising continuously in Germany for years."}, {"de": "Mit der Ausbildungsvergütung kann er seine Fahrtkosten und einen Teil der Miete bezahlen.", "en": "With the training allowance, he can pay his travel costs and part of the rent."}]},
  {id:1053,german:"das Berufsfeld",level:"B2",english:"occupational field",pos:"noun (n)",sentences:[{"de": "Das Berufsfeld der Informationstechnologie bietet viele Möglichkeiten für Absolventen.", "en": "The occupational field of information technology offers many opportunities for graduates."}, {"de": "Sie möchte ihr Berufsfeld wechseln und eine neue Ausbildung beginnen.", "en": "She would like to change her occupational field and start a new training."}]},
  {id:1054,german:"die Berufsorientierung",level:"B2",english:"career guidance, vocational orientation",pos:"noun (f)",sentences:[{"de": "Die Berufsorientierung in der Schule hilft Schülern, den richtigen Ausbildungsweg zu finden.", "en": "Career guidance at school helps students to find the right training path."}, {"de": "Er hat an einem Berufsorientierungsprogramm teilgenommen, um seine Stärken zu entdecken.", "en": "He participated in a career guidance programme to discover his strengths."}]},
  {id:1055,german:"das Praktikum",level:"B2",english:"internship, work placement",pos:"noun (n)",sentences:[{"de": "Ein Praktikum gibt einem die Möglichkeit, erste Berufserfahrungen zu sammeln.", "en": "An internship gives one the opportunity to gain initial professional experience."}, {"de": "Sie absolviert gerade ein sechswöchiges Praktikum in einem Architekturbüro.", "en": "She is currently completing a six-week internship at an architecture firm."}]},
  {id:1056,german:"der/die Praktikant/-in",level:"B2",english:"intern, trainee",pos:"noun (m/f)",sentences:[{"de": "Der Praktikant unterstützt das Team bei verschiedenen Projekten.", "en": "The intern supports the team with various projects."}, {"de": "Die Praktikantin hat während ihres Praktikums wertvolle Erfahrungen gesammelt.", "en": "The intern gained valuable experience during her work placement."}]},
  {id:1057,german:"die Bewerbung",level:"B2",english:"application, job application",pos:"noun (f)",sentences:[{"de": "Er hat bereits zwanzig Bewerbungen abgeschickt und wartet auf Antworten.", "en": "He has already sent out twenty applications and is waiting for replies."}, {"de": "Eine gute Bewerbung sollte ein Anschreiben und einen Lebenslauf enthalten.", "en": "A good job application should include a cover letter and a CV."}]},
  {id:1058,german:"das Anschreiben",level:"B2",english:"cover letter",pos:"noun (n)",sentences:[{"de": "Das Anschreiben ist oft das erste, was ein Arbeitgeber von einem Bewerber liest.", "en": "The cover letter is often the first thing an employer reads from an applicant."}, {"de": "Sie hat ihr Anschreiben individuell auf jede Stelle zugeschnitten.", "en": "She tailored her cover letter individually to each position."}]},
  {id:1059,german:"der Lebenslauf",level:"B2",english:"CV, curriculum vitae",pos:"noun (m)",sentences:[{"de": "Sein Lebenslauf zeigt eine beeindruckende Liste von Qualifikationen und Erfahrungen.", "en": "His CV shows an impressive list of qualifications and experiences."}, {"de": "Der Lebenslauf sollte übersichtlich und klar strukturiert sein.", "en": "The CV should be clear and well structured."}]},
  {id:1060,german:"das Vorstellungsgespräch",level:"B2",english:"job interview",pos:"noun (n)",sentences:[{"de": "Sie hat sich gut auf das Vorstellungsgespräch vorbereitet und die Stelle bekommen.", "en": "She prepared well for the job interview and got the position."}, {"de": "Im Vorstellungsgespräch sollte man authentisch und selbstbewusst auftreten.", "en": "In a job interview, one should present oneself authentically and confidently."}]},
  {id:1061,german:"die Gehaltsvorstellung",level:"B2",english:"salary expectation",pos:"noun (f)",sentences:[{"de": "Im Vorstellungsgespräch wurde er nach seinen Gehaltsvorstellungen gefragt.", "en": "In the job interview, he was asked about his salary expectations."}, {"de": "Ihre Gehaltsvorstellungen lagen leider über dem Budget des Unternehmens.", "en": "Unfortunately, her salary expectations were above the company's budget."}]},
  {id:1062,german:"die Einstellung",level:"B2",english:"hiring, employment; attitude",pos:"noun (f)",sentences:[{"de": "Die Einstellung neuer Mitarbeiter ist derzeit aufgrund des Budgets eingefroren.", "en": "The hiring of new employees is currently frozen due to the budget."}, {"de": "Eine positive Einstellung zur Arbeit ist für den Erfolg im Beruf entscheidend.", "en": "A positive attitude towards work is crucial for success in a career."}]},
  {id:1063,german:"die Kündigung",level:"B2",english:"dismissal, notice, termination",pos:"noun (f)",sentences:[{"de": "Er hat nach zehn Jahren seine Kündigung eingereicht, um ein eigenes Unternehmen zu gründen.", "en": "After ten years, he handed in his notice to start his own company."}, {"de": "Die Kündigung muss schriftlich und fristgerecht erfolgen.", "en": "The termination must be submitted in writing and within the notice period."}]},
  {id:1064,german:"die Abfindung",level:"B2",english:"severance pay, redundancy payment",pos:"noun (f)",sentences:[{"de": "Nach der Entlassung hat er eine großzügige Abfindung erhalten.", "en": "After being made redundant, he received a generous severance payment."}, {"de": "Die Abfindung soll den Verlust des Arbeitsplatzes teilweise ausgleichen.", "en": "The redundancy payment is intended to partially compensate for the loss of the job."}]},
  {id:1065,german:"die Versicherung",level:"B2",english:"insurance",pos:"noun (f)",sentences:[{"de": "Eine Haftpflichtversicherung ist in Deutschland sehr empfehlenswert.", "en": "Third-party liability insurance is highly recommended in Germany."}, {"de": "Er hat seine Versicherung gewechselt, weil die neue günstiger ist.", "en": "He changed his insurance because the new one is cheaper."}]},
  {id:1066,german:"die Rentenversicherung",level:"B2",english:"pension insurance",pos:"noun (f)",sentences:[{"de": "Jeder Arbeitnehmer in Deutschland ist verpflichtet, in die Rentenversicherung einzuzahlen.", "en": "Every employee in Germany is obliged to pay into pension insurance."}, {"de": "Die Rentenversicherung soll im Alter eine finanzielle Grundsicherung bieten.", "en": "Pension insurance is intended to provide basic financial security in old age."}]},
  {id:1067,german:"die Krankenversicherung",level:"B2",english:"health insurance",pos:"noun (f)",sentences:[{"de": "In Deutschland ist die Krankenversicherung für alle Einwohner Pflicht.", "en": "In Germany, health insurance is compulsory for all residents."}, {"de": "Sie ist privat krankenversichert und hat damit kürzere Wartezeiten beim Arzt.", "en": "She has private health insurance and therefore has shorter waiting times at the doctor's."}]},
  {id:1068,german:"die Pflegeversicherung",level:"B2",english:"long-term care insurance",pos:"noun (f)",sentences:[{"de": "Die Pflegeversicherung übernimmt einen Teil der Kosten für die Pflege im Alter.", "en": "Long-term care insurance covers part of the costs of care in old age."}, {"de": "Der Beitrag zur Pflegeversicherung wird automatisch vom Gehalt abgezogen.", "en": "The long-term care insurance contribution is automatically deducted from the salary."}]},
  {id:1069,german:"die Arbeitslosenversicherung",level:"B2",english:"unemployment insurance",pos:"noun (f)",sentences:[{"de": "Die Arbeitslosenversicherung zahlt bei Jobverlust Arbeitslosengeld für eine begrenzte Zeit.", "en": "Unemployment insurance pays unemployment benefit for a limited time when a job is lost."}, {"de": "Beide Arbeitgeber und Arbeitnehmer zahlen in die Arbeitslosenversicherung ein.", "en": "Both employers and employees contribute to unemployment insurance."}]},
  {id:1070,german:"die Sozialversicherung",level:"B2",english:"social insurance",pos:"noun (f)",sentences:[{"de": "Die Sozialversicherung umfasst Kranken-, Pflege-, Renten- und Arbeitslosenversicherung.", "en": "Social insurance encompasses health, long-term care, pension and unemployment insurance."}, {"de": "Jeder Arbeitnehmer ist automatisch in das deutsche Sozialversicherungssystem eingegliedert.", "en": "Every employee is automatically integrated into the German social insurance system."}]},
  {id:1071,german:"der Beitrag",level:"B2",english:"contribution, fee, premium",pos:"noun (m)",sentences:[{"de": "Der monatliche Beitrag zur Krankenversicherung hängt vom Einkommen ab.", "en": "The monthly health insurance contribution depends on income."}, {"de": "Sie leistet mit ihrer ehrenamtlichen Arbeit einen wichtigen Beitrag zur Gesellschaft.", "en": "She makes an important contribution to society through her voluntary work."}]},
  {id:1072,german:"die Pflichtversicherung",level:"B2",english:"compulsory insurance",pos:"noun (f)",sentences:[{"de": "Die Kfz-Haftpflichtversicherung ist in Deutschland eine Pflichtversicherung.", "en": "Third-party motor vehicle insurance is a compulsory insurance in Germany."}, {"de": "Als Arbeitnehmer sind Sie automatisch in der Pflichtversicherung erfasst.", "en": "As an employee, you are automatically included in compulsory insurance."}]},
  {id:1073,german:"der Arbeitnehmer",level:"B2",english:"employee, worker",pos:"noun (m)",sentences:[{"de": "Der Arbeitnehmer hat das Recht auf mindestens vier Wochen Urlaub im Jahr.", "en": "The employee is entitled to at least four weeks of holiday per year."}, {"de": "Arbeitnehmer und Arbeitgeber teilen sich die Sozialversicherungsbeiträge.", "en": "Employees and employers share the social insurance contributions."}]},
  {id:1074,german:"der Arbeitgeber",level:"B2",english:"employer",pos:"noun (m)",sentences:[{"de": "Der Arbeitgeber ist verpflichtet, einen sicheren Arbeitsplatz bereitzustellen.", "en": "The employer is obliged to provide a safe workplace."}, {"de": "Gute Arbeitgeber kümmern sich um das Wohlbefinden ihrer Belegschaft.", "en": "Good employers take care of the well-being of their workforce."}]},
  {id:1075,german:"die Gewerkschaft",level:"B2",english:"trade union",pos:"noun (f)",sentences:[{"de": "Die Gewerkschaft verhandelt mit den Arbeitgebern über bessere Löhne und Arbeitsbedingungen.", "en": "The trade union negotiates with employers about better wages and working conditions."}, {"de": "Er ist seit Jahren Mitglied einer Gewerkschaft und nimmt aktiv an deren Arbeit teil.", "en": "He has been a member of a trade union for years and actively participates in its work."}]},
  {id:1076,german:"der Tarifvertrag",level:"B2",english:"collective agreement, wage agreement",pos:"noun (m)",sentences:[{"de": "Der Tarifvertrag regelt Löhne, Arbeitszeiten und Urlaubsansprüche in der Branche.", "en": "The collective agreement regulates wages, working hours and holiday entitlements in the sector."}, {"de": "Viele Arbeitnehmer profitieren von den im Tarifvertrag festgelegten Mindeststandards.", "en": "Many employees benefit from the minimum standards set out in the collective agreement."}]},
  {id:1077,german:"der Mindestlohn",level:"B2",english:"minimum wage",pos:"noun (m)",sentences:[{"de": "Der gesetzliche Mindestlohn wurde in Deutschland im Jahr 2015 eingeführt.", "en": "The statutory minimum wage was introduced in Germany in 2015."}, {"de": "Es wird diskutiert, ob der aktuelle Mindestlohn zum Leben ausreicht.", "en": "There is a debate as to whether the current minimum wage is sufficient to live on."}]},
  {id:1078,german:"die Überstunden",level:"B2",english:"overtime",pos:"noun (pl)",sentences:[{"de": "Er macht regelmäßig Überstunden, weil das Projekt unter Zeitdruck steht.", "en": "He regularly works overtime because the project is under time pressure."}, {"de": "Überstunden müssen entweder finanziell abgegolten oder als Freizeit ausgeglichen werden.", "en": "Overtime must either be financially compensated or taken as time off in lieu."}]},
  {id:1079,german:"die Gleitzeit",level:"B2",english:"flexitime, flexible working hours",pos:"noun (f)",sentences:[{"de": "Dank der Gleitzeit kann sie ihren Arbeitstag flexibel gestalten.", "en": "Thanks to flexitime, she can organise her working day flexibly."}, {"de": "Immer mehr Unternehmen bieten Gleitzeit als Alternative zur festen Arbeitszeit an.", "en": "More and more companies offer flexitime as an alternative to fixed working hours."}]},
  {id:1080,german:"die Teilzeit",level:"B2",english:"part-time",pos:"noun (f)",sentences:[{"de": "Sie arbeitet in Teilzeit, um mehr Zeit für ihre Familie zu haben.", "en": "She works part-time to have more time for her family."}, {"de": "Nach der Elternzeit ist er auf eine Teilzeitstelle zurückgekehrt.", "en": "After parental leave, he returned to a part-time position."}]},
  {id:1081,german:"die Vollzeit",level:"B2",english:"full-time",pos:"noun (f)",sentences:[{"de": "Nach dem Studium möchte er eine Vollzeitstelle in seiner Branche finden.", "en": "After his studies, he would like to find a full-time position in his sector."}, {"de": "Sie hat von Teilzeit auf Vollzeit gewechselt, seit die Kinder größer sind.", "en": "She switched from part-time to full-time once the children grew older."}]},
  {id:1082,german:"das Homeoffice",level:"B2",english:"home office, working from home",pos:"noun (n)",sentences:[{"de": "Seit der Pandemie arbeiten viele Menschen regelmäßig im Homeoffice.", "en": "Since the pandemic, many people regularly work from home."}, {"de": "Er schätzt das Homeoffice, weil er so lange Pendelzeiten vermeidet.", "en": "He appreciates working from home because he avoids long commuting times."}]},
  {id:1083,german:"die Dienstreise",level:"B2",english:"business trip",pos:"noun (f)",sentences:[{"de": "Sie ist diese Woche auf Dienstreise nach Wien.", "en": "She is on a business trip to Vienna this week."}, {"de": "Die Kosten für eine Dienstreise werden in der Regel vom Arbeitgeber übernommen.", "en": "The costs of a business trip are usually covered by the employer."}]},
  {id:1084,german:"die Geschäftsreise",level:"B2",english:"business trip",pos:"noun (f)",sentences:[{"de": "Er ist häufig auf Geschäftsreise und verbringt wenig Zeit zu Hause.", "en": "He is often on business trips and spends little time at home."}, {"de": "Die Geschäftsreise nach Japan war sehr erfolgreich und hat neue Kunden gebracht.", "en": "The business trip to Japan was very successful and brought new clients."}]},
  {id:1085,german:"die Jobmesse",level:"B2",english:"job fair, careers fair",pos:"noun (f)",sentences:[{"de": "Auf der Jobmesse konnten sich Bewerber direkt bei Unternehmen vorstellen.", "en": "At the careers fair, applicants were able to introduce themselves directly to companies."}, {"de": "Sie hat auf der Jobmesse wertvolle Kontakte geknüpft.", "en": "She made valuable contacts at the job fair."}]},
  {id:1086,german:"das Netzwerk",level:"B2",english:"network",pos:"noun (n)",sentences:[{"de": "Ein gutes berufliches Netzwerk kann bei der Jobsuche sehr hilfreich sein.", "en": "A good professional network can be very helpful when looking for a job."}, {"de": "Sie pflegt ihr Netzwerk regelmäßig durch Veranstaltungen und Social Media.", "en": "She regularly maintains her network through events and social media."}]},
  {id:1087,german:"die Karriere",level:"B2",english:"career",pos:"noun (f)",sentences:[{"de": "Er hat eine beeindruckende Karriere in der Finanzbranche gemacht.", "en": "He has had an impressive career in the financial sector."}, {"de": "Sie plant ihre Karriere langfristig und setzt sich klare Ziele.", "en": "She plans her career long-term and sets herself clear goals."}]},
  {id:1088,german:"der Aufstieg",level:"B2",english:"advancement, promotion, rise",pos:"noun (m)",sentences:[{"de": "Sein beruflicher Aufstieg ist das Ergebnis jahrelanger harter Arbeit.", "en": "His professional advancement is the result of years of hard work."}, {"de": "Der Aufstieg zum Abteilungsleiter war ein wichtiger Schritt in ihrer Karriere.", "en": "The rise to department head was an important step in her career."}]},
  {id:1089,german:"die Beförderung",level:"B2",english:"promotion",pos:"noun (f)",sentences:[{"de": "Nach drei Jahren hat er eine verdiente Beförderung zum Teamleiter erhalten.", "en": "After three years, he received a well-deserved promotion to team leader."}, {"de": "Sie hofft auf eine Beförderung, nachdem sie das große Projekt erfolgreich abgeschlossen hat.", "en": "She is hoping for a promotion after successfully completing the major project."}]},
  {id:1090,german:"die Stelle",level:"B2",english:"position, job, post",pos:"noun (f)",sentences:[{"de": "Er hat sich auf eine Stelle als Ingenieur in Hamburg beworben.", "en": "He has applied for a position as an engineer in Hamburg."}, {"de": "Die ausgeschriebene Stelle wurde intern besetzt.", "en": "The advertised post was filled internally."}]},
  {id:1091,german:"die Arbeitsstelle",level:"B2",english:"workplace, job",pos:"noun (f)",sentences:[{"de": "Seine neue Arbeitsstelle ist nur fünf Minuten von seiner Wohnung entfernt.", "en": "His new workplace is only five minutes from his flat."}, {"de": "Sie hat ihre Arbeitsstelle verloren und sucht jetzt eine neue.", "en": "She has lost her job and is now looking for a new one."}]},
  {id:1092,german:"der Putzlappen",level:"B2",english:"cleaning cloth, rag",pos:"noun (m)",sentences:[{"de": "Sie wischte den Tisch mit einem feuchten Putzlappen ab.", "en": "She wiped the table with a damp cleaning cloth."}, {"de": "Für gründliches Putzen braucht man verschiedene Arten von Putzlappen.", "en": "For thorough cleaning, you need different types of cleaning cloths."}]},
  {id:1093,german:"der Wischmopp",level:"B2",english:"mop",pos:"noun (m)",sentences:[{"de": "Mit dem Wischmopp lässt sich der Boden schnell und effizient reinigen.", "en": "With the mop, the floor can be cleaned quickly and efficiently."}, {"de": "Er hat einen neuen Wischmopp gekauft, weil der alte kaputt war.", "en": "He bought a new mop because the old one was broken."}]},
  {id:1094,german:"der Staubsauger",level:"B2",english:"vacuum cleaner",pos:"noun (m)",sentences:[{"de": "Der neue Staubsauger ist viel leiser als das alte Modell.", "en": "The new vacuum cleaner is much quieter than the old model."}, {"de": "Sie saugt jeden Samstag die ganze Wohnung mit dem Staubsauger durch.", "en": "She vacuums the entire flat with the vacuum cleaner every Saturday."}]},
  {id:1095,german:"das Putzmittel",level:"B2",english:"cleaning agent, detergent",pos:"noun (n)",sentences:[{"de": "Beim Einsatz von Putzmitteln sollte man immer die Anleitung lesen.", "en": "When using cleaning agents, one should always read the instructions."}, {"de": "Sie bevorzugt umweltfreundliche Putzmittel, die keine schädlichen Chemikalien enthalten.", "en": "She prefers environmentally friendly cleaning agents that contain no harmful chemicals."}]},
  {id:1096,german:"die Reinigungskraft",level:"B2",english:"cleaner, cleaning staff",pos:"noun (f)",sentences:[{"de": "Die Reinigungskraft kommt zweimal pro Woche, um das Büro zu reinigen.", "en": "The cleaner comes twice a week to clean the office."}, {"de": "Das Hotel beschäftigt über zwanzig Reinigungskräfte.", "en": "The hotel employs over twenty members of cleaning staff."}]},
  {id:1097,german:"der/die Hausmeister/-in",level:"B2",english:"caretaker, janitor",pos:"noun (m/f)",sentences:[{"de": "Der Hausmeister hat die defekte Heizung in unserem Keller repariert.", "en": "The caretaker repaired the broken heating in our cellar."}, {"de": "Die Hausmeisterin kümmert sich um die Instandhaltung des gesamten Wohnkomplexes.", "en": "The caretaker looks after the maintenance of the entire residential complex."}]},
  {id:1098,german:"die Reinigung",level:"B2",english:"cleaning, dry-cleaning",pos:"noun (f)",sentences:[{"de": "Die gründliche Reinigung des Büros dauert mehrere Stunden.", "en": "The thorough cleaning of the office takes several hours."}, {"de": "Er bringt seinen Anzug regelmäßig in die Reinigung.", "en": "He regularly takes his suit to the dry-cleaner's."}]},
  {id:1099,german:"der Haushaltsplan",level:"B2",english:"household budget, housekeeping plan",pos:"noun (m)",sentences:[{"de": "Mit einem guten Haushaltsplan behält man die Kontrolle über seine Ausgaben.", "en": "With a good household budget, one keeps control of one's expenditure."}, {"de": "Sie hat einen detaillierten Haushaltsplan erstellt, um jeden Monat Geld zu sparen.", "en": "She drew up a detailed household budget to save money each month."}]},
  {id:1100,german:"sauber machen",level:"B2",english:"to clean",pos:"verb",sentences:[{"de": "Sie macht jedes Wochenende die Küche gründlich sauber.", "en": "She thoroughly cleans the kitchen every weekend."}, {"de": "Es ist wichtig, das Badezimmer regelmäßig sauber zu machen.", "en": "It is important to clean the bathroom regularly."}]},
  {id:1101,german:"abstauben",level:"B2",english:"to dust",pos:"verb",sentences:[{"de": "Sie staubt jede Woche die Bücherregale und die Möbel ab.", "en": "She dusts the bookshelves and the furniture every week."}, {"de": "Vergiss nicht, auch hinter dem Sofa abzustauben.", "en": "Don't forget to dust behind the sofa too."}]},
  {id:1102,german:"wischen",level:"B2",english:"to wipe, to mop",pos:"verb",sentences:[{"de": "Er wischt den Boden nach dem Kochen immer gründlich.", "en": "He always mops the floor thoroughly after cooking."}, {"de": "Sie wischt die Tischoberfläche mit einem feuchten Tuch ab.", "en": "She wipes the table surface with a damp cloth."}]},
  {id:1103,german:"schrubben",level:"B2",english:"to scrub",pos:"verb",sentences:[{"de": "Er schrubbte den Badezimmerboden, bis er wieder glänzte.", "en": "He scrubbed the bathroom floor until it gleamed again."}, {"de": "Beim Schrubben der Töpfe sollte man Handschuhe tragen.", "en": "When scrubbing pots, one should wear gloves."}]},
  {id:1104,german:"aufräumen",level:"B2",english:"to tidy up, to clear up",pos:"verb",sentences:[{"de": "Die Kinder müssen ihr Zimmer aufräumen, bevor sie spielen dürfen.", "en": "The children have to tidy up their room before they are allowed to play."}, {"de": "Nach der Party haben sie stundenlang aufgeräumt.", "en": "After the party, they tidied up for hours."}]},
  {id:1105,german:"entsorgen",level:"B2",english:"to dispose of, to get rid of",pos:"verb",sentences:[{"de": "Alte Elektrogeräte dürfen nicht im normalen Hausmüll entsorgt werden.", "en": "Old electrical appliances must not be disposed of in normal household waste."}, {"de": "Er hat den kaputten Schrank fachgerecht entsorgt.", "en": "He properly disposed of the broken wardrobe."}]},
  {id:1106,german:"sortieren",level:"B2",english:"to sort",pos:"verb",sentences:[{"de": "Sie sortiert ihren Müll sorgfältig nach Glas, Papier und Plastik.", "en": "She carefully sorts her rubbish into glass, paper and plastic."}, {"de": "Die Pakete müssen nach Zielort sortiert werden, bevor sie versendet werden.", "en": "The packages must be sorted by destination before they are sent."}]},
  {id:1107,german:"lagern",level:"B2",english:"to store",pos:"verb",sentences:[{"de": "Lebensmittel sollten kühl und trocken gelagert werden.", "en": "Food should be stored in a cool and dry place."}, {"de": "Das Unternehmen lagert seine Waren in einem modernen Logistikzentrum.", "en": "The company stores its goods in a modern logistics centre."}]},
  {id:1108,german:"einlagern",level:"B2",english:"to store, to put into storage",pos:"verb",sentences:[{"de": "Er hat seine Winterreifen für den Sommer beim Reifenhändler eingelagert.", "en": "He put his winter tyres into storage at the tyre dealer's for the summer."}, {"de": "Die Firma hat große Mengen an Rohstoffen eingelagert, um Lieferengpässen vorzubeugen.", "en": "The company stored large quantities of raw materials to prevent supply bottlenecks."}]},
  {id:1109,german:"das Lager",level:"B2",english:"warehouse, stock, storage",pos:"noun (n)",sentences:[{"de": "Das Lager ist voll und es müssen neue Waren bestellt werden.", "en": "The warehouse is full and new goods need to be ordered."}, {"de": "Der Artikel ist leider nicht mehr auf Lager und muss nachbestellt werden.", "en": "Unfortunately, the item is no longer in stock and has to be reordered."}]},
  {id:1110,german:"der Lagerraum",level:"B2",english:"storage room",pos:"noun (m)",sentences:[{"de": "Im Keller befindet sich ein Lagerraum für Saisonware.", "en": "There is a storage room in the cellar for seasonal goods."}, {"de": "Der Lagerraum muss besser organisiert werden, damit man alles schnell findet.", "en": "The storage room needs to be better organised so that everything can be found quickly."}]},
  {id:1111,german:"die Lagerhaltung",level:"B2",english:"stock management, warehousing",pos:"noun (f)",sentences:[{"de": "Eine effiziente Lagerhaltung spart Kosten und verbessert die Lieferzeiten.", "en": "Efficient stock management saves costs and improves delivery times."}, {"de": "Das Unternehmen hat seine Lagerhaltung durch ein neues Softwaresystem optimiert.", "en": "The company has optimised its warehousing through a new software system."}]},
  {id:1112,german:"das Angebot",level:"B2",english:"offer, supply; menu",pos:"noun (n)",sentences:[{"de": "Das Angebot des Supermarkts ist sehr vielfältig und gut sortiert.", "en": "The supermarket's range is very diverse and well organised."}, {"de": "Er hat das Angebot des Arbeitgebers nach reiflicher Überlegung abgelehnt.", "en": "He declined the employer's offer after careful consideration."}]},
  {id:1113,german:"die Nachfrage",level:"B2",english:"demand",pos:"noun (f)",sentences:[{"de": "Die Nachfrage nach erneuerbaren Energien steigt weltweit.", "en": "The demand for renewable energy is increasing worldwide."}, {"de": "Bei hoher Nachfrage und geringem Angebot steigen die Preise.", "en": "When demand is high and supply is low, prices rise."}]},
  {id:1114,german:"der Markt",level:"B2",english:"market",pos:"noun (m)",sentences:[{"de": "Der europäische Markt bietet viele Chancen für neue Unternehmen.", "en": "The European market offers many opportunities for new companies."}, {"de": "Sie kauft frisches Gemüse und Obst jeden Samstag auf dem Markt.", "en": "She buys fresh vegetables and fruit at the market every Saturday."}]},
  {id:1115,german:"der Marktplatz",level:"B2",english:"marketplace, market square",pos:"noun (m)",sentences:[{"de": "Der historische Marktplatz ist das Zentrum der Altstadt.", "en": "The historic market square is the centre of the old town."}, {"de": "Online-Marktplätze haben den Handel grundlegend verändert.", "en": "Online marketplaces have fundamentally changed commerce."}]},
  {id:1116,german:"die Konkurrenz",level:"B2",english:"competition, competitors",pos:"noun (f)",sentences:[{"de": "Die Konkurrenz in der Technologiebranche ist sehr hart.", "en": "Competition in the technology sector is very fierce."}, {"de": "Das Unternehmen muss sich von der Konkurrenz abheben, um erfolgreich zu sein.", "en": "The company needs to stand out from the competition to be successful."}]},
  {id:1117,german:"der Wettbewerb",level:"B2",english:"competition",pos:"noun (m)",sentences:[{"de": "Fairer Wettbewerb fördert Innovation und niedrigere Preise für Verbraucher.", "en": "Fair competition promotes innovation and lower prices for consumers."}, {"de": "Sie hat am nationalen Wettbewerb für junge Unternehmer teilgenommen.", "en": "She participated in the national competition for young entrepreneurs."}]},
  {id:1118,german:"die Strategie",level:"B2",english:"strategy",pos:"noun (f)",sentences:[{"de": "Das Unternehmen braucht eine klare Strategie, um langfristig erfolgreich zu sein.", "en": "The company needs a clear strategy to be successful in the long term."}, {"de": "Sie hat eine neue Marketingstrategie entwickelt, die auf Social Media setzt.", "en": "She has developed a new marketing strategy that focuses on social media."}]},
  {id:1119,german:"das Marketing",level:"B2",english:"marketing",pos:"noun (n)",sentences:[{"de": "Effektives Marketing ist entscheidend für den Erfolg eines neuen Produkts.", "en": "Effective marketing is crucial for the success of a new product."}, {"de": "Er hat ein Studium im Bereich Marketing und Kommunikation abgeschlossen.", "en": "He completed a degree in marketing and communications."}]},
  {id:1120,german:"die Werbung",level:"B2",english:"advertising, advertisement",pos:"noun (f)",sentences:[{"de": "Werbung im Fernsehen ist nach wie vor eine der wirkungsvollsten Formen der Werbung.", "en": "Television advertising remains one of the most effective forms of advertising."}, {"de": "Das Unternehmen hat viel Geld in die Werbung für sein neues Produkt investiert.", "en": "The company has invested a lot of money in advertising for its new product."}]},
  {id:1121,german:"die Kampagne",level:"B2",english:"campaign",pos:"noun (f)",sentences:[{"de": "Die Werbekampagne hat die Markenbekanntheit deutlich gesteigert.", "en": "The advertising campaign significantly increased brand awareness."}, {"de": "Die Kampagne für mehr Umweltbewusstsein hat viele Menschen erreicht.", "en": "The campaign for greater environmental awareness reached many people."}]},
  {id:1122,german:"die Zielgruppe",level:"B2",english:"target group, target audience",pos:"noun (f)",sentences:[{"de": "Die Zielgruppe des neuen Produkts sind vor allem junge Berufstätige.", "en": "The target group for the new product is primarily young working professionals."}, {"de": "Gutes Marketing muss die Bedürfnisse der Zielgruppe genau kennen.", "en": "Good marketing must know the needs of the target audience precisely."}]},
  {id:1123,german:"der Kunde",level:"B2",english:"customer, client",pos:"noun (m)",sentences:[{"de": "Der Kunde hat sich über den schlechten Service beschwert.", "en": "The customer complained about the poor service."}, {"de": "Zufriedene Kunden kommen wieder und empfehlen das Geschäft weiter.", "en": "Satisfied customers come back and recommend the shop to others."}]},
  {id:1124,german:"die Kundschaft",level:"B2",english:"customers, clientele",pos:"noun (f)",sentences:[{"de": "Das Restaurant ist für seine treue Kundschaft bekannt.", "en": "The restaurant is known for its loyal clientele."}, {"de": "Das Geschäft hat seit der Renovierung eine ganz neue Kundschaft gewonnen.", "en": "The shop has gained a completely new clientele since the renovation."}]},
  {id:1125,german:"die Kundenzufriedenheit",level:"B2",english:"customer satisfaction",pos:"noun (f)",sentences:[{"de": "Die Kundenzufriedenheit steht bei unserem Unternehmen an erster Stelle.", "en": "Customer satisfaction is our company's top priority."}, {"de": "Regelmäßige Umfragen helfen dabei, die Kundenzufriedenheit zu messen.", "en": "Regular surveys help to measure customer satisfaction."}]},
  {id:1126,german:"der Umsatz",level:"B2",english:"turnover, revenue, sales",pos:"noun (m)",sentences:[{"de": "Der Umsatz des Unternehmens ist im letzten Quartal um zehn Prozent gestiegen.", "en": "The company's turnover increased by ten percent in the last quarter."}, {"de": "Ein höherer Umsatz bedeutet nicht unbedingt auch einen höheren Gewinn.", "en": "Higher revenue does not necessarily mean higher profit."}]},
  {id:1127,german:"der Gewinn",level:"B2",english:"profit, gain, win",pos:"noun (m)",sentences:[{"de": "Das Unternehmen hat im vergangenen Jahr einen Rekordgewinn erzielt.", "en": "The company achieved a record profit last year."}, {"de": "Der Gewinn wird gleichmäßig unter den Aktionären aufgeteilt.", "en": "The profit is divided equally among the shareholders."}]},
  {id:1128,german:"der Verlust",level:"B2",english:"loss",pos:"noun (m)",sentences:[{"de": "Das Unternehmen hat in diesem Jahr zum ersten Mal einen Verlust gemacht.", "en": "The company has made a loss for the first time this year."}, {"de": "Der Verlust von wichtigen Mitarbeitern kann einem Unternehmen schaden.", "en": "The loss of important employees can harm a company."}]},
  {id:1129,german:"die Bilanz",level:"B2",english:"balance sheet; balance, assessment",pos:"noun (f)",sentences:[{"de": "Die Jahresbilanz des Unternehmens wird von einem Wirtschaftsprüfer geprüft.", "en": "The company's annual balance sheet is audited by an accountant."}, {"de": "Am Ende des Projekts zogen sie eine positive Bilanz.", "en": "At the end of the project, they drew a positive assessment."}]},
  {id:1130,german:"die Buchhaltung",level:"B2",english:"bookkeeping, accounting",pos:"noun (f)",sentences:[{"de": "Die Buchhaltung ist für die korrekte Erfassung aller Einnahmen und Ausgaben verantwortlich.", "en": "The accounting department is responsible for the correct recording of all income and expenditure."}, {"de": "Sie arbeitet in der Buchhaltung eines mittelständischen Unternehmens.", "en": "She works in the accounting department of a medium-sized company."}]},
  {id:1131,german:"der/die Buchhalter/-in",level:"B2",english:"accountant, bookkeeper",pos:"noun (m/f)",sentences:[{"de": "Der Buchhalter überprüft alle Belege und erstellt die monatlichen Berichte.", "en": "The accountant reviews all receipts and prepares the monthly reports."}, {"de": "Die Buchhalterin hat einen Fehler in der Abrechnung entdeckt.", "en": "The bookkeeper discovered an error in the accounts."}]},
  {id:1132,german:"die Steuer",level:"B2",english:"tax; steering wheel",pos:"noun (f)",sentences:[{"de": "Jeder, der in Deutschland arbeitet, muss Steuern auf sein Einkommen zahlen.", "en": "Everyone who works in Germany must pay taxes on their income."}, {"de": "Die Mehrwertsteuer ist eine der wichtigsten indirekten Steuern in Deutschland.", "en": "Value added tax is one of the most important indirect taxes in Germany."}]},
  {id:1133,german:"das Finanzamt",level:"B2",english:"tax office",pos:"noun (n)",sentences:[{"de": "Das Finanzamt hat ihm eine Aufforderung zur Abgabe der Steuererklärung geschickt.", "en": "The tax office sent him a request to submit his tax return."}, {"de": "Sie hat einen Termin beim Finanzamt, um ihre Steuerschulden zu klären.", "en": "She has an appointment at the tax office to settle her tax debts."}]},
  {id:1134,german:"die Steuererklärung",level:"B2",english:"tax return",pos:"noun (f)",sentences:[{"de": "Die Steuererklärung muss bis zum 31. Juli beim Finanzamt eingereicht werden.", "en": "The tax return must be submitted to the tax office by 31 July."}, {"de": "Er hat einen Steuerberater beauftragt, seine Steuererklärung zu erstellen.", "en": "He hired a tax advisor to prepare his tax return."}]},
  {id:1135,german:"der Steuerberater",level:"B2",english:"tax advisor, tax consultant",pos:"noun (m)",sentences:[{"de": "Ein guter Steuerberater kann dabei helfen, Steuern legal zu minimieren.", "en": "A good tax advisor can help to minimise taxes legally."}, {"de": "Sie hat einen erfahrenen Steuerberater, der sich um ihre Unternehmensfinanzen kümmert.", "en": "She has an experienced tax advisor who looks after her company's finances."}]},
  {id:1136,german:"die Mehrwertsteuer",level:"B2",english:"VAT, value added tax",pos:"noun (f)",sentences:[{"de": "In Deutschland beträgt der reguläre Mehrwertsteuersatz neunzehn Prozent.", "en": "In Germany, the standard VAT rate is nineteen percent."}, {"de": "Auf dem Kassenbon ist die Mehrwertsteuer separat ausgewiesen.", "en": "The VAT is shown separately on the receipt."}]},
  {id:1137,german:"der Jahresabschluss",level:"B2",english:"annual accounts, year-end financial statement",pos:"noun (m)",sentences:[{"de": "Der Jahresabschluss muss von einem zugelassenen Wirtschaftsprüfer geprüft werden.", "en": "The annual accounts must be audited by a licensed auditor."}, {"de": "Der Jahresabschluss gibt einen umfassenden Überblick über die finanzielle Lage des Unternehmens.", "en": "The year-end financial statement provides a comprehensive overview of the company's financial situation."}]},
  {id:1138,german:"die Investition",level:"B2",english:"investment",pos:"noun (f)",sentences:[{"de": "Die Investition in neue Technologien hat sich als sehr rentabel erwiesen.", "en": "The investment in new technologies has proven to be very profitable."}, {"de": "Das Unternehmen plant Investitionen in Höhe von mehreren Millionen Euro.", "en": "The company is planning investments of several million euros."}]},
  {id:1139,german:"der Kredit",level:"B2",english:"loan, credit",pos:"noun (m)",sentences:[{"de": "Sie hat einen Kredit bei der Bank aufgenommen, um ihr Unternehmen zu gründen.", "en": "She took out a loan from the bank to start her company."}, {"de": "Der Kredit wird über einen Zeitraum von zehn Jahren zurückgezahlt.", "en": "The loan is repaid over a period of ten years."}]},
  {id:1140,german:"die Zinsen",level:"B2",english:"interest (financial)",pos:"noun (pl)",sentences:[{"de": "Bei einem Kredit zahlt man neben dem Betrag auch Zinsen an die Bank.", "en": "With a loan, one pays interest to the bank in addition to the principal."}, {"de": "Die niedrigen Zinsen machen es derzeit günstig, Geld zu leihen.", "en": "The low interest rates currently make it cheap to borrow money."}]},
  {id:1141,german:"das Budget",level:"B2",english:"budget",pos:"noun (n)",sentences:[{"de": "Das Projekt muss innerhalb des vorgegebenen Budgets abgeschlossen werden.", "en": "The project must be completed within the specified budget."}, {"de": "Sie hat ihr monatliches Budget sorgfältig geplant, um sparen zu können.", "en": "She carefully planned her monthly budget to be able to save."}]},
  {id:1142,german:"die Planung",level:"B2",english:"planning",pos:"noun (f)",sentences:[{"de": "Eine gründliche Planung ist die Grundlage für den Erfolg eines jeden Projekts.", "en": "Thorough planning is the foundation for the success of any project."}, {"de": "Die Planung der Veranstaltung hat mehrere Monate in Anspruch genommen.", "en": "Planning the event took several months."}]},
  {id:1143,german:"das Projekt",level:"B2",english:"project",pos:"noun (n)",sentences:[{"de": "Das Projekt soll bis Ende des Jahres abgeschlossen sein.", "en": "The project is due to be completed by the end of the year."}, {"de": "Sie leitet ein internationales Projekt mit Teams in drei verschiedenen Ländern.", "en": "She leads an international project with teams in three different countries."}]},
  {id:1144,german:"der/die Projektleiter/-in",level:"B2",english:"project manager",pos:"noun (m/f)",sentences:[{"de": "Der Projektleiter ist dafür verantwortlich, dass das Projekt im Zeit- und Kostenrahmen bleibt.", "en": "The project manager is responsible for keeping the project on time and within budget."}, {"de": "Die Projektleiterin koordiniert alle Beteiligten und sorgt für einen reibungslosen Ablauf.", "en": "The project manager coordinates all those involved and ensures a smooth process."}]},
  {id:1145,german:"die Deadline",level:"B2",english:"deadline",pos:"noun (f)",sentences:[{"de": "Die Deadline für die Abgabe des Berichts ist nächsten Freitag.", "en": "The deadline for submitting the report is next Friday."}, {"de": "Er arbeitet unter großem Druck, um die Deadline einzuhalten.", "en": "He is working under great pressure to meet the deadline."}]},
  {id:1146,german:"der Zeitplan",level:"B2",english:"schedule, timetable",pos:"noun (m)",sentences:[{"de": "Der Zeitplan für das Projekt ist sehr eng und lässt wenig Spielraum.", "en": "The schedule for the project is very tight and leaves little room for manoeuvre."}, {"de": "Wir liegen genau im Zeitplan und werden die Deadline problemlos einhalten.", "en": "We are exactly on schedule and will easily meet the deadline."}]},
  {id:1147,german:"die Aufgabe",level:"B2",english:"task, assignment, duty",pos:"noun (f)",sentences:[{"de": "Die wichtigste Aufgabe des Teams ist es, die Kundenzufriedenheit zu verbessern.", "en": "The team's most important task is to improve customer satisfaction."}, {"de": "Er hat viele Aufgaben gleichzeitig zu bewältigen und braucht Unterstützung.", "en": "He has many tasks to handle simultaneously and needs support."}]},
  {id:1148,german:"die Verantwortung",level:"B2",english:"responsibility",pos:"noun (f)",sentences:[{"de": "Mit der neuen Stelle übernimmt sie mehr Verantwortung im Unternehmen.", "en": "With the new position, she takes on more responsibility in the company."}, {"de": "Es ist wichtig, Verantwortung für die eigenen Fehler zu übernehmen.", "en": "It is important to take responsibility for one's own mistakes."}]},
  {id:1149,german:"die Kompetenz",level:"B2",english:"competence, skill, authority",pos:"noun (f)",sentences:[{"de": "Soziale Kompetenz und Teamfähigkeit sind in vielen Berufen unerlässlich.", "en": "Social competence and the ability to work in a team are indispensable in many professions."}, {"de": "Die Entscheidung liegt in der Kompetenz des Abteilungsleiters.", "en": "The decision falls within the authority of the department head."}]},
  {id:1150,german:"die Qualifikation",level:"B2",english:"qualification",pos:"noun (f)",sentences:[{"de": "Ihre Qualifikationen sind für diese Stelle besonders gut geeignet.", "en": "Her qualifications are particularly well suited for this position."}, {"de": "Er hat sich durch Weiterbildungen zusätzliche Qualifikationen erworben.", "en": "He has acquired additional qualifications through further training."}]},
  {id:1151,german:"das Anliegen",level:"B2",english:"concern, request, matter",pos:"noun (n)",sentences:[{"de": "Ihr persönliches Anliegen wurde vom Kundendienst schnell bearbeitet.", "en": "Her personal concern was dealt with quickly by the customer service department."}, {"de": "Er hat sein Anliegen klar und deutlich dem zuständigen Sachbearbeiter vorgetragen.", "en": "He clearly and distinctly presented his matter to the responsible clerk."}]},
  {id:1152,german:"der Antrag",level:"B2",english:"application, request, motion",pos:"noun (m)",sentences:[{"de": "Sie hat einen Antrag auf Kindergeld beim Familienkasse gestellt.", "en": "She submitted an application for child benefit at the family benefits office."}, {"de": "Der Antrag muss vollständig ausgefüllt und fristgerecht eingereicht werden.", "en": "The application must be fully completed and submitted on time."}]},
  {id:1153,german:"die Genehmigung",level:"B2",english:"approval, permit, authorisation",pos:"noun (f)",sentences:[{"de": "Für den Umbau des Hauses benötigt man eine Baugenehmigung von der Gemeinde.", "en": "A building permit from the municipality is required for the renovation of the house."}, {"de": "Die Genehmigung für die Veranstaltung wurde von der Stadtverwaltung erteilt.", "en": "Approval for the event was granted by the city administration."}]},
  {id:1154,german:"die Behörde",level:"B2",english:"authority, government office",pos:"noun (f)",sentences:[{"de": "Die zuständige Behörde hat den Antrag innerhalb von zwei Wochen bearbeitet.", "en": "The responsible authority processed the application within two weeks."}, {"de": "Er musste verschiedene Behörden aufsuchen, um alle Dokumente zu besorgen.", "en": "He had to visit various government offices to obtain all the documents."}]},
  {id:1155,german:"das Amt",level:"B2",english:"office, authority, post",pos:"noun (n)",sentences:[{"de": "Sie hat ihr Amt als Bürgermeisterin nach zehn Jahren niedergelegt.", "en": "She relinquished her post as mayor after ten years."}, {"de": "Er hat sich beim Amt für die Erteilung des Personalausweises angemeldet.", "en": "He has made an appointment at the office to obtain his identity card."}]},
  {id:1156,german:"das Formular",level:"B2",english:"form",pos:"noun (n)",sentences:[{"de": "Das Formular muss vollständig und gut leserlich ausgefüllt werden.", "en": "The form must be filled in completely and legibly."}, {"de": "Sie hat das falsche Formular eingereicht und muss einen neuen Antrag stellen.", "en": "She submitted the wrong form and has to submit a new application."}]},
  {id:1157,german:"der Bescheid",level:"B2",english:"decision, notice, notification",pos:"noun (m)",sentences:[{"de": "Sie hat den Bescheid über die Bewilligung ihres Antrags erhalten.", "en": "She received the notification of approval of her application."}, {"de": "Der Steuerbescheid war höher als erwartet und er legte Widerspruch ein.", "en": "The tax notice was higher than expected and he lodged an objection."}]},
  {id:1158,german:"die Frist",level:"B2",english:"deadline, period, time limit",pos:"noun (f)",sentences:[{"de": "Die Frist für die Einreichung des Antrags läuft nächste Woche ab.", "en": "The deadline for submitting the application expires next week."}, {"de": "Er hat die Frist versäumt und muss jetzt eine Verlängerung beantragen.", "en": "He missed the deadline and now has to apply for an extension."}]},
  {id:1159,german:"der Widerspruch",level:"B2",english:"objection, contradiction",pos:"noun (m)",sentences:[{"de": "Gegen den ablehnenden Bescheid hat sie fristgerecht Widerspruch eingelegt.", "en": "She lodged an objection against the rejection notice within the deadline."}, {"de": "Zwischen seinen Aussagen gibt es einen deutlichen Widerspruch.", "en": "There is a clear contradiction between his statements."}]},
  {id:1160,german:"die Beschwerde",level:"B2",english:"complaint",pos:"noun (f)",sentences:[{"de": "Er hat eine formelle Beschwerde beim Kundenservice eingereicht.", "en": "He submitted a formal complaint to the customer service department."}, {"de": "Die Beschwerde über den Lärm der Baustelle wurde von der Behörde ernst genommen.", "en": "The complaint about the noise from the building site was taken seriously by the authority."}]},
  {id:1161,german:"der Einspruch",level:"B2",english:"objection, appeal",pos:"noun (m)",sentences:[{"de": "Sie hat gegen den Steuerbescheid Einspruch eingelegt.", "en": "She lodged an appeal against the tax assessment."}, {"de": "Der Einspruch muss innerhalb eines Monats nach Erhalt des Bescheids eingereicht werden.", "en": "The objection must be submitted within one month of receiving the notice."}]},
  {id:1162,german:"das Recht",level:"B2",english:"right, law",pos:"noun (n)",sentences:[{"de": "Jeder Mensch hat das Recht auf freie Meinungsäußerung.", "en": "Every person has the right to freedom of expression."}, {"de": "Sie studiert Recht an der Universität Frankfurt.", "en": "She is studying law at the University of Frankfurt."}]},
  {id:1163,german:"die Pflicht",level:"B2",english:"duty, obligation",pos:"noun (f)",sentences:[{"de": "Es ist die Pflicht eines jeden Staatsbürgers, Steuern zu zahlen.", "en": "It is the duty of every citizen to pay taxes."}, {"de": "Er hat seine Pflichten als Vater sehr ernst genommen.", "en": "He took his duties as a father very seriously."}]},
  {id:1164,german:"der Vertrag",level:"B2",english:"contract, agreement",pos:"noun (m)",sentences:[{"de": "Vor der Unterzeichnung des Vertrags sollte man alle Klauseln sorgfältig lesen.", "en": "Before signing the contract, one should carefully read all the clauses."}, {"de": "Der Vertrag wurde von beiden Parteien unterzeichnet und tritt sofort in Kraft.", "en": "The contract was signed by both parties and comes into effect immediately."}]},
  {id:1165,german:"die Klausel",level:"B2",english:"clause",pos:"noun (f)",sentences:[{"de": "Die Klausel im Vertrag regelt die Bedingungen für eine vorzeitige Kündigung.", "en": "The clause in the contract regulates the conditions for early termination."}, {"de": "Er hat den Anwalt gebeten, eine bestimmte Klausel aus dem Vertrag zu streichen.", "en": "He asked the lawyer to remove a specific clause from the contract."}]},
  {id:1166,german:"der Paragraph",level:"B2",english:"paragraph, clause, section",pos:"noun (m)",sentences:[{"de": "Paragraph 218 des Strafgesetzbuchs regelt in Deutschland die Abtreibung.", "en": "Section 218 of the Criminal Code regulates abortion in Germany."}, {"de": "Die Anwältin hat sich auf einen bestimmten Paragraphen im Vertrag bezogen.", "en": "The lawyer referred to a specific clause in the contract."}]},
  {id:1167,german:"das Gesetz",level:"B2",english:"law, act",pos:"noun (n)",sentences:[{"de": "Das neue Gesetz tritt am ersten Januar des nächsten Jahres in Kraft.", "en": "The new law comes into force on the first of January next year."}, {"de": "Gesetze müssen von allen Bürgern eingehalten werden, unabhängig von ihrer sozialen Stellung.", "en": "Laws must be observed by all citizens, regardless of their social status."}]},
  {id:1168,german:"die Vorschrift",level:"B2",english:"regulation, rule, instruction",pos:"noun (f)",sentences:[{"de": "Die Sicherheitsvorschriften am Arbeitsplatz müssen strikt eingehalten werden.", "en": "Workplace safety regulations must be strictly observed."}, {"de": "Laut Vorschrift muss jedes Produkt eine gültige CE-Kennzeichnung tragen.", "en": "According to the regulation, every product must bear a valid CE marking."}]},
  {id:1169,german:"die Regelung",level:"B2",english:"regulation, arrangement, settlement",pos:"noun (f)",sentences:[{"de": "Die neue Regelung zur Homeoffice-Pflicht wird heftig diskutiert.", "en": "The new regulation on working from home is being hotly debated."}, {"de": "Eine einvernehmliche Regelung des Streits konnte außergerichtlich erzielt werden.", "en": "An amicable settlement of the dispute was achieved out of court."}]},
  {id:1170,german:"die Bestimmung",level:"B2",english:"regulation, provision, purpose",pos:"noun (f)",sentences:[{"de": "Die Bestimmungen des Vertrags sind für beide Seiten verbindlich.", "en": "The provisions of the contract are binding on both parties."}, {"de": "Er hat lange nach seiner Bestimmung im Leben gesucht und sie im Lehrberuf gefunden.", "en": "He searched for his purpose in life for a long time and found it in the teaching profession."}]},
  {id:1171,german:"die Ausnahme",level:"B2",english:"exception",pos:"noun (f)",sentences:[{"de": "Die Regel gilt für alle Mitarbeiter, ohne Ausnahme.", "en": "The rule applies to all employees, without exception."}, {"de": "In diesem besonderen Fall macht das Unternehmen eine Ausnahme von der Standardpolitik.", "en": "In this special case, the company is making an exception to the standard policy."}]},
  {id:1172,german:"das Protokoll",level:"B2",english:"minutes, record, protocol",pos:"noun (n)",sentences:[{"de": "Das Protokoll der Sitzung wurde von der Sekretärin erstellt und allen Teilnehmern zugeschickt.", "en": "The minutes of the meeting were drawn up by the secretary and sent to all participants."}, {"de": "Beim Grenzübertritt muss man ein bestimmtes Protokoll einhalten.", "en": "When crossing the border, one must follow a specific protocol."}]},
  {id:1173,german:"die Sitzung",level:"B2",english:"meeting, session",pos:"noun (f)",sentences:[{"de": "Die Sitzung des Vorstands dauerte über drei Stunden.", "en": "The board meeting lasted over three hours."}, {"de": "Können wir die Sitzung auf morgen verschieben?", "en": "Can we postpone the meeting to tomorrow?"}]},
  {id:1174,german:"die Konferenz",level:"B2",english:"conference",pos:"noun (f)",sentences:[{"de": "An der internationalen Konferenz nahmen Experten aus zwanzig Ländern teil.", "en": "Experts from twenty countries participated in the international conference."}, {"de": "Die nächste Konferenz findet in Wien statt.", "en": "The next conference will take place in Vienna."}]},
  {id:1175,german:"die Verhandlung",level:"B2",english:"negotiation, hearing, trial",pos:"noun (f)",sentences:[{"de": "Die Verhandlungen zwischen den Parteien verliefen sehr zäh.", "en": "The negotiations between the parties were very tough."}, {"de": "Die Verhandlung vor Gericht beginnt nächste Woche.", "en": "The trial in court begins next week."}]},
  {id:1176,german:"der Kompromiss",level:"B2",english:"compromise",pos:"noun (m)",sentences:[{"de": "Nach langen Diskussionen einigten sie sich auf einen Kompromiss.", "en": "After lengthy discussions, they agreed on a compromise."}, {"de": "Ein Kompromiss ist oft besser als gar keine Lösung.", "en": "A compromise is often better than no solution at all."}]},
  {id:1177,german:"die Einigung",level:"B2",english:"agreement, settlement",pos:"noun (f)",sentences:[{"de": "Die Einigung über den neuen Tarifvertrag wurde gestern erzielt.", "en": "The agreement on the new collective agreement was reached yesterday."}, {"de": "Ohne eine Einigung droht ein langer Rechtsstreit.", "en": "Without a settlement, a lengthy legal dispute threatens."}]},
  {id:1178,german:"der Konsens",level:"B2",english:"consensus",pos:"noun (m)",sentences:[{"de": "Im Team herrschte Konsens über die neue Strategie.", "en": "There was consensus in the team about the new strategy."}, {"de": "Einen Konsens zu finden ist nicht immer einfach.", "en": "Finding a consensus is not always easy."}]},
  {id:1179,german:"der Dissens",level:"B2",english:"dissent, disagreement",pos:"noun (m)",sentences:[{"de": "Es besteht weiterhin Dissens zwischen den Verhandlungspartnern.", "en": "There is still dissent between the negotiating partners."}, {"de": "Der Dissens in der Gruppe führte zu erheblichen Verzögerungen.", "en": "The disagreement within the group led to considerable delays."}]},
  {id:1180,german:"die Abstimmung",level:"B2",english:"vote, voting, coordination",pos:"noun (f)",sentences:[{"de": "Bei der Abstimmung erhielt der Vorschlag eine klare Mehrheit.", "en": "In the vote, the proposal received a clear majority."}, {"de": "Eine gute Abstimmung zwischen den Abteilungen ist unerlässlich.", "en": "Good coordination between the departments is essential."}]},
  {id:1181,german:"die Mehrheit",level:"B2",english:"majority",pos:"noun (f)",sentences:[{"de": "Die Mehrheit der Mitarbeiter befürwortet die neue Regelung.", "en": "The majority of employees support the new regulation."}, {"de": "Mit einer knappen Mehrheit wurde der Antrag angenommen.", "en": "The motion was passed with a narrow majority."}]},
  {id:1182,german:"die Minderheit",level:"B2",english:"minority",pos:"noun (f)",sentences:[{"de": "Die Interessen der Minderheit müssen ebenfalls berücksichtigt werden.", "en": "The interests of the minority must also be taken into account."}, {"de": "Eine kleine Minderheit stimmte gegen den Vorschlag.", "en": "A small minority voted against the proposal."}]},
  {id:1183,german:"der Vorsitz",level:"B2",english:"chairmanship, presidency",pos:"noun (m)",sentences:[{"de": "Er übernahm den Vorsitz der Kommission für ein Jahr.", "en": "He took over the chairmanship of the commission for one year."}, {"de": "Unter ihrem Vorsitz wurden wichtige Reformen eingeleitet.", "en": "Under her chairmanship, important reforms were initiated."}]},
  {id:1184,german:"der/die Vorsitzende",level:"B2",english:"chairperson, president",pos:"noun (m/f)",sentences:[{"de": "Die Vorsitzende eröffnete die Sitzung pünktlich um 10 Uhr.", "en": "The chairperson opened the meeting punctually at 10 o'clock."}, {"de": "Der Vorsitzende bat alle Teilnehmer um Ruhe.", "en": "The chairperson asked all participants to be quiet."}]},
  {id:1185,german:"das Ergebnis",level:"B2",english:"result, outcome",pos:"noun (n)",sentences:[{"de": "Das Ergebnis der Verhandlungen war für alle Seiten zufriedenstellend.", "en": "The outcome of the negotiations was satisfactory for all sides."}, {"de": "Wir warten noch auf das Ergebnis der Analyse.", "en": "We are still waiting for the result of the analysis."}]},
  {id:1186,german:"die Lösung",level:"B2",english:"solution",pos:"noun (f)",sentences:[{"de": "Für dieses Problem haben wir noch keine Lösung gefunden.", "en": "We have not yet found a solution to this problem."}, {"de": "Die vorgeschlagene Lösung überzeugt nicht alle Beteiligten.", "en": "The proposed solution does not convince all those involved."}]},
  {id:1187,german:"der Vorschlag",level:"B2",english:"suggestion, proposal",pos:"noun (m)",sentences:[{"de": "Ihr Vorschlag wurde vom Ausschuss einstimmig angenommen.", "en": "Her proposal was unanimously accepted by the committee."}, {"de": "Haben Sie einen konkreten Vorschlag zur Kostensenkung?", "en": "Do you have a concrete suggestion for reducing costs?"}]},
  {id:1188,german:"die Alternative",level:"B2",english:"alternative",pos:"noun (f)",sentences:[{"de": "Zu dieser Maßnahme gibt es keine sinnvolle Alternative.", "en": "There is no sensible alternative to this measure."}, {"de": "Wir sollten alle Alternativen sorgfältig abwägen.", "en": "We should carefully weigh all alternatives."}]},
  {id:1189,german:"die Möglichkeit",level:"B2",english:"possibility, opportunity",pos:"noun (f)",sentences:[{"de": "Es besteht die Möglichkeit, den Vertrag zu verlängern.", "en": "There is the possibility of extending the contract."}, {"de": "Diese Möglichkeit sollten wir unbedingt nutzen.", "en": "We should definitely take advantage of this opportunity."}]},
  {id:1190,german:"die Chance",level:"B2",english:"chance, opportunity",pos:"noun (f)",sentences:[{"de": "Diese Kooperation bietet uns eine große Chance.", "en": "This cooperation offers us a great opportunity."}, {"de": "Man sollte eine solche Chance nicht ungenutzt lassen.", "en": "One should not let such a chance go to waste."}]},
  {id:1191,german:"das Risiko",level:"B2",english:"risk",pos:"noun (n)",sentences:[{"de": "Das finanzielle Risiko dieses Projekts ist nicht zu unterschätzen.", "en": "The financial risk of this project should not be underestimated."}, {"de": "Jede unternehmerische Entscheidung birgt ein gewisses Risiko.", "en": "Every business decision carries a certain risk."}]},
  {id:1192,german:"einen Probedurchlauf machen",level:"B2",english:"to do a trial run, to rehearse",pos:"verb phrase",sentences:[{"de": "Bevor wir das System einführen, sollten wir einen Probedurchlauf machen.", "en": "Before we introduce the system, we should do a trial run."}, {"de": "Das Team machte einen Probedurchlauf, um mögliche Fehler zu entdecken.", "en": "The team did a trial run to discover possible errors."}]},
  {id:1193,german:"die Probearbeit",level:"B2",english:"trial work, probationary work",pos:"noun (f)",sentences:[{"de": "Die Bewerberin leistet diese Woche Probearbeit in unserer Abteilung.", "en": "The applicant is doing trial work in our department this week."}, {"de": "Nach der Probearbeit entschieden wir uns für den Bewerber.", "en": "After the trial work, we decided in favour of the applicant."}]},
  {id:1194,german:"ausprobieren",level:"B2",english:"to try out, to test",pos:"verb",sentences:[{"de": "Wir möchten die neue Software erst ausprobieren, bevor wir sie kaufen.", "en": "We would like to try out the new software before buying it."}, {"de": "Probieren Sie alle Funktionen in Ruhe aus.", "en": "Try out all the functions at your leisure."}]},
  {id:1195,german:"testen",level:"B2",english:"to test",pos:"verb",sentences:[{"de": "Die Entwickler testen das Programm auf Fehler.", "en": "The developers are testing the program for errors."}, {"de": "Wir müssen das neue Verfahren unter realen Bedingungen testen.", "en": "We must test the new procedure under real conditions."}]},
  {id:1196,german:"prüfen",level:"B2",english:"to check, to examine, to test",pos:"verb",sentences:[{"de": "Bitte prüfen Sie alle Angaben sorgfältig auf Richtigkeit.", "en": "Please carefully check all details for accuracy."}, {"de": "Die Behörde prüft den Antrag auf Vollständigkeit.", "en": "The authority examines the application for completeness."}]},
  {id:1197,german:"kontrollieren",level:"B2",english:"to control, to check, to monitor",pos:"verb",sentences:[{"de": "Der Vorgesetzte kontrolliert regelmäßig die Arbeitsqualität.", "en": "The supervisor regularly monitors the quality of work."}, {"de": "Am Eingang wurden alle Tickets kontrolliert.", "en": "All tickets were checked at the entrance."}]},
  {id:1198,german:"überprüfen",level:"B2",english:"to verify, to review, to check",pos:"verb",sentences:[{"de": "Bitte überprüfen Sie die Rechnung noch einmal genau.", "en": "Please check the invoice carefully once more."}, {"de": "Die Aussagen des Zeugen werden von der Polizei überprüft.", "en": "The witness's statements are being verified by the police."}]},
  {id:1199,german:"auswerten",level:"B2",english:"to evaluate, to analyse, to process",pos:"verb",sentences:[{"de": "Die Fragebögen werden derzeit ausgewertet.", "en": "The questionnaires are currently being evaluated."}, {"de": "Es dauert einige Tage, die gesammelten Daten auszuwerten.", "en": "It takes a few days to analyse the collected data."}]},
  {id:1200,german:"analysieren",level:"B2",english:"to analyse",pos:"verb",sentences:[{"de": "Die Expertin analysiert die Ursachen des Rückgangs.", "en": "The expert is analysing the causes of the decline."}, {"de": "Wir müssen die Situation gründlich analysieren, bevor wir handeln.", "en": "We must thoroughly analyse the situation before acting."}]},
  {id:1201,german:"bewerten",level:"B2",english:"to evaluate, to assess, to rate",pos:"verb",sentences:[{"de": "Die Juroren bewerten die Beiträge nach festgelegten Kriterien.", "en": "The judges evaluate the submissions according to set criteria."}, {"de": "Es ist schwierig, kreative Arbeiten objektiv zu bewerten.", "en": "It is difficult to assess creative work objectively."}]},
  {id:1202,german:"beurteilen",level:"B2",english:"to assess, to judge, to evaluate",pos:"verb",sentences:[{"de": "Ohne alle Fakten zu kennen, kann man die Lage nicht beurteilen.", "en": "Without knowing all the facts, one cannot judge the situation."}, {"de": "Die Lehrerin beurteilte die Schülerarbeiten sehr fair.", "en": "The teacher assessed the students' work very fairly."}]},
  {id:1203,german:"einschätzen",level:"B2",english:"to estimate, to assess, to judge",pos:"verb",sentences:[{"de": "Wie schätzen Sie die Risiken dieses Projekts ein?", "en": "How do you assess the risks of this project?"}, {"de": "Man sollte die Konkurrenz niemals unterschätzen oder falsch einschätzen.", "en": "One should never underestimate or misjudge the competition."}]},
  {id:1204,german:"vergleichen",level:"B2",english:"to compare",pos:"verb",sentences:[{"de": "Vergleichen Sie die Angebote verschiedener Anbieter miteinander.", "en": "Compare the offers of various providers with each other."}, {"de": "Es wäre unfair, diese beiden Konzepte direkt zu vergleichen.", "en": "It would be unfair to compare these two concepts directly."}]},
  {id:1205,german:"unterscheiden",level:"B2",english:"to distinguish, to differentiate",pos:"verb",sentences:[{"de": "Man muss zwischen den verschiedenen Vertragsarten unterscheiden.", "en": "One must distinguish between the different types of contracts."}, {"de": "Diese zwei Produkte sind kaum voneinander zu unterscheiden.", "en": "These two products are barely distinguishable from each other."}]},
  {id:1206,german:"definieren",level:"B2",english:"to define",pos:"verb",sentences:[{"de": "Wir müssen zunächst die Ziele des Projekts klar definieren.", "en": "We must first clearly define the objectives of the project."}, {"de": "Der Begriff ist in der Fachliteratur unterschiedlich definiert.", "en": "The term is defined differently in the specialist literature."}]},
  {id:1207,german:"beschreiben",level:"B2",english:"to describe",pos:"verb",sentences:[{"de": "Können Sie das Problem genauer beschreiben?", "en": "Can you describe the problem in more detail?"}, {"de": "Der Zeuge beschrieb den Vorfall sehr detailliert.", "en": "The witness described the incident in great detail."}]},
  {id:1208,german:"erklären",level:"B2",english:"to explain",pos:"verb",sentences:[{"de": "Bitte erklären Sie mir den Unterschied zwischen diesen beiden Optionen.", "en": "Please explain to me the difference between these two options."}, {"de": "Der Techniker erklärte, wie das Gerät funktioniert.", "en": "The technician explained how the device works."}]},
  {id:1209,german:"begründen",level:"B2",english:"to justify, to give reasons for",pos:"verb",sentences:[{"de": "Sie musste ihre Entscheidung vor dem Ausschuss begründen.", "en": "She had to justify her decision before the committee."}, {"de": "Bitte begründen Sie Ihren Antrag schriftlich.", "en": "Please give written reasons for your application."}]},
  {id:1210,german:"argumentieren",level:"B2",english:"to argue, to make an argument",pos:"verb",sentences:[{"de": "Er argumentierte überzeugend für die neue Strategie.", "en": "He argued convincingly in favour of the new strategy."}, {"de": "Man muss sachlich und fundiert argumentieren können.", "en": "One must be able to argue objectively and with sound reasoning."}]},
  {id:1211,german:"diskutieren",level:"B2",english:"to discuss, to debate",pos:"verb",sentences:[{"de": "Wir sollten diesen Punkt in der nächsten Sitzung diskutieren.", "en": "We should discuss this point at the next meeting."}, {"de": "Über Geschmack lässt sich trefflich diskutieren.", "en": "Matters of taste are well worth debating."}]},
  {id:1212,german:"der Bestandskunde",level:"B2",english:"existing customer, regular customer",pos:"noun (m)",sentences:[{"de": "Bestandskunden erhalten einen Treuerabatt von fünf Prozent.", "en": "Existing customers receive a loyalty discount of five percent."}, {"de": "Die Pflege von Bestandskunden ist genauso wichtig wie die Neukundengewinnung.", "en": "Looking after existing customers is just as important as acquiring new ones."}]},
  {id:1213,german:"die Stammkundschaft",level:"B2",english:"regular customers, loyal clientele",pos:"noun (f)",sentences:[{"de": "Das Restaurant hat eine treue Stammkundschaft aufgebaut.", "en": "The restaurant has built up a loyal regular clientele."}, {"de": "Durch guten Service hält man die Stammkundschaft langfristig.", "en": "Through good service, one retains the regular clientele long-term."}]},
  {id:1214,german:"der Neukunde",level:"B2",english:"new customer",pos:"noun (m)",sentences:[{"de": "Neukunden profitieren von einem Einführungsangebot.", "en": "New customers benefit from an introductory offer."}, {"de": "Das Marketing-Team kümmert sich um die Gewinnung von Neukunden.", "en": "The marketing team takes care of acquiring new customers."}]},
  {id:1215,german:"die Kundenbindung",level:"B2",english:"customer loyalty, customer retention",pos:"noun (f)",sentences:[{"de": "Das Bonusprogramm wurde zur Steigerung der Kundenbindung eingeführt.", "en": "The bonus programme was introduced to increase customer loyalty."}, {"de": "Kundenbindung ist ein zentrales Ziel unserer Vertriebsstrategie.", "en": "Customer retention is a central goal of our sales strategy."}]},
  {id:1216,german:"die Kundengewinnung",level:"B2",english:"customer acquisition",pos:"noun (f)",sentences:[{"de": "Die Kosten für die Kundengewinnung sind in den letzten Jahren gestiegen.", "en": "The costs of customer acquisition have risen in recent years."}, {"de": "Online-Werbung ist ein effektives Mittel zur Kundengewinnung.", "en": "Online advertising is an effective means of customer acquisition."}]},
  {id:1217,german:"der Kundenservice",level:"B2",english:"customer service",pos:"noun (m)",sentences:[{"de": "Unser Kundenservice ist von Montag bis Freitag erreichbar.", "en": "Our customer service is available from Monday to Friday."}, {"de": "Ein guter Kundenservice ist entscheidend für den Unternehmenserfolg.", "en": "Good customer service is decisive for business success."}]},
  {id:1218,german:"die Reklamation",level:"B2",english:"complaint (about a product/service)",pos:"noun (f)",sentences:[{"de": "Bitte richten Sie Ihre Reklamation schriftlich an uns.", "en": "Please address your complaint to us in writing."}, {"de": "Die Reklamation wurde innerhalb von drei Werktagen bearbeitet.", "en": "The complaint was processed within three working days."}]},
  {id:1219,german:"die Rückgabe",level:"B2",english:"return (of goods)",pos:"noun (f)",sentences:[{"de": "Die Rückgabe ungeöffneter Waren ist innerhalb von 14 Tagen möglich.", "en": "The return of unopened goods is possible within 14 days."}, {"de": "Für die Rückgabe benötigen Sie die Originalquittung.", "en": "For the return, you need the original receipt."}]},
  {id:1220,german:"die Erstattung",level:"B2",english:"refund, reimbursement",pos:"noun (f)",sentences:[{"de": "Die Erstattung des Kaufpreises erfolgt innerhalb von sieben Tagen.", "en": "The refund of the purchase price will be made within seven days."}, {"de": "Sie haben Anspruch auf die Erstattung Ihrer Reisekosten.", "en": "You are entitled to the reimbursement of your travel expenses."}]},
  {id:1221,german:"die Reparatur",level:"B2",english:"repair",pos:"noun (f)",sentences:[{"de": "Die Reparatur des Geräts dauert voraussichtlich zwei Wochen.", "en": "The repair of the device is expected to take two weeks."}, {"de": "Die Kosten für die Reparatur übernimmt die Garantie.", "en": "The warranty covers the costs of the repair."}]},
  {id:1222,german:"die Garantie",level:"B2",english:"guarantee, warranty",pos:"noun (f)",sentences:[{"de": "Das Produkt hat eine Garantie von zwei Jahren.", "en": "The product has a two-year warranty."}, {"de": "Bei einem Defekt innerhalb der Garantiezeit wird das Gerät kostenlos repariert.", "en": "In the event of a defect within the warranty period, the device is repaired free of charge."}]},
  {id:1223,german:"die Gewährleistung",level:"B2",english:"warranty, guarantee, liability",pos:"noun (f)",sentences:[{"de": "Die gesetzliche Gewährleistung beträgt zwei Jahre ab Kaufdatum.", "en": "The statutory warranty is two years from the date of purchase."}, {"de": "Der Verkäufer haftet im Rahmen der Gewährleistung für Mängel.", "en": "The seller is liable for defects within the scope of the warranty."}]},
  {id:1224,german:"der Mangel",level:"B2",english:"defect, fault, shortage",pos:"noun (m)",sentences:[{"de": "Das Produkt weist einen erheblichen Mangel auf.", "en": "The product has a significant defect."}, {"de": "Es herrscht ein Mangel an qualifizierten Fachkräften.", "en": "There is a shortage of qualified specialists."}]},
  {id:1225,german:"der Defekt",level:"B2",english:"defect, fault, malfunction",pos:"noun (m)",sentences:[{"de": "Ein technischer Defekt hat die Produktion zum Stillstand gebracht.", "en": "A technical defect brought production to a standstill."}, {"de": "Der Defekt an der Maschine wurde schnell behoben.", "en": "The fault in the machine was quickly rectified."}]},
  {id:1226,german:"die Qualitätskontrolle",level:"B2",english:"quality control",pos:"noun (f)",sentences:[{"de": "Jedes Produkt durchläuft vor der Auslieferung eine strenge Qualitätskontrolle.", "en": "Every product undergoes a strict quality control before delivery."}, {"de": "Die Qualitätskontrolle ist ein wesentlicher Teil des Produktionsprozesses.", "en": "Quality control is an essential part of the production process."}]},
  {id:1227,german:"das Qualitätsmanagement",level:"B2",english:"quality management",pos:"noun (n)",sentences:[{"de": "Das Unternehmen hat ein zertifiziertes Qualitätsmanagement eingeführt.", "en": "The company has introduced a certified quality management system."}, {"de": "Gutes Qualitätsmanagement senkt die Fehlerquote erheblich.", "en": "Good quality management significantly reduces the error rate."}]},
  {id:1228,german:"die Norm",level:"B2",english:"standard, norm",pos:"noun (f)",sentences:[{"de": "Das Produkt entspricht der europäischen Norm EN 9001.", "en": "The product complies with the European standard EN 9001."}, {"de": "Die Einhaltung der Normen ist für die Zulassung zwingend erforderlich.", "en": "Compliance with the standards is mandatory for approval."}]},
  {id:1229,german:"die Zertifizierung",level:"B2",english:"certification",pos:"noun (f)",sentences:[{"de": "Die Zertifizierung nach ISO 9001 wurde erfolgreich abgeschlossen.", "en": "The certification according to ISO 9001 was successfully completed."}, {"de": "Ohne entsprechende Zertifizierung darf das Produkt nicht verkauft werden.", "en": "Without the appropriate certification, the product may not be sold."}]},
  {id:1230,german:"die Akkreditierung",level:"B2",english:"accreditation",pos:"noun (f)",sentences:[{"de": "Die Akkreditierung des Labors wurde von der zuständigen Behörde erteilt.", "en": "The accreditation of the laboratory was granted by the competent authority."}, {"de": "Eine Akkreditierung ist Voraussetzung für die Teilnahme an der Messe.", "en": "Accreditation is a prerequisite for participation in the trade fair."}]},
  {id:1231,german:"das Produkt",level:"B2",english:"product",pos:"noun (n)",sentences:[{"de": "Das neue Produkt kommt nächsten Monat auf den Markt.", "en": "The new product will come onto the market next month."}, {"de": "Wir entwickeln Produkte, die den Bedürfnissen unserer Kunden entsprechen.", "en": "We develop products that meet the needs of our customers."}]},
  {id:1232,german:"die Dienstleistung",level:"B2",english:"service",pos:"noun (f)",sentences:[{"de": "Das Unternehmen bietet eine breite Palette an Dienstleistungen an.", "en": "The company offers a wide range of services."}, {"de": "Qualitativ hochwertige Dienstleistungen erfordern gut ausgebildetes Personal.", "en": "High-quality services require well-trained staff."}]},
  {id:1233,german:"das Sortiment",level:"B2",english:"product range, assortment",pos:"noun (n)",sentences:[{"de": "Das Sortiment des Supermarkts wurde um Bio-Produkte erweitert.", "en": "The supermarket's product range has been extended to include organic products."}, {"de": "Unser Sortiment umfasst über tausend verschiedene Artikel.", "en": "Our product range includes over a thousand different items."}]},
  {id:1234,german:"der Preis",level:"B2",english:"price",pos:"noun (m)",sentences:[{"de": "Der Preis für das Produkt wurde aufgrund gestiegener Rohstoffkosten erhöht.", "en": "The price of the product was increased due to rising raw material costs."}, {"de": "Verhandeln Sie den Preis, bevor Sie den Vertrag unterzeichnen.", "en": "Negotiate the price before you sign the contract."}]},
  {id:1235,german:"der Rabatt",level:"B2",english:"discount, rebate",pos:"noun (m)",sentences:[{"de": "Bei einer Bestellung über 500 Euro gewähren wir einen Rabatt von zehn Prozent.", "en": "For orders over 500 euros, we grant a discount of ten percent."}, {"de": "Der Rabatt wird automatisch vom Rechnungsbetrag abgezogen.", "en": "The discount is automatically deducted from the invoice amount."}]},
  {id:1236,german:"der Skonto",level:"B2",english:"cash discount, early payment discount",pos:"noun (m)",sentences:[{"de": "Bei Zahlung innerhalb von zehn Tagen gewähren wir zwei Prozent Skonto.", "en": "We grant a two percent cash discount for payment within ten days."}, {"de": "Der Skonto wurde auf der Rechnung ausgewiesen.", "en": "The early payment discount was shown on the invoice."}]},
  {id:1237,german:"die Rechnung",level:"B2",english:"invoice, bill",pos:"noun (f)",sentences:[{"de": "Die Rechnung muss innerhalb von 30 Tagen beglichen werden.", "en": "The invoice must be settled within 30 days."}, {"de": "Bitte schicken Sie mir die Rechnung per E-Mail.", "en": "Please send me the invoice by email."}]},
  {id:1238,german:"die Quittung",level:"B2",english:"receipt",pos:"noun (f)",sentences:[{"de": "Bewahren Sie die Quittung für eine mögliche Rückgabe auf.", "en": "Keep the receipt for a possible return."}, {"de": "Ohne Quittung können wir keinen Umtausch vornehmen.", "en": "Without a receipt, we cannot make an exchange."}]},
  {id:1239,german:"der Beleg",level:"B2",english:"receipt, voucher, proof",pos:"noun (m)",sentences:[{"de": "Reichen Sie alle Belege für Ihre Ausgaben ein.", "en": "Submit all receipts for your expenses."}, {"de": "Der Buchhalter benötigt Belege für jede Ausgabe.", "en": "The accountant needs proof for every expenditure."}]},
  {id:1240,german:"die Bestellung",level:"B2",english:"order",pos:"noun (f)",sentences:[{"de": "Ihre Bestellung wird innerhalb von drei Werktagen bearbeitet.", "en": "Your order will be processed within three working days."}, {"de": "Die Bestellung kann bis zu 24 Stunden vor Lieferung storniert werden.", "en": "The order can be cancelled up to 24 hours before delivery."}]},
  {id:1241,german:"die Lieferung",level:"B2",english:"delivery",pos:"noun (f)",sentences:[{"de": "Die Lieferung erfolgt frei Haus innerhalb Deutschlands.", "en": "Delivery is free of charge within Germany."}, {"de": "Die Lieferung hat sich leider um eine Woche verzögert.", "en": "Unfortunately, the delivery has been delayed by one week."}]},
  {id:1242,german:"der Versand",level:"B2",english:"shipping, dispatch",pos:"noun (m)",sentences:[{"de": "Der Versand erfolgt in der Regel am nächsten Werktag.", "en": "Shipping usually takes place on the next working day."}, {"de": "Die Versandkosten werden separat berechnet.", "en": "The shipping costs are charged separately."}]},
  {id:1243,german:"die Spedition",level:"B2",english:"freight company, forwarding company",pos:"noun (f)",sentences:[{"de": "Der Transport der Waren wird von einer renommierten Spedition übernommen.", "en": "The transport of the goods is handled by a renowned freight company."}, {"de": "Wir arbeiten seit Jahren mit derselben Spedition zusammen.", "en": "We have been working with the same freight company for years."}]},
  {id:1244,german:"der Frachtbrief",level:"B2",english:"waybill, bill of lading",pos:"noun (m)",sentences:[{"de": "Der Frachtbrief muss alle relevanten Angaben zur Sendung enthalten.", "en": "The waybill must contain all relevant details about the consignment."}, {"de": "Bitte füllen Sie den Frachtbrief vollständig aus.", "en": "Please fill in the waybill completely."}]},
  {id:1245,german:"die Zollabfertigung",level:"B2",english:"customs clearance",pos:"noun (f)",sentences:[{"de": "Die Zollabfertigung kann bei Importen aus Drittländern mehrere Tage dauern.", "en": "Customs clearance for imports from third countries can take several days."}, {"de": "Alle notwendigen Dokumente für die Zollabfertigung wurden eingereicht.", "en": "All necessary documents for customs clearance were submitted."}]},
  {id:1246,german:"die Importware",level:"B2",english:"imported goods",pos:"noun (f)",sentences:[{"de": "Importwaren aus Nicht-EU-Ländern unterliegen Zollgebühren.", "en": "Imported goods from non-EU countries are subject to customs duties."}, {"de": "Die Qualität der Importware muss den europäischen Standards entsprechen.", "en": "The quality of imported goods must meet European standards."}]},
  {id:1247,german:"die Exportware",level:"B2",english:"export goods",pos:"noun (f)",sentences:[{"de": "Exportwaren müssen bestimmten Anforderungen des Ziellandes entsprechen.", "en": "Export goods must meet certain requirements of the destination country."}, {"de": "Die Exportware wurde ordnungsgemäß verpackt und gekennzeichnet.", "en": "The export goods were properly packaged and labelled."}]},
  {id:1248,german:"die Handelsware",level:"B2",english:"merchandise, trade goods",pos:"noun (f)",sentences:[{"de": "Die Handelsware wird im Lager zwischengelagert.", "en": "The merchandise is stored temporarily in the warehouse."}, {"de": "Der Wert der Handelsware muss korrekt deklariert werden.", "en": "The value of the trade goods must be declared correctly."}]},
  {id:1249,german:"die Lieferkette",level:"B2",english:"supply chain",pos:"noun (f)",sentences:[{"de": "Störungen in der Lieferkette können die Produktion erheblich beeinträchtigen.", "en": "Disruptions in the supply chain can significantly affect production."}, {"de": "Das Unternehmen optimiert seine Lieferkette für mehr Nachhaltigkeit.", "en": "The company is optimising its supply chain for greater sustainability."}]},
  {id:1250,german:"die Logistik",level:"B2",english:"logistics",pos:"noun (f)",sentences:[{"de": "Eine effiziente Logistik ist für den Erfolg eines Handelsunternehmens entscheidend.", "en": "Efficient logistics is decisive for the success of a trading company."}, {"de": "Durch verbesserte Logistik konnten die Lieferzeiten verkürzt werden.", "en": "Through improved logistics, delivery times were able to be shortened."}]},
  {id:1251,german:"der Transport",level:"B2",english:"transport, transportation",pos:"noun (m)",sentences:[{"de": "Der Transport empfindlicher Güter erfordert besondere Sorgfalt.", "en": "The transport of sensitive goods requires special care."}, {"de": "Die Kosten für den Transport wurden im Angebot nicht berücksichtigt.", "en": "The costs for transportation were not taken into account in the quotation."}]},
  {id:1252,german:"die Infrastruktur",level:"B2",english:"infrastructure",pos:"noun (f)",sentences:[{"de": "Die Infrastruktur in ländlichen Gebieten muss dringend verbessert werden.", "en": "The infrastructure in rural areas urgently needs to be improved."}, {"de": "Eine moderne Infrastruktur ist die Grundlage für wirtschaftliches Wachstum.", "en": "Modern infrastructure is the foundation for economic growth."}]},
  {id:1253,german:"die Kommunikation",level:"B2",english:"communication",pos:"noun (f)",sentences:[{"de": "Eine offene Kommunikation im Team fördert die Zusammenarbeit.", "en": "Open communication within the team promotes collaboration."}, {"de": "Die Kommunikation zwischen den Abteilungen muss verbessert werden.", "en": "The communication between the departments needs to be improved."}]},
  {id:1254,german:"die Information",level:"B2",english:"information",pos:"noun (f)",sentences:[{"de": "Bitte halten Sie alle Beteiligten über den Projektfortschritt informiert.", "en": "Please keep all those involved informed about project progress."}, {"de": "Weitere Informationen erhalten Sie auf unserer Website.", "en": "Further information is available on our website."}]},
  {id:1255,german:"das Wissen",level:"B2",english:"knowledge",pos:"noun (n)",sentences:[{"de": "Das Wissen der Mitarbeiter ist das wertvollste Kapital eines Unternehmens.", "en": "The knowledge of employees is a company's most valuable asset."}, {"de": "Sie verfügt über umfangreiches Wissen auf dem Gebiet der Betriebswirtschaft.", "en": "She has extensive knowledge in the field of business administration."}]},
  {id:1256,german:"die Fertigkeit",level:"B2",english:"skill, proficiency",pos:"noun (f)",sentences:[{"de": "Soziale Fertigkeiten sind im Berufsleben unentbehrlich.", "en": "Social skills are indispensable in professional life."}, {"de": "Diese Fertigkeit kann durch regelmäßige Übung erworben werden.", "en": "This skill can be acquired through regular practice."}]},
  {id:1257,german:"die Erfahrung",level:"B2",english:"experience",pos:"noun (f)",sentences:[{"de": "Sie bringt langjährige Erfahrung im Projektmanagement mit.", "en": "She brings many years of experience in project management."}, {"de": "Aus dieser Erfahrung können wir für die Zukunft lernen.", "en": "We can learn from this experience for the future."}]},
  {id:1258,german:"das Know-how",level:"B2",english:"know-how, expertise",pos:"noun (n)",sentences:[{"de": "Das technische Know-how unserer Ingenieure ist einzigartig.", "en": "The technical know-how of our engineers is unique."}, {"de": "Wir suchen Mitarbeiter mit spezifischem Know-how im Bereich IT-Sicherheit.", "en": "We are looking for employees with specific know-how in the area of IT security."}]},
  {id:1259,german:"die Expertise",level:"B2",english:"expertise",pos:"noun (f)",sentences:[{"de": "Für dieses Projekt benötigen wir externe Expertise.", "en": "We need external expertise for this project."}, {"de": "Die Expertise der Unternehmensberatung hat uns sehr geholfen.", "en": "The expertise of the management consultancy helped us greatly."}]},
  {id:1260,german:"die Spezialisierung",level:"B2",english:"specialisation",pos:"noun (f)",sentences:[{"de": "Durch eine Spezialisierung kann man höhere Gehälter erzielen.", "en": "Through specialisation, one can achieve higher salaries."}, {"de": "Die Spezialisierung auf erneuerbare Energien war eine kluge Entscheidung.", "en": "Specialising in renewable energies was a wise decision."}]},
  {id:1261,german:"die Qualifizierung",level:"B2",english:"qualification, training",pos:"noun (f)",sentences:[{"de": "Die Qualifizierung der Belegschaft ist eine strategische Priorität.", "en": "The qualification of the workforce is a strategic priority."}, {"de": "Das Unternehmen investiert stark in die Qualifizierung seiner Mitarbeiter.", "en": "The company invests heavily in the qualification of its employees."}]},
  {id:1262,german:"die Schulung",level:"B2",english:"training, coaching",pos:"noun (f)",sentences:[{"de": "Alle neuen Mitarbeiter nehmen an einer Einführungsschulung teil.", "en": "All new employees participate in an introductory training."}, {"de": "Die Schulung zum Thema Datenschutz ist für alle Mitarbeiter verpflichtend.", "en": "The training on the topic of data protection is compulsory for all employees."}]},
  {id:1263,german:"das Seminar",level:"B2",english:"seminar",pos:"noun (n)",sentences:[{"de": "Das Seminar zur Führungskräfteentwicklung findet einmal jährlich statt.", "en": "The seminar on leadership development takes place once a year."}, {"de": "Sie hat an einem zweitägigen Seminar über Kommunikationstechniken teilgenommen.", "en": "She attended a two-day seminar on communication techniques."}]},
  {id:1264,german:"der Workshop",level:"B2",english:"workshop",pos:"noun (m)",sentences:[{"de": "Im Workshop erarbeiteten die Teilnehmer gemeinsam neue Lösungsansätze.", "en": "In the workshop, the participants developed new approaches to solutions together."}, {"de": "Der Workshop wird von einem externen Moderator geleitet.", "en": "The workshop is led by an external facilitator."}]},
  {id:1265,german:"die Fortbildung",level:"B2",english:"further training, professional development",pos:"noun (f)",sentences:[{"de": "Regelmäßige Fortbildungen sind in manchen Berufen gesetzlich vorgeschrieben.", "en": "Regular professional development is legally required in some professions."}, {"de": "Der Arbeitgeber fördert die Fortbildung seiner Mitarbeiter finanziell.", "en": "The employer provides financial support for employees' further training."}]},
  {id:1266,german:"das Zertifikat",level:"B2",english:"certificate",pos:"noun (n)",sentences:[{"de": "Nach erfolgreichem Abschluss erhalten alle Teilnehmer ein Zertifikat.", "en": "After successful completion, all participants receive a certificate."}, {"de": "Das Zertifikat belegt ihre Kenntnisse im Bereich Projektmanagement.", "en": "The certificate demonstrates her knowledge in the field of project management."}]},
  {id:1267,german:"das Diplom",level:"B2",english:"diploma",pos:"noun (n)",sentences:[{"de": "Er hat sein Diplom in Ingenieurwesen mit Auszeichnung abgeschlossen.", "en": "He completed his diploma in engineering with distinction."}, {"de": "Das Diplom ist in vielen Ländern noch immer ein anerkannter Abschluss.", "en": "The diploma is still a recognised qualification in many countries."}]},
  {id:1268,german:"der Masterabschluss",level:"B2",english:"master's degree",pos:"noun (m)",sentences:[{"de": "Mit einem Masterabschluss in BWL stehen viele Türen offen.", "en": "With a master's degree in business administration, many doors are open."}, {"de": "Sie hat ihren Masterabschluss an der Universität Wien erworben.", "en": "She obtained her master's degree at the University of Vienna."}]},
  {id:1269,german:"die Promotion",level:"B2",english:"doctorate, PhD",pos:"noun (f)",sentences:[{"de": "Er hat seine Promotion zum Thema künstliche Intelligenz abgeschlossen.", "en": "He completed his doctorate on the topic of artificial intelligence."}, {"de": "Eine Promotion eröffnet Karrieremöglichkeiten in der Wissenschaft.", "en": "A doctorate opens up career opportunities in academia."}]},
  {id:1270,german:"der Doktortitel",level:"B2",english:"doctoral title, PhD",pos:"noun (m)",sentences:[{"de": "Der Doktortitel berechtigt zur Führung des Titels Dr. vor dem Namen.", "en": "The doctoral title entitles the holder to use the title 'Dr.' before their name."}, {"de": "Sie hat hart gearbeitet, um ihren Doktortitel zu erlangen.", "en": "She worked hard to obtain her doctoral title."}]},
  {id:1271,german:"die Habilitation",level:"B2",english:"habilitation, post-doctoral qualification",pos:"noun (f)",sentences:[{"de": "Die Habilitation ist Voraussetzung für eine Professur an einer deutschen Universität.", "en": "The habilitation is a prerequisite for a professorship at a German university."}, {"de": "Nach der Habilitation wurde er zum außerordentlichen Professor ernannt.", "en": "After his habilitation, he was appointed associate professor."}]},
  {id:1272,german:"das Forschungsprojekt",level:"B2",english:"research project",pos:"noun (n)",sentences:[{"de": "Das Forschungsprojekt wird von der Deutschen Forschungsgemeinschaft gefördert.", "en": "The research project is funded by the German Research Foundation."}, {"de": "An dem internationalen Forschungsprojekt sind zehn Universitäten beteiligt.", "en": "Ten universities are involved in the international research project."}]},
  {id:1273,german:"die Publikation",level:"B2",english:"publication",pos:"noun (f)",sentences:[{"de": "Die Publikation ihrer Forschungsergebnisse wurde in einer renommierten Fachzeitschrift veröffentlicht.", "en": "The publication of her research results was published in a renowned specialist journal."}, {"de": "Für eine akademische Karriere sind regelmäßige Publikationen unerlässlich.", "en": "Regular publications are essential for an academic career."}]},
  {id:1274,german:"der Artikel",level:"B2",english:"article",pos:"noun (m)",sentences:[{"de": "Sie hat einen Artikel über nachhaltige Energiepolitik veröffentlicht.", "en": "She published an article on sustainable energy policy."}, {"de": "Der Artikel erscheint nächste Woche in der Fachzeitschrift.", "en": "The article will appear in the specialist journal next week."}]},
  {id:1275,german:"die Fachzeitschrift",level:"B2",english:"specialist journal, trade journal",pos:"noun (f)",sentences:[{"de": "Der Beitrag wurde in einer internationalen Fachzeitschrift veröffentlicht.", "en": "The article was published in an international specialist journal."}, {"de": "Fachzeitschriften sind wichtige Informationsquellen für Wissenschaftler.", "en": "Specialist journals are important sources of information for scientists."}]},
  {id:1276,german:"der Vortrag",level:"B2",english:"lecture, talk, presentation",pos:"noun (m)",sentences:[{"de": "Der Professor hielt einen fesselnden Vortrag über Klimawandel.", "en": "The professor gave a captivating lecture on climate change."}, {"de": "Für den Vortrag stehen ihm genau zwanzig Minuten zur Verfügung.", "en": "He has exactly twenty minutes available for his talk."}]},
  {id:1277,german:"das Referat",level:"B2",english:"paper, report, presentation",pos:"noun (n)",sentences:[{"de": "Sie hält nächste Woche ein Referat über die Weimarer Republik.", "en": "She is giving a paper on the Weimar Republic next week."}, {"de": "Das Referat muss schriftlich eingereicht und mündlich präsentiert werden.", "en": "The report must be submitted in writing and presented orally."}]},
  {id:1278,german:"die Präsentation",level:"B2",english:"presentation",pos:"noun (f)",sentences:[{"de": "Die Präsentation der Quartalszahlen findet morgen statt.", "en": "The presentation of the quarterly figures takes place tomorrow."}, {"de": "Eine überzeugende Präsentation erfordert gründliche Vorbereitung.", "en": "A convincing presentation requires thorough preparation."}]},
  {id:1279,german:"die Thesis",level:"B2",english:"thesis",pos:"noun (f)",sentences:[{"de": "Sie schreibt ihre Thesis zum Thema nachhaltiges Wirtschaften.", "en": "She is writing her thesis on the topic of sustainable economics."}, {"de": "Die zentrale Thesis des Artikels ist gut belegt.", "en": "The central thesis of the article is well substantiated."}]},
  {id:1280,german:"die Dissertation",level:"B2",english:"dissertation, doctoral thesis",pos:"noun (f)",sentences:[{"de": "Er arbeitet seit drei Jahren an seiner Dissertation.", "en": "He has been working on his dissertation for three years."}, {"de": "Die Dissertation wurde mit summa cum laude bewertet.", "en": "The dissertation was graded summa cum laude."}]},
  {id:1281,german:"das Gutachten",level:"B2",english:"expert opinion, report, assessment",pos:"noun (n)",sentences:[{"de": "Ein unabhängiges Gutachten wurde in Auftrag gegeben.", "en": "An independent expert opinion was commissioned."}, {"de": "Das Gutachten des Sachverständigen bestätigte unsere Vermutung.", "en": "The expert's report confirmed our assumption."}]},
  {id:1282,german:"die Evaluation",level:"B2",english:"evaluation",pos:"noun (f)",sentences:[{"de": "Die Evaluation des Programms ergab überwiegend positive Ergebnisse.", "en": "The evaluation of the programme yielded predominantly positive results."}, {"de": "Eine regelmäßige Evaluation der Maßnahmen ist notwendig.", "en": "A regular evaluation of the measures is necessary."}]},
  {id:1283,german:"das Feedback",level:"B2",english:"feedback",pos:"noun (n)",sentences:[{"de": "Konstruktives Feedback hilft uns, uns weiterzuentwickeln.", "en": "Constructive feedback helps us to develop further."}, {"de": "Bitte geben Sie uns Feedback zu unserem neuen Produkt.", "en": "Please give us feedback on our new product."}]},
  {id:1284,german:"der Bericht",level:"B2",english:"report",pos:"noun (m)",sentences:[{"de": "Der Jahresbericht wird im März veröffentlicht.", "en": "The annual report will be published in March."}, {"de": "Sie muss der Geschäftsführung regelmäßig Bericht erstatten.", "en": "She must regularly report to the management."}]},
  {id:1285,german:"die Dokumentation",level:"B2",english:"documentation",pos:"noun (f)",sentences:[{"de": "Eine vollständige Dokumentation aller Vorgänge ist gesetzlich vorgeschrieben.", "en": "Complete documentation of all processes is required by law."}, {"de": "Die technische Dokumentation muss für den Kunden verständlich sein.", "en": "The technical documentation must be comprehensible for the customer."}]},
  {id:1286,german:"die Akte",level:"B2",english:"file, dossier, record",pos:"noun (f)",sentences:[{"de": "Die Akte des Falles wird im Archiv aufbewahrt.", "en": "The file of the case is kept in the archive."}, {"de": "Alle relevanten Dokumente wurden in der Akte zusammengefasst.", "en": "All relevant documents were compiled in the file."}]},
  {id:1287,german:"die Unterlage",level:"B2",english:"document, supporting material",pos:"noun (f)",sentences:[{"de": "Bitte legen Sie alle erforderlichen Unterlagen bei.", "en": "Please attach all required supporting documents."}, {"de": "Die Unterlagen für die Bewerbung müssen vollständig eingereicht werden.", "en": "The documents for the application must be submitted in full."}]},
  {id:1288,german:"das Archiv",level:"B2",english:"archive",pos:"noun (n)",sentences:[{"de": "Historische Dokumente werden im Bundesarchiv aufbewahrt.", "en": "Historical documents are kept in the Federal Archive."}, {"de": "Alle abgeschlossenen Projekte kommen ins Archiv.", "en": "All completed projects go into the archive."}]},
  {id:1289,german:"die Datei",level:"B2",english:"file (digital)",pos:"noun (f)",sentences:[{"de": "Bitte schicken Sie mir die Datei als PDF-Anhang.", "en": "Please send me the file as a PDF attachment."}, {"de": "Die Datei ist zu groß für einen E-Mail-Anhang.", "en": "The file is too large for an email attachment."}]},
  {id:1290,german:"die Tabelle",level:"B2",english:"table, spreadsheet",pos:"noun (f)",sentences:[{"de": "Die Ergebnisse wurden in einer übersichtlichen Tabelle dargestellt.", "en": "The results were presented in a clear table."}, {"de": "Bitte tragen Sie Ihre Daten in die Tabelle ein.", "en": "Please enter your data into the spreadsheet."}]},
  {id:1291,german:"die Statistik",level:"B2",english:"statistics",pos:"noun (f)",sentences:[{"de": "Die Statistik zeigt einen deutlichen Rückgang der Arbeitslosigkeit.", "en": "The statistics show a clear decline in unemployment."}, {"de": "Laut der aktuellen Statistik ist die Geburtenrate gesunken.", "en": "According to the latest statistics, the birth rate has fallen."}]},
  {id:1292,german:"das Diagramm",level:"B2",english:"diagram, chart",pos:"noun (n)",sentences:[{"de": "Das Diagramm veranschaulicht die Umsatzentwicklung der letzten fünf Jahre.", "en": "The chart illustrates the revenue development over the last five years."}, {"de": "Fügen Sie bitte ein Diagramm in Ihren Bericht ein.", "en": "Please include a diagram in your report."}]},
  {id:1293,german:"die Grafik",level:"B2",english:"graphic, chart, illustration",pos:"noun (f)",sentences:[{"de": "Die Grafik macht die komplexen Zusammenhänge auf einen Blick verständlich.", "en": "The graphic makes the complex relationships understandable at a glance."}, {"de": "Für die Präsentation wurden professionelle Grafiken erstellt.", "en": "Professional graphics were created for the presentation."}]},
  {id:1294,german:"die Auswertung",level:"B2",english:"evaluation, analysis",pos:"noun (f)",sentences:[{"de": "Die Auswertung der Umfrage hat mehrere Wochen in Anspruch genommen.", "en": "The evaluation of the survey took several weeks."}, {"de": "Die Auswertung der Daten ergab interessante Erkenntnisse.", "en": "The analysis of the data yielded interesting findings."}]},
  {id:1295,german:"die Analyse",level:"B2",english:"analysis",pos:"noun (f)",sentences:[{"de": "Eine gründliche Analyse der Situation ist vor jeder Entscheidung notwendig.", "en": "A thorough analysis of the situation is necessary before every decision."}, {"de": "Die Analyse der Konkurrenz zeigte einige Schwachstellen auf.", "en": "The analysis of the competition revealed some weaknesses."}]},
  {id:1296,german:"der Befund",level:"B2",english:"finding, result, diagnosis",pos:"noun (m)",sentences:[{"de": "Der Befund des Arztes war erfreulich.", "en": "The doctor's finding was pleasing."}, {"de": "Der Befund der Untersuchung wird in einem Bericht zusammengefasst.", "en": "The finding of the investigation is summarised in a report."}]},
  {id:1297,german:"die Diagnose",level:"B2",english:"diagnosis",pos:"noun (f)",sentences:[{"de": "Die Diagnose des Arztes bestätigte den Verdacht auf eine Lungenentzündung.", "en": "The doctor's diagnosis confirmed the suspicion of pneumonia."}, {"de": "Eine frühzeitige Diagnose kann die Heilungschancen erheblich verbessern.", "en": "An early diagnosis can significantly improve the chances of recovery."}]},
  {id:1298,german:"die Prognose",level:"B2",english:"prognosis, forecast",pos:"noun (f)",sentences:[{"de": "Die wirtschaftliche Prognose für das nächste Jahr ist verhalten optimistisch.", "en": "The economic forecast for next year is cautiously optimistic."}, {"de": "Die Prognose des Arztes war besser als erwartet.", "en": "The doctor's prognosis was better than expected."}]},
  {id:1299,german:"die Schätzung",level:"B2",english:"estimate, estimation",pos:"noun (f)",sentences:[{"de": "Laut einer groben Schätzung werden etwa 500 Personen teilnehmen.", "en": "According to a rough estimate, around 500 people will participate."}, {"de": "Die Schätzung der Kosten war deutlich zu niedrig angesetzt.", "en": "The estimate of the costs was set far too low."}]},
  {id:1300,german:"die Berechnung",level:"B2",english:"calculation",pos:"noun (f)",sentences:[{"de": "Laut unserer Berechnung werden die Kosten die ursprüngliche Kalkulation überschreiten.", "en": "According to our calculation, the costs will exceed the original estimate."}, {"de": "Die Berechnung der Steuer wurde von einem Steuerberater vorgenommen.", "en": "The calculation of the tax was carried out by a tax advisor."}]},
  {id:1301,german:"die Kalkulation",level:"B2",english:"calculation, costing",pos:"noun (f)",sentences:[{"de": "Die Kalkulation des Projekts muss alle Nebenkosten berücksichtigen.", "en": "The costing of the project must take all ancillary costs into account."}, {"de": "Nach einer genauen Kalkulation stellte sich heraus, dass das Projekt nicht rentabel ist.", "en": "After a precise calculation, it turned out that the project is not profitable."}]},
  {id:1302,german:"die Offerte",level:"B2",english:"offer, quote, tender",pos:"noun (f)",sentences:[{"de": "Die Offerte des Lieferanten lag deutlich unter unseren Erwartungen.", "en": "The supplier's offer was significantly below our expectations."}, {"de": "Wir haben drei Offerten eingeholt und verglichen.", "en": "We obtained and compared three quotes."}]},
  {id:1303,german:"die Ausschreibung",level:"B2",english:"tender, call for bids",pos:"noun (f)",sentences:[{"de": "Das Unternehmen hat an der öffentlichen Ausschreibung teilgenommen.", "en": "The company participated in the public tender."}, {"de": "Die Ausschreibung für den Bau der neuen Schule wurde veröffentlicht.", "en": "The call for bids for the construction of the new school was published."}]},
  {id:1304,german:"die Vergabe",level:"B2",english:"award (of contract), allocation",pos:"noun (f)",sentences:[{"de": "Die Vergabe des Auftrags erfolgt nach den Kriterien Preis und Qualität.", "en": "The award of the contract is based on the criteria of price and quality."}, {"de": "Bei der Vergabe öffentlicher Aufträge gelten strenge Vorschriften.", "en": "Strict regulations apply to the allocation of public contracts."}]},
  {id:1305,german:"der Auftraggeber",level:"B2",english:"client, customer, commissioning party",pos:"noun (m)",sentences:[{"de": "Der Auftraggeber hat die Spezifikationen des Projekts festgelegt.", "en": "The client has defined the specifications of the project."}, {"de": "Änderungswünsche des Auftraggebers müssen schriftlich festgehalten werden.", "en": "Change requests from the commissioning party must be recorded in writing."}]},
  {id:1306,german:"der Auftragnehmer",level:"B2",english:"contractor, service provider",pos:"noun (m)",sentences:[{"de": "Der Auftragnehmer ist für die termingerechte Lieferung verantwortlich.", "en": "The contractor is responsible for timely delivery."}, {"de": "Als Auftragnehmer müssen Sie die vereinbarten Qualitätsstandards einhalten.", "en": "As a contractor, you must comply with the agreed quality standards."}]},
  {id:1307,german:"der Subunternehmer",level:"B2",english:"subcontractor",pos:"noun (m)",sentences:[{"de": "Teile des Auftrags wurden an einen Subunternehmer vergeben.", "en": "Parts of the contract were awarded to a subcontractor."}, {"de": "Der Auftragnehmer haftet auch für Fehler seiner Subunternehmer.", "en": "The contractor is also liable for the mistakes of its subcontractors."}]},
  {id:1308,german:"die Haftung",level:"B2",english:"liability",pos:"noun (f)",sentences:[{"de": "Bei Fahrlässigkeit tragen Sie die volle Haftung für entstandene Schäden.", "en": "In the event of negligence, you bear full liability for damages incurred."}, {"de": "Die Haftung des Unternehmens ist vertraglich auf einen Höchstbetrag begrenzt.", "en": "The company's liability is contractually limited to a maximum amount."}]},
  {id:1309,german:"der Schadensersatz",level:"B2",english:"compensation, damages",pos:"noun (m)",sentences:[{"de": "Das Unternehmen wurde zur Zahlung von Schadensersatz verurteilt.", "en": "The company was ordered to pay damages."}, {"de": "Sie forderte Schadensersatz für die durch den Unfall entstandenen Verluste.", "en": "She claimed compensation for the losses caused by the accident."}]},
  {id:1310,german:"die Entschädigung",level:"B2",english:"compensation, indemnification",pos:"noun (f)",sentences:[{"de": "Die betroffenen Mieter erhielten eine Entschädigung für die Unannehmlichkeiten.", "en": "The affected tenants received compensation for the inconvenience."}, {"de": "Er klagte auf Entschädigung für den ihm entstandenen Schaden.", "en": "He sued for indemnification for the damage caused to him."}]},
  {id:1311,german:"die Versicherungsleistung",level:"B2",english:"insurance benefit, insurance payment",pos:"noun (f)",sentences:[{"de": "Die Versicherungsleistung deckt die Kosten für die Reparatur vollständig ab.", "en": "The insurance payment fully covers the costs of the repair."}, {"de": "Bitte reichen Sie alle notwendigen Unterlagen ein, um die Versicherungsleistung zu erhalten.", "en": "Please submit all necessary documents to receive the insurance benefit."}]},
  {id:1312,german:"der Schadensfall",level:"B2",english:"case of damage, claim event",pos:"noun (m)",sentences:[{"de": "Im Schadensfall wenden Sie sich bitte sofort an unsere Hotline.", "en": "In the event of a claim, please contact our hotline immediately."}, {"de": "Alle Schädensfälle müssen innerhalb von 48 Stunden gemeldet werden.", "en": "All cases of damage must be reported within 48 hours."}]},
  {id:1313,german:"die Meldepflicht",level:"B2",english:"reporting obligation",pos:"noun (f)",sentences:[{"de": "Bestimmte Krankheiten unterliegen der gesetzlichen Meldepflicht.", "en": "Certain diseases are subject to a statutory reporting obligation."}, {"de": "Arbeitgeber unterliegen einer Meldepflicht gegenüber der Sozialversicherung.", "en": "Employers are subject to a reporting obligation to the social insurance authority."}]},
  {id:1314,german:"die Anzeigepflicht",level:"B2",english:"disclosure obligation",pos:"noun (f)",sentences:[{"de": "Die Anzeigepflicht gegenüber der Versicherung muss eingehalten werden.", "en": "The disclosure obligation to the insurance company must be complied with."}, {"de": "Bei Verdacht auf Steuerhinterziehung besteht eine Anzeigepflicht.", "en": "In the event of suspected tax evasion, there is a disclosure obligation."}]},
  {id:1315,german:"die Dokumentationspflicht",level:"B2",english:"documentation obligation",pos:"noun (f)",sentences:[{"de": "Ärzte unterliegen einer strengen Dokumentationspflicht.", "en": "Doctors are subject to a strict documentation obligation."}, {"de": "Die Dokumentationspflicht für Arbeitsstunden wurde gesetzlich eingeführt.", "en": "The documentation obligation for working hours was introduced by law."}]},
  {id:1316,german:"die Aufzeichnungspflicht",level:"B2",english:"record-keeping obligation",pos:"noun (f)",sentences:[{"de": "Unternehmen unterliegen einer Aufzeichnungspflicht für steuerrelevante Vorgänge.", "en": "Companies are subject to a record-keeping obligation for tax-relevant transactions."}, {"de": "Die Aufzeichnungspflicht umfasst alle Geschäftsvorgänge der letzten zehn Jahre.", "en": "The record-keeping obligation covers all business transactions of the last ten years."}]},
  {id:1317,german:"die Archivierungspflicht",level:"B2",english:"archiving obligation",pos:"noun (f)",sentences:[{"de": "Geschäftsunterlagen unterliegen einer Archivierungspflicht von mindestens sechs Jahren.", "en": "Business documents are subject to an archiving obligation of at least six years."}, {"de": "Die Archivierungspflicht für elektronische Rechnungen ist gesetzlich geregelt.", "en": "The archiving obligation for electronic invoices is regulated by law."}]},
  {id:1318,german:"die Aufbewahrungsfrist",level:"B2",english:"retention period, storage period",pos:"noun (f)",sentences:[{"de": "Die gesetzliche Aufbewahrungsfrist für Buchungsbelege beträgt zehn Jahre.", "en": "The statutory retention period for accounting documents is ten years."}, {"de": "Nach Ablauf der Aufbewahrungsfrist können die Akten vernichtet werden.", "en": "After the retention period has expired, the files can be destroyed."}]},
  {id:1319,german:"das Datenschutzgesetz",level:"B2",english:"data protection law",pos:"noun (n)",sentences:[{"de": "Das europäische Datenschutzgesetz schützt die Daten von EU-Bürgern.", "en": "The European data protection law protects the data of EU citizens."}, {"de": "Alle Unternehmen müssen das Datenschutzgesetz einhalten.", "en": "All companies must comply with the data protection law."}]},
  {id:1320,german:"die Datenschutzerklärung",level:"B2",english:"privacy policy, data protection statement",pos:"noun (f)",sentences:[{"de": "Bevor Sie das Formular absenden, lesen Sie bitte unsere Datenschutzerklärung.", "en": "Before you submit the form, please read our privacy policy."}, {"de": "Die Datenschutzerklärung muss klar und verständlich formuliert sein.", "en": "The data protection statement must be formulated clearly and comprehensibly."}]},
  {id:1321,german:"die Einwilligung",level:"B2",english:"consent",pos:"noun (f)",sentences:[{"de": "Für die Verarbeitung personenbezogener Daten ist eine ausdrückliche Einwilligung erforderlich.", "en": "Explicit consent is required for the processing of personal data."}, {"de": "Die Einwilligung kann jederzeit widerrufen werden.", "en": "Consent can be revoked at any time."}]},
  {id:1322,german:"die Zustimmung",level:"B2",english:"agreement, consent, approval",pos:"noun (f)",sentences:[{"de": "Das Projekt kann nur mit Zustimmung aller Beteiligten umgesetzt werden.", "en": "The project can only be implemented with the agreement of all those involved."}, {"de": "Die Zustimmung des Betriebsrats ist für diese Maßnahme erforderlich.", "en": "The approval of the works council is required for this measure."}]},
  {id:1323,german:"die Ablehnung",level:"B2",english:"rejection, refusal",pos:"noun (f)",sentences:[{"de": "Die Ablehnung des Antrags wurde schriftlich begründet.", "en": "The rejection of the application was justified in writing."}, {"de": "Mit der Ablehnung des Vorschlags war nicht zu rechnen.", "en": "The rejection of the proposal was not to be expected."}]},
  {id:1324,german:"der Widerruf",level:"B2",english:"revocation, withdrawal, retraction",pos:"noun (m)",sentences:[{"de": "Der Widerruf des Vertrags muss innerhalb von 14 Tagen erfolgen.", "en": "The withdrawal from the contract must take place within 14 days."}, {"de": "Nach dem Widerruf wird der Kaufpreis vollständig erstattet.", "en": "After the revocation, the purchase price will be fully refunded."}]},
  {id:1325,german:"die Rücknahme",level:"B2",english:"withdrawal, taking back",pos:"noun (f)",sentences:[{"de": "Die Rücknahme des Angebots kam für alle überraschend.", "en": "The withdrawal of the offer came as a surprise to everyone."}, {"de": "Die Rücknahme defekter Produkte ist gesetzlich vorgeschrieben.", "en": "The taking back of defective products is required by law."}]},
  {id:1326,german:"der Rücktritt",level:"B2",english:"resignation, withdrawal, stepping back",pos:"noun (m)",sentences:[{"de": "Der Rücktritt des Ministers kam nach einem Skandal.", "en": "The minister's resignation came after a scandal."}, {"de": "Im Falle eines Vertragsbruchs ist ein Rücktritt vom Vertrag möglich.", "en": "In the event of a breach of contract, withdrawal from the contract is possible."}]},
  {id:1327,german:"die fristlose Kündigung",level:"B2",english:"immediate dismissal, summary dismissal",pos:"noun phrase (f)",sentences:[{"de": "Nach dem Diebstahl erhielt der Mitarbeiter eine fristlose Kündigung.", "en": "After the theft, the employee received an immediate dismissal."}, {"de": "Eine fristlose Kündigung muss gut begründet sein, um rechtlich wirksam zu sein.", "en": "An immediate dismissal must be well justified in order to be legally effective."}]},
  {id:1328,german:"die Krankmeldung",level:"B2",english:"sick note, medical certificate",pos:"noun (f)",sentences:[{"de": "Bitte reichen Sie bei Krankheit eine Krankmeldung spätestens am dritten Tag ein.", "en": "Please submit a sick note no later than the third day of illness."}, {"de": "Die Krankmeldung muss dem Arbeitgeber unverzüglich vorgelegt werden.", "en": "The sick note must be submitted to the employer without delay."}]},
  {id:1329,german:"das Attest",level:"B2",english:"medical certificate",pos:"noun (n)",sentences:[{"de": "Für die Prüfungsbefreiung benötigen Sie ein ärztliches Attest.", "en": "You need a medical certificate for exemption from the examination."}, {"de": "Das Attest des Hausarztes bestätigte die Arbeitsunfähigkeit.", "en": "The general practitioner's medical certificate confirmed the incapacity for work."}]},
  {id:1330,german:"die Arbeitsunfähigkeit",level:"B2",english:"incapacity for work, inability to work",pos:"noun (f)",sentences:[{"de": "Die Arbeitsunfähigkeit muss durch ein ärztliches Attest nachgewiesen werden.", "en": "The incapacity for work must be proven by a medical certificate."}, {"de": "Bei länger andauernder Arbeitsunfähigkeit greift die Lohnfortzahlung.", "en": "In the event of prolonged incapacity for work, continued wage payment applies."}]},
  {id:1331,german:"die Rehabilitation",level:"B2",english:"rehabilitation",pos:"noun (f)",sentences:[{"de": "Nach dem Unfall absolvierte sie eine mehrmonatige Rehabilitation.", "en": "After the accident, she underwent several months of rehabilitation."}, {"de": "Die Rehabilitation dient dazu, die Arbeitsfähigkeit wiederherzustellen.", "en": "Rehabilitation serves to restore the capacity for work."}]},
  {id:1332,german:"die Wiedereingliederung",level:"B2",english:"reintegration, return to work",pos:"noun (f)",sentences:[{"de": "Die stufenweise Wiedereingliederung ermöglicht eine sanfte Rückkehr in den Beruf.", "en": "Gradual reintegration enables a gentle return to work."}, {"de": "Für die Wiedereingliederung nach langer Krankheit gibt es spezielle Programme.", "en": "There are special programmes for reintegration after long illness."}]},
  {id:1333,german:"die Umschulung",level:"B2",english:"retraining, vocational retraining",pos:"noun (f)",sentences:[{"de": "Die Arbeitsagentur finanziert eine Umschulung zum Fachinformatiker.", "en": "The employment agency is funding retraining as an IT specialist."}, {"de": "Nach dem Stellenabbau erhielten viele Mitarbeiter eine Umschulung.", "en": "After the job cuts, many employees received vocational retraining."}]},
  {id:1334,german:"die Qualifizierungsmaßnahme",level:"B2",english:"qualification measure, training measure",pos:"noun (f)",sentences:[{"de": "Das Unternehmen bietet seinen Mitarbeitern verschiedene Qualifizierungsmaßnahmen an.", "en": "The company offers its employees various training measures."}, {"de": "Qualifizierungsmaßnahmen werden vom Staat gefördert.", "en": "Qualification measures are supported by the state."}]},
  {id:1335,german:"die Fördermaßnahme",level:"B2",english:"support measure, funding measure",pos:"noun (f)",sentences:[{"de": "Die Regierung hat neue Fördermaßnahmen für kleine und mittlere Unternehmen beschlossen.", "en": "The government has decided on new support measures for small and medium-sized companies."}, {"de": "Die Fördermaßnahmen sollen den Übergang zur Digitalwirtschaft erleichtern.", "en": "The funding measures are intended to facilitate the transition to the digital economy."}]},
  {id:1336,german:"das Förderprogramm",level:"B2",english:"funding programme, support programme",pos:"noun (n)",sentences:[{"de": "Das staatliche Förderprogramm unterstützt Start-ups in der Gründungsphase.", "en": "The state funding programme supports start-ups in the founding phase."}, {"de": "Bewerben Sie sich rechtzeitig für das Förderprogramm.", "en": "Apply for the funding programme in good time."}]},
  {id:1337,german:"der Zuschuss",level:"B2",english:"subsidy, grant, allowance",pos:"noun (m)",sentences:[{"de": "Die Stadt gewährt einen Zuschuss für die energetische Sanierung von Gebäuden.", "en": "The city grants a subsidy for the energy-efficient renovation of buildings."}, {"de": "Der Zuschuss deckt bis zu 30 Prozent der Investitionskosten ab.", "en": "The grant covers up to 30 percent of the investment costs."}]},
  {id:1338,german:"die Subvention",level:"B2",english:"subsidy, subvention",pos:"noun (f)",sentences:[{"de": "Landwirtschaftliche Betriebe erhalten in der EU erhebliche Subventionen.", "en": "Agricultural businesses in the EU receive substantial subsidies."}, {"de": "Die Abschaffung von Subventionen für fossile Brennstoffe ist umstritten.", "en": "The abolition of subsidies for fossil fuels is controversial."}]},
  {id:1339,german:"das Darlehen",level:"B2",english:"loan",pos:"noun (n)",sentences:[{"de": "Die Bank gewährt ihm ein Darlehen zu günstigen Konditionen.", "en": "The bank grants him a loan on favourable terms."}, {"de": "Das Darlehen muss innerhalb von zehn Jahren zurückgezahlt werden.", "en": "The loan must be repaid within ten years."}]},
  {id:1340,german:"die Bürgschaft",level:"B2",english:"guarantee, surety",pos:"noun (f)",sentences:[{"de": "Er übernahm die Bürgschaft für den Kredit seines Sohnes.", "en": "He stood surety for his son's loan."}, {"de": "Ohne Bürgschaft wird der Kredit nicht bewilligt.", "en": "Without a guarantee, the loan will not be approved."}]},
  {id:1341,german:"die Sicherheit",level:"B2",english:"security, safety, collateral",pos:"noun (f)",sentences:[{"de": "Die Bank verlangt eine Sicherheit in Form einer Immobilie.", "en": "The bank requires collateral in the form of a property."}, {"de": "Die Sicherheit der Mitarbeiter hat für uns höchste Priorität.", "en": "The safety of employees is our highest priority."}]},
  {id:1342,german:"die Hypothek",level:"B2",english:"mortgage",pos:"noun (f)",sentences:[{"de": "Sie hat eine Hypothek auf ihr Haus aufgenommen, um das Unternehmen zu finanzieren.", "en": "She took out a mortgage on her house to finance the company."}, {"de": "Die monatliche Rate für die Hypothek beträgt 1.200 Euro.", "en": "The monthly instalment for the mortgage amounts to 1,200 euros."}]},
  {id:1343,german:"die Tilgung",level:"B2",english:"repayment, amortisation",pos:"noun (f)",sentences:[{"de": "Die Tilgung des Darlehens beginnt nach einer tilgungsfreien Anlaufphase.", "en": "The repayment of the loan begins after an initial repayment-free period."}, {"de": "Bei einer höheren Tilgung reduziert sich die Gesamtzinslast erheblich.", "en": "With a higher repayment rate, the total interest burden is significantly reduced."}]},
  {id:1344,german:"die Rate",level:"B2",english:"instalment, rate",pos:"noun (f)",sentences:[{"de": "Die monatliche Rate für den Kredit beträgt 350 Euro.", "en": "The monthly instalment for the loan amounts to 350 euros."}, {"de": "Bei Zahlung in Raten entstehen zusätzliche Zinskosten.", "en": "Additional interest costs arise when paying in instalments."}]},
  {id:1345,german:"die Laufzeit",level:"B2",english:"term, duration, runtime",pos:"noun (f)",sentences:[{"de": "Der Kredit hat eine Laufzeit von zwanzig Jahren.", "en": "The loan has a term of twenty years."}, {"de": "Je kürzer die Laufzeit, desto höher die monatliche Belastung.", "en": "The shorter the term, the higher the monthly burden."}]},
  {id:1346,german:"der Zinssatz",level:"B2",english:"interest rate",pos:"noun (m)",sentences:[{"de": "Der aktuelle Zinssatz für Hypothekendarlehen ist historisch niedrig.", "en": "The current interest rate for mortgage loans is historically low."}, {"de": "Die Europäische Zentralbank hat den Zinssatz erhöht, um die Inflation zu bekämpfen.", "en": "The European Central Bank raised the interest rate to combat inflation."}]},
  {id:1347,german:"die Inflation",level:"B2",english:"inflation",pos:"noun (f)",sentences:[{"de": "Die hohe Inflation zehrt an der Kaufkraft der Bevölkerung.", "en": "High inflation is eroding the purchasing power of the population."}, {"de": "Die Zentralbank versucht, die Inflation durch Zinserhöhungen zu dämpfen.", "en": "The central bank is trying to dampen inflation through interest rate increases."}]},
  {id:1348,german:"die Deflation",level:"B2",english:"deflation",pos:"noun (f)",sentences:[{"de": "Deflation kann zu einer Spirale sinkender Preise und wirtschaftlicher Stagnation führen.", "en": "Deflation can lead to a spiral of falling prices and economic stagnation."}, {"de": "Japan kämpfte jahrzehntelang gegen anhaltende Deflation.", "en": "Japan fought against persistent deflation for decades."}]},
  {id:1349,german:"die Rezession",level:"B2",english:"recession",pos:"noun (f)",sentences:[{"de": "Während der Rezession sank die Wirtschaftsleistung des Landes erheblich.", "en": "During the recession, the country's economic output fell considerably."}, {"de": "Eine Rezession ist definiert als zwei aufeinander folgende Quartale mit negativem Wachstum.", "en": "A recession is defined as two consecutive quarters of negative growth."}]},
  {id:1350,german:"der Aufschwung",level:"B2",english:"upturn, boom, recovery",pos:"noun (m)",sentences:[{"de": "Nach der Krise erlebte die Wirtschaft einen kräftigen Aufschwung.", "en": "After the crisis, the economy experienced a strong upturn."}, {"de": "Der Aufschwung auf dem Arbeitsmarkt spiegelt sich in sinkenden Arbeitslosenzahlen wider.", "en": "The recovery in the labour market is reflected in falling unemployment figures."}]},
  {id:1351,german:"der Konjunkturzyklus",level:"B2",english:"business cycle, economic cycle",pos:"noun (m)",sentences:[{"de": "Der Konjunkturzyklus umfasst Phasen des Aufschwungs, der Hochkonjunktur, des Abschwungs und der Rezession.", "en": "The business cycle comprises phases of upturn, boom, downturn and recession."}, {"de": "Unternehmen müssen ihre Strategie dem jeweiligen Konjunkturzyklus anpassen.", "en": "Companies must adapt their strategy to the respective business cycle."}]},
  {id:1352,german:"das Bruttoinlandsprodukt",level:"B2",english:"gross domestic product (GDP)",pos:"noun (n)",sentences:[{"de": "Das Bruttoinlandsprodukt Deutschlands ist eines der höchsten in der Europäischen Union.", "en": "Germany's gross domestic product is one of the highest in the European Union."}, {"de": "Das Wachstum des Bruttoinlandsprodukts gilt als wichtiger Indikator für den wirtschaftlichen Wohlstand.", "en": "The growth of gross domestic product is considered an important indicator of economic prosperity."}]},
  {id:1353,german:"die Arbeitslosenquote",level:"B2",english:"unemployment rate",pos:"noun (f)",sentences:[{"de": "Die Arbeitslosenquote ist auf 5% gestiegen.", "en": "The unemployment rate has risen to 5%."}, {"de": "Eine niedrige Arbeitslosenquote deutet auf eine starke Wirtschaft hin.", "en": "A low unemployment rate indicates a strong economy."}]},
  {id:1354,german:"die Erwerbsquote",level:"B2",english:"employment rate, labour force participation rate",pos:"noun (f)",sentences:[{"de": "Die Erwerbsquote von Frauen hat sich in den letzten Jahrzehnten deutlich erhöht.", "en": "The labour force participation rate of women has increased significantly over recent decades."}, {"de": "Eine hohe Erwerbsquote ist ein Zeichen für eine funktionierende Wirtschaft.", "en": "A high employment rate is a sign of a functioning economy."}]},
  {id:1355,german:"der Fachkräftemangel",level:"B2",english:"skilled worker shortage",pos:"noun (m)",sentences:[{"de": "Der Fachkräftemangel in der Pflegebranche ist ein ernstes Problem.", "en": "The skilled worker shortage in the care sector is a serious problem."}, {"de": "Viele Unternehmen leiden unter dem anhaltenden Fachkräftemangel.", "en": "Many companies are suffering from the ongoing skilled worker shortage."}]},
  {id:1356,german:"der demografische Wandel",level:"B2",english:"demographic change",pos:"noun phrase (m)",sentences:[{"de": "Der demografische Wandel stellt das Rentensystem vor große Herausforderungen.", "en": "Demographic change poses major challenges for the pension system."}, {"de": "Aufgrund des demografischen Wandels wird die Bevölkerung immer älter.", "en": "Due to demographic change, the population is getting older and older."}]},
  {id:1357,german:"die Digitalisierung",level:"B2",english:"digitalisation, digitisation",pos:"noun (f)",sentences:[{"de": "Die Digitalisierung verändert die Arbeitswelt grundlegend.", "en": "Digitalisation is fundamentally changing the world of work."}, {"de": "Viele kleine Unternehmen haben Schwierigkeiten, mit der Digitalisierung Schritt zu halten.", "en": "Many small companies have difficulty keeping pace with digitalisation."}]},
  {id:1358,german:"die Automatisierung",level:"B2",english:"automation",pos:"noun (f)",sentences:[{"de": "Durch die Automatisierung fallen viele Routinearbeiten weg.", "en": "Through automation, many routine tasks are disappearing."}, {"de": "Die Automatisierung von Produktionsprozessen steigert die Effizienz erheblich.", "en": "The automation of production processes significantly increases efficiency."}]},
  {id:1359,german:"die künstliche Intelligenz",level:"B2",english:"artificial intelligence (AI)",pos:"noun phrase (f)",sentences:[{"de": "Künstliche Intelligenz wird bereits in vielen Bereichen des Alltags eingesetzt.", "en": "Artificial intelligence is already being used in many areas of everyday life."}, {"de": "Die Entwicklung der künstlichen Intelligenz schreitet rasant voran.", "en": "The development of artificial intelligence is advancing rapidly."}]},
  {id:1360,german:"das maschinelle Lernen",level:"B2",english:"machine learning",pos:"noun phrase (n)",sentences:[{"de": "Maschinelles Lernen ermöglicht es Computern, aus Daten zu lernen.", "en": "Machine learning enables computers to learn from data."}, {"de": "Viele Empfehlungssysteme basieren auf maschinellem Lernen.", "en": "Many recommendation systems are based on machine learning."}]},
  {id:1361,german:"die Datenanalyse",level:"B2",english:"data analysis",pos:"noun (f)",sentences:[{"de": "Die Datenanalyse hilft Unternehmen, bessere Entscheidungen zu treffen.", "en": "Data analysis helps companies make better decisions."}, {"de": "Für die Datenanalyse werden spezielle Softwareprogramme verwendet.", "en": "Special software programs are used for data analysis."}]},
  {id:1362,german:"der Algorithmus",level:"B2",english:"algorithm",pos:"noun (m)",sentences:[{"de": "Soziale Netzwerke nutzen Algorithmen, um Inhalte zu sortieren.", "en": "Social networks use algorithms to sort content."}, {"de": "Ein effizienter Algorithmus kann komplexe Probleme schnell lösen.", "en": "An efficient algorithm can solve complex problems quickly."}]},
  {id:1363,german:"die Software",level:"B2",english:"software",pos:"noun (f)",sentences:[{"de": "Die neue Software wurde erfolgreich auf allen Computern installiert.", "en": "The new software was successfully installed on all computers."}, {"de": "Regelmäßige Software-Updates sind wichtig für die Sicherheit.", "en": "Regular software updates are important for security."}]},
  {id:1364,german:"die Hardware",level:"B2",english:"hardware",pos:"noun (f)",sentences:[{"de": "Die Hardware des alten Computers ist nicht mehr leistungsfähig genug.", "en": "The hardware of the old computer is no longer powerful enough."}, {"de": "Für moderne Anwendungen benötigt man leistungsstarke Hardware.", "en": "Modern applications require powerful hardware."}]},
  {id:1365,german:"das Betriebssystem",level:"B2",english:"operating system",pos:"noun (n)",sentences:[{"de": "Das Betriebssystem verwaltet alle Ressourcen des Computers.", "en": "The operating system manages all of the computer's resources."}, {"de": "Nach dem Update des Betriebssystems lief der Computer wieder reibungslos.", "en": "After the operating system update, the computer ran smoothly again."}]},
  {id:1366,german:"die Anwendung",level:"B2",english:"application, app; use",pos:"noun (f)",sentences:[{"de": "Diese Anwendung erleichtert die Verwaltung von Terminen erheblich.", "en": "This application greatly simplifies appointment management."}, {"de": "Die praktische Anwendung der Theorie ist oft schwieriger als erwartet.", "en": "The practical application of theory is often more difficult than expected."}]},
  {id:1367,german:"die App",level:"B2",english:"app, application",pos:"noun (f)",sentences:[{"de": "Es gibt eine nützliche App, mit der man den Nahverkehr planen kann.", "en": "There is a useful app for planning public transport."}, {"de": "Die App wurde innerhalb einer Woche eine Million Mal heruntergeladen.", "en": "The app was downloaded one million times within a week."}]},
  {id:1368,german:"das Interface",level:"B2",english:"interface",pos:"noun (n)",sentences:[{"de": "Ein benutzerfreundliches Interface ist entscheidend für den Erfolg einer App.", "en": "A user-friendly interface is crucial for the success of an app."}, {"de": "Das Interface der neuen Software wurde komplett überarbeitet.", "en": "The interface of the new software has been completely revised."}]},
  {id:1369,german:"die Datenbank",level:"B2",english:"database",pos:"noun (f)",sentences:[{"de": "Alle Kundendaten werden in einer zentralen Datenbank gespeichert.", "en": "All customer data is stored in a central database."}, {"de": "Die Datenbank muss regelmäßig gesichert werden.", "en": "The database must be backed up regularly."}]},
  {id:1370,german:"die Cloud",level:"B2",english:"cloud (computing)",pos:"noun (f)",sentences:[{"de": "Ich speichere meine Dokumente in der Cloud, damit ich überall darauf zugreifen kann.", "en": "I store my documents in the cloud so I can access them anywhere."}, {"de": "Viele Unternehmen verlagern ihre IT-Infrastruktur in die Cloud.", "en": "Many companies are moving their IT infrastructure to the cloud."}]},
  {id:1371,german:"die Cybersicherheit",level:"B2",english:"cybersecurity",pos:"noun (f)",sentences:[{"de": "Cybersicherheit ist für Unternehmen ein immer wichtigeres Thema.", "en": "Cybersecurity is an increasingly important issue for companies."}, {"de": "Es werden verstärkt Investitionen in die Cybersicherheit getätigt.", "en": "Investments in cybersecurity are being increasingly made."}]},
  {id:1372,german:"der Datenschutz",level:"B2",english:"data protection, privacy",pos:"noun (m)",sentences:[{"de": "Der Datenschutz in Europa wird durch die DSGVO geregelt.", "en": "Data protection in Europe is regulated by the GDPR."}, {"de": "Beim Umgang mit persönlichen Daten muss der Datenschutz stets beachtet werden.", "en": "Data protection must always be observed when handling personal data."}]},
  {id:1373,german:"die Verschlüsselung",level:"B2",english:"encryption",pos:"noun (f)",sentences:[{"de": "Die Verschlüsselung von Nachrichten schützt die Privatsphäre der Nutzer.", "en": "The encryption of messages protects users' privacy."}, {"de": "Ende-zu-Ende-Verschlüsselung gilt als besonders sicher.", "en": "End-to-end encryption is considered particularly secure."}]},
  {id:1374,german:"das Passwort",level:"B2",english:"password",pos:"noun (n)",sentences:[{"de": "Ein sicheres Passwort sollte mindestens acht Zeichen lang sein.", "en": "A secure password should be at least eight characters long."}, {"de": "Es ist wichtig, für jeden Dienst ein anderes Passwort zu verwenden.", "en": "It is important to use a different password for each service."}]},
  {id:1375,german:"die Authentifizierung",level:"B2",english:"authentication",pos:"noun (f)",sentences:[{"de": "Die Zwei-Faktor-Authentifizierung erhöht die Sicherheit von Online-Konten.", "en": "Two-factor authentication increases the security of online accounts."}, {"de": "Für den Zugriff auf sensible Daten ist eine starke Authentifizierung erforderlich.", "en": "Strong authentication is required to access sensitive data."}]},
  {id:1376,german:"die Belegschaft",level:"B2",english:"workforce, staff, employees",pos:"noun (f)",sentences:[{"de": "Die Belegschaft wurde über die geplanten Umstrukturierungen informiert.", "en": "The workforce was informed about the planned restructuring."}, {"de": "Das Unternehmen möchte die Belegschaft in den nächsten Jahren vergrößern.", "en": "The company wants to grow its workforce in the coming years."}]},
  {id:1377,german:"die Gleichberechtigung",level:"B2",english:"equal rights, gender equality",pos:"noun (f)",sentences:[{"de": "Die Gleichberechtigung von Männern und Frauen ist ein grundlegendes Recht.", "en": "The equal rights of men and women is a fundamental right."}, {"de": "Trotz großer Fortschritte ist die vollständige Gleichberechtigung noch nicht erreicht.", "en": "Despite great progress, full gender equality has not yet been achieved."}]},
  {id:1378,german:"die Integration",level:"B2",english:"integration",pos:"noun (f)",sentences:[{"de": "Die Integration von Einwanderern in den Arbeitsmarkt ist eine gesellschaftliche Aufgabe.", "en": "The integration of immigrants into the labour market is a societal task."}, {"de": "Gelungene Integration erfordert Engagement von beiden Seiten.", "en": "Successful integration requires commitment from both sides."}]},
  {id:1379,german:"der/die Nachfolger/-in",level:"B2",english:"successor",pos:"noun (m/f)",sentences:[{"de": "Der Vorstandsvorsitzende hat bereits einen Nachfolger ernannt.", "en": "The CEO has already appointed a successor."}, {"de": "Die Nachfolgerin wurde aus den eigenen Reihen des Unternehmens ausgewählt.", "en": "The successor was selected from within the company's own ranks."}]},
  {id:1380,german:"der/die Schwerbehinderte",level:"B2",english:"severely disabled person",pos:"noun (m/f)",sentences:[{"de": "Arbeitgeber sind verpflichtet, einen bestimmten Anteil an Schwerbehinderten einzustellen.", "en": "Employers are obliged to hire a certain proportion of severely disabled persons."}, {"de": "Schwerbehinderte haben Anspruch auf besonderen Kündigungsschutz.", "en": "Severely disabled persons are entitled to special protection against dismissal."}]},
  {id:1381,german:"die Inklusion",level:"B2",english:"inclusion",pos:"noun (f)",sentences:[{"de": "Inklusion bedeutet, dass alle Menschen gleichberechtigt am gesellschaftlichen Leben teilhaben.", "en": "Inclusion means that all people participate in social life on an equal footing."}, {"de": "Schulen arbeiten daran, Inklusion für Kinder mit Behinderungen zu verwirklichen.", "en": "Schools are working to realise inclusion for children with disabilities."}]},
  {id:1382,german:"die Diversität",level:"B2",english:"diversity",pos:"noun (f)",sentences:[{"de": "Diversität im Team fördert Kreativität und Innovation.", "en": "Diversity in the team promotes creativity and innovation."}, {"de": "Das Unternehmen setzt sich aktiv für mehr Diversität in Führungspositionen ein.", "en": "The company is actively committed to greater diversity in leadership positions."}]},
  {id:1383,german:"das Employer Branding",level:"B2",english:"employer branding",pos:"noun (n)",sentences:[{"de": "Erfolgreiches Employer Branding hilft dabei, qualifizierte Fachkräfte zu gewinnen.", "en": "Successful employer branding helps to attract qualified specialists."}, {"de": "Das Unternehmen investiert viel in sein Employer Branding.", "en": "The company invests heavily in its employer branding."}]},
  {id:1384,german:"die Unternehmenskultur",level:"B2",english:"corporate culture, company culture",pos:"noun (f)",sentences:[{"de": "Eine positive Unternehmenskultur trägt zur Mitarbeiterzufriedenheit bei.", "en": "A positive corporate culture contributes to employee satisfaction."}, {"de": "Bei der Jobsuche achten viele Bewerber auf die Unternehmenskultur.", "en": "Many applicants pay attention to company culture when looking for a job."}]},
  {id:1385,german:"das Betriebsklima",level:"B2",english:"workplace atmosphere, working climate",pos:"noun (n)",sentences:[{"de": "Ein gutes Betriebsklima steigert die Produktivität der Mitarbeiter.", "en": "A good working climate increases employee productivity."}, {"de": "Die Konflikte im Team haben das Betriebsklima stark belastet.", "en": "The conflicts in the team have put a heavy strain on the workplace atmosphere."}]},
  {id:1386,german:"der Teamgeist",level:"B2",english:"team spirit",pos:"noun (m)",sentences:[{"de": "Der Teamgeist in unserer Abteilung ist vorbildlich.", "en": "The team spirit in our department is exemplary."}, {"de": "Gemeinsame Aktivitäten außerhalb der Arbeit stärken den Teamgeist.", "en": "Joint activities outside work strengthen team spirit."}]},
  {id:1387,german:"die Motivation",level:"B2",english:"motivation",pos:"noun (f)",sentences:[{"de": "Die Motivation der Mitarbeiter ist entscheidend für den Unternehmenserfolg.", "en": "Employee motivation is crucial for company success."}, {"de": "Finanzielle Anreize allein reichen nicht aus, um die Motivation langfristig aufrechtzuerhalten.", "en": "Financial incentives alone are not sufficient to maintain motivation in the long term."}]},
  {id:1388,german:"die Zufriedenheit",level:"B2",english:"satisfaction, contentment",pos:"noun (f)",sentences:[{"de": "Die Zufriedenheit am Arbeitsplatz hängt von vielen Faktoren ab.", "en": "Satisfaction in the workplace depends on many factors."}, {"de": "Regelmäßige Umfragen messen die Zufriedenheit der Kunden.", "en": "Regular surveys measure customer satisfaction."}]},
  {id:1389,german:"die Loyalität",level:"B2",english:"loyalty",pos:"noun (f)",sentences:[{"de": "Die Loyalität der langjährigen Mitarbeiter ist ein wertvolles Gut für das Unternehmen.", "en": "The loyalty of long-standing employees is a valuable asset for the company."}, {"de": "Loyalität gegenüber dem Arbeitgeber wird oft durch faire Bezahlung gefördert.", "en": "Loyalty towards the employer is often encouraged through fair pay."}]},
  {id:1390,german:"das Engagement",level:"B2",english:"commitment, dedication, engagement",pos:"noun (n)",sentences:[{"de": "Ihr Engagement für das Projekt war außergewöhnlich.", "en": "Her commitment to the project was extraordinary."}, {"de": "Soziales Engagement ist für viele Menschen ein wichtiger Teil ihres Lebens.", "en": "Social engagement is an important part of many people's lives."}]},
  {id:1391,german:"die Eigeninitiative",level:"B2",english:"own initiative, self-initiative",pos:"noun (f)",sentences:[{"de": "Eigeninitiative wird bei vielen Arbeitgebern sehr geschätzt.", "en": "Self-initiative is highly valued by many employers."}, {"de": "Er hat das Problem aus eigener Eigeninitiative gelöst, ohne auf Anweisungen zu warten.", "en": "He solved the problem on his own initiative without waiting for instructions."}]},
  {id:1392,german:"die Selbstständigkeit",level:"B2",english:"independence, self-employment",pos:"noun (f)",sentences:[{"de": "Nach Jahren im Angestelltenverhältnis wagte sie den Schritt in die Selbstständigkeit.", "en": "After years as an employee, she took the step into self-employment."}, {"de": "Selbstständigkeit im Denken und Handeln ist eine wichtige Eigenschaft.", "en": "Independence in thinking and acting is an important quality."}]},
  {id:1393,german:"die Zuverlässigkeit",level:"B2",english:"reliability, dependability",pos:"noun (f)",sentences:[{"de": "Zuverlässigkeit ist eine der wichtigsten Eigenschaften eines guten Mitarbeiters.", "en": "Reliability is one of the most important qualities of a good employee."}, {"de": "Die Zuverlässigkeit des Zulieferers ist entscheidend für unsere Produktion.", "en": "The reliability of the supplier is crucial for our production."}]},
  {id:1394,german:"die Pünktlichkeit",level:"B2",english:"punctuality",pos:"noun (f)",sentences:[{"de": "Pünktlichkeit gilt in Deutschland als Zeichen von Respekt und Professionalität.", "en": "Punctuality is considered a sign of respect and professionalism in Germany."}, {"de": "Die Pünktlichkeit der Deutschen Bahn lässt manchmal zu wünschen übrig.", "en": "The punctuality of Deutsche Bahn sometimes leaves something to be desired."}]},
  {id:1395,german:"die Genauigkeit",level:"B2",english:"accuracy, precision",pos:"noun (f)",sentences:[{"de": "In wissenschaftlichen Experimenten ist höchste Genauigkeit erforderlich.", "en": "The highest level of accuracy is required in scientific experiments."}, {"de": "Die Genauigkeit seiner Berichte ist bekannt und geschätzt.", "en": "The accuracy of his reports is well known and appreciated."}]},
  {id:1396,german:"die Sorgfalt",level:"B2",english:"care, diligence, thoroughness",pos:"noun (f)",sentences:[{"de": "Die Arbeiten wurden mit großer Sorgfalt ausgeführt.", "en": "The work was carried out with great care."}, {"de": "Rechtliche Dokumente müssen mit äußerster Sorgfalt geprüft werden.", "en": "Legal documents must be checked with the utmost diligence."}]},
  {id:1397,german:"das Verantwortungsbewusstsein",level:"B2",english:"sense of responsibility",pos:"noun (n)",sentences:[{"de": "Verantwortungsbewusstsein ist eine Grundvoraussetzung für Führungskräfte.", "en": "A sense of responsibility is a basic requirement for managers."}, {"de": "Ihr ausgeprägtes Verantwortungsbewusstsein machte sie zur idealen Kandidatin.", "en": "Her strong sense of responsibility made her the ideal candidate."}]},
  {id:1398,german:"die Belastbarkeit",level:"B2",english:"resilience, ability to work under pressure",pos:"noun (f)",sentences:[{"de": "In stressigen Phasen ist eine hohe Belastbarkeit gefragt.", "en": "High resilience is required during stressful periods."}, {"de": "Seine Belastbarkeit unter Druck ist eine seiner größten Stärken.", "en": "His ability to work under pressure is one of his greatest strengths."}]},
  {id:1399,german:"die Flexibilität",level:"B2",english:"flexibility",pos:"noun (f)",sentences:[{"de": "Flexibilität bezüglich der Arbeitszeiten ist für viele Arbeitnehmer wichtig.", "en": "Flexibility regarding working hours is important for many employees."}, {"de": "Die Flexibilität des Unternehmens ermöglicht es, schnell auf Marktveränderungen zu reagieren.", "en": "The company's flexibility makes it possible to respond quickly to market changes."}]},
  {id:1400,german:"die Anpassungsfähigkeit",level:"B2",english:"adaptability",pos:"noun (f)",sentences:[{"de": "Anpassungsfähigkeit ist in einer sich schnell verändernden Arbeitswelt unerlässlich.", "en": "Adaptability is indispensable in a rapidly changing world of work."}, {"de": "Die Anpassungsfähigkeit des Teams hat uns durch die schwierige Zeit gebracht.", "en": "The team's adaptability carried us through the difficult period."}]},
  {id:1401,german:"die Kommunikationsfähigkeit",level:"B2",english:"communication skills",pos:"noun (f)",sentences:[{"de": "Gute Kommunikationsfähigkeit ist in fast allen Berufen wichtig.", "en": "Good communication skills are important in almost all professions."}, {"de": "Im Vorstellungsgespräch wird die Kommunikationsfähigkeit der Bewerber bewertet.", "en": "The communication skills of applicants are assessed in job interviews."}]},
  {id:1402,german:"die Teamfähigkeit",level:"B2",english:"ability to work in a team",pos:"noun (f)",sentences:[{"de": "Teamfähigkeit steht in den meisten Stellenanzeigen ganz oben auf der Anforderungsliste.", "en": "The ability to work in a team is at the top of the requirements list in most job advertisements."}, {"de": "Er bewies seine Teamfähigkeit durch die erfolgreiche Zusammenarbeit mit verschiedenen Kollegen.", "en": "He demonstrated his ability to work in a team through successful collaboration with various colleagues."}]},
  {id:1403,german:"die Führungskompetenz",level:"B2",english:"leadership competence, leadership skills",pos:"noun (f)",sentences:[{"de": "Führungskompetenz lässt sich durch gezielte Weiterbildungen entwickeln.", "en": "Leadership skills can be developed through targeted training."}, {"de": "Sie überzeugte den Vorstand durch ihre ausgeprägte Führungskompetenz.", "en": "She convinced the board with her strong leadership competence."}]},
  {id:1404,german:"die Entscheidungsfähigkeit",level:"B2",english:"decision-making ability",pos:"noun (f)",sentences:[{"de": "In Krisenzeiten ist eine schnelle Entscheidungsfähigkeit besonders wichtig.", "en": "In times of crisis, rapid decision-making ability is particularly important."}, {"de": "Gute Führungskräfte zeichnen sich durch ihre Entscheidungsfähigkeit aus.", "en": "Good leaders are distinguished by their decision-making ability."}]},
  {id:1405,german:"die Problemlösungsfähigkeit",level:"B2",english:"problem-solving ability",pos:"noun (f)",sentences:[{"de": "Problemlösungsfähigkeit ist eine der gefragtesten Kompetenzen auf dem Arbeitsmarkt.", "en": "Problem-solving ability is one of the most sought-after skills in the labour market."}, {"de": "Das schwierige Projekt schärfte ihre Problemlösungsfähigkeit erheblich.", "en": "The difficult project considerably sharpened her problem-solving ability."}]},
  {id:1406,german:"die Kreativität",level:"B2",english:"creativity",pos:"noun (f)",sentences:[{"de": "Kreativität ist in der Werbebranche eine unverzichtbare Eigenschaft.", "en": "Creativity is an indispensable quality in the advertising industry."}, {"de": "Durch regelmäßige Pausen kann man die Kreativität fördern.", "en": "Regular breaks can promote creativity."}]},
  {id:1407,german:"die Innovationsfähigkeit",level:"B2",english:"ability to innovate",pos:"noun (f)",sentences:[{"de": "Die Innovationsfähigkeit eines Unternehmens entscheidet über seinen langfristigen Erfolg.", "en": "A company's ability to innovate determines its long-term success."}, {"de": "Forschung und Entwicklung sind die Grundlage für Innovationsfähigkeit.", "en": "Research and development are the foundation of the ability to innovate."}]},
  {id:1408,german:"das Denkvermögen",level:"B2",english:"thinking capacity, reasoning ability",pos:"noun (n)",sentences:[{"de": "Schachspielen soll das Denkvermögen von Kindern fördern.", "en": "Playing chess is said to promote children's reasoning ability."}, {"de": "Sein analytisches Denkvermögen ist eine große Stärke.", "en": "His analytical thinking capacity is a great strength."}]},
  {id:1409,german:"die Analysefähigkeit",level:"B2",english:"analytical ability",pos:"noun (f)",sentences:[{"de": "In diesem Beruf ist eine ausgeprägte Analysefähigkeit notwendig.", "en": "In this profession, a strong analytical ability is necessary."}, {"de": "Ihre Analysefähigkeit half ihr, das Problem schnell zu verstehen.", "en": "Her analytical ability helped her understand the problem quickly."}]},
  {id:1410,german:"die Lernbereitschaft",level:"B2",english:"willingness to learn",pos:"noun (f)",sentences:[{"de": "Lernbereitschaft ist in einer Zeit des schnellen Wandels unerlässlich.", "en": "Willingness to learn is indispensable in an era of rapid change."}, {"de": "Arbeitgeber schätzen Mitarbeiter mit hoher Lernbereitschaft.", "en": "Employers value employees with a high willingness to learn."}]},
  {id:1411,german:"die Lernfähigkeit",level:"B2",english:"ability to learn",pos:"noun (f)",sentences:[{"de": "Die Lernfähigkeit des Gehirns bleibt bis ins hohe Alter erhalten.", "en": "The brain's ability to learn is maintained into old age."}, {"de": "Eine hohe Lernfähigkeit ist ein entscheidender Vorteil im Berufsleben.", "en": "A high ability to learn is a decisive advantage in professional life."}]},
  {id:1412,german:"die Wissensdurst",level:"B2",english:"thirst for knowledge",pos:"noun (m)",sentences:[{"de": "Der Wissensdurst des jungen Wissenschaftlers trieb ihn zu immer neuen Entdeckungen.", "en": "The young scientist's thirst for knowledge drove him to ever new discoveries."}, {"de": "Kinder haben von Natur aus einen starken Wissensdurst.", "en": "Children have a natural thirst for knowledge."}]},
  {id:1413,german:"die Neugier",level:"B2",english:"curiosity",pos:"noun (f)",sentences:[{"de": "Neugier ist eine wichtige Triebkraft für Lernen und Entdecken.", "en": "Curiosity is an important driving force for learning and discovery."}, {"de": "Aus reiner Neugier fragte er, wie das Gerät funktioniert.", "en": "Out of pure curiosity, he asked how the device works."}]},
  {id:1414,german:"die Offenheit",level:"B2",english:"openness",pos:"noun (f)",sentences:[{"de": "Offenheit gegenüber neuen Ideen ist eine wichtige Eigenschaft für Führungskräfte.", "en": "Openness to new ideas is an important quality for leaders."}, {"de": "Sie schätzte seine Offenheit bei Diskussionen sehr.", "en": "She greatly appreciated his openness in discussions."}]},
  {id:1415,german:"die Toleranz",level:"B2",english:"tolerance",pos:"noun (f)",sentences:[{"de": "Toleranz gegenüber anderen Meinungen ist ein Grundpfeiler der Demokratie.", "en": "Tolerance towards other opinions is a cornerstone of democracy."}, {"de": "In einer vielfältigen Gesellschaft ist gegenseitige Toleranz unerlässlich.", "en": "In a diverse society, mutual tolerance is indispensable."}]},
  {id:1416,german:"der Respekt",level:"B2",english:"respect",pos:"noun (m)",sentences:[{"de": "Gegenseitiger Respekt ist die Grundlage für jede gute Zusammenarbeit.", "en": "Mutual respect is the foundation of any good collaboration."}, {"de": "Er genießt den Respekt seiner Kollegen wegen seiner Fairness.", "en": "He enjoys the respect of his colleagues because of his fairness."}]},
  {id:1417,german:"die Wertschätzung",level:"B2",english:"appreciation, esteem",pos:"noun (f)",sentences:[{"de": "Regelmäßige Wertschätzung durch Vorgesetzte motiviert die Mitarbeiter.", "en": "Regular appreciation from supervisors motivates employees."}, {"de": "Er zeigte seine Wertschätzung für ihre Arbeit durch ein Lob in der Teamsitzung.", "en": "He showed his appreciation for her work with a compliment at the team meeting."}]},
  {id:1418,german:"die Anerkennung",level:"B2",english:"recognition, acknowledgement",pos:"noun (f)",sentences:[{"de": "Die Anerkennung für ihre Leistungen motivierte sie, noch härter zu arbeiten.", "en": "The recognition for her achievements motivated her to work even harder."}, {"de": "Öffentliche Anerkennung ist für viele Menschen wichtiger als eine Gehaltserhöhung.", "en": "Public recognition is more important to many people than a pay rise."}]},
  {id:1419,german:"die Kritikfähigkeit",level:"B2",english:"ability to accept criticism",pos:"noun (f)",sentences:[{"de": "Kritikfähigkeit zu entwickeln ist ein wichtiger Teil der persönlichen Reife.", "en": "Developing the ability to accept criticism is an important part of personal maturity."}, {"de": "Wer nicht kritikfähig ist, kann sich kaum weiterentwickeln.", "en": "Those who cannot accept criticism can hardly develop further."}]},
  {id:1420,german:"die Konfliktfähigkeit",level:"B2",english:"ability to handle conflict",pos:"noun (f)",sentences:[{"de": "Konfliktfähigkeit bedeutet, Meinungsverschiedenheiten konstruktiv zu lösen.", "en": "The ability to handle conflict means resolving disagreements constructively."}, {"de": "In Teamarbeit ist Konfliktfähigkeit besonders wichtig.", "en": "The ability to handle conflict is particularly important in teamwork."}]},
  {id:1421,german:"das Verhandlungsgeschick",level:"B2",english:"negotiating skill",pos:"noun (n)",sentences:[{"de": "Sein Verhandlungsgeschick brachte dem Unternehmen einen vorteilhaften Vertrag.", "en": "His negotiating skill brought the company an advantageous contract."}, {"de": "Gutes Verhandlungsgeschick ist im Einkauf unerlässlich.", "en": "Good negotiating skill is indispensable in purchasing."}]},
  {id:1422,german:"das Einfühlungsvermögen",level:"B2",english:"empathy, sensitivity",pos:"noun (n)",sentences:[{"de": "Ein guter Therapeut braucht ein hohes Maß an Einfühlungsvermögen.", "en": "A good therapist needs a high degree of empathy."}, {"de": "Ihr Einfühlungsvermögen macht sie zu einer geschätzten Kollegin.", "en": "Her sensitivity makes her a valued colleague."}]},
  {id:1423,german:"die Empathie",level:"B2",english:"empathy",pos:"noun (f)",sentences:[{"de": "Empathie ist die Fähigkeit, sich in die Lage anderer Menschen zu versetzen.", "en": "Empathy is the ability to put oneself in the position of others."}, {"de": "Im Umgang mit Kunden ist Empathie eine unverzichtbare Eigenschaft.", "en": "In dealing with customers, empathy is an indispensable quality."}]},
  {id:1424,german:"die soziale Kompetenz",level:"B2",english:"social competence, social skills",pos:"noun phrase (f)",sentences:[{"de": "Soziale Kompetenz umfasst Fähigkeiten wie Kommunikation und Kooperation.", "en": "Social competence encompasses skills such as communication and cooperation."}, {"de": "Soziale Kompetenz lässt sich durch Training und Erfahrung verbessern.", "en": "Social competence can be improved through training and experience."}]},
  {id:1425,german:"die interkulturelle Kompetenz",level:"B2",english:"intercultural competence",pos:"noun phrase (f)",sentences:[{"de": "In internationalen Unternehmen ist interkulturelle Kompetenz sehr gefragt.", "en": "In international companies, intercultural competence is in great demand."}, {"de": "Auslandsaufenthalte fördern die interkulturelle Kompetenz erheblich.", "en": "Stays abroad considerably promote intercultural competence."}]},
  {id:1426,german:"der Solidaritätszuschlag",level:"B2",english:"solidarity surcharge",pos:"noun (m)",sentences:[{"de": "Der Solidaritätszuschlag wurde ursprünglich zur Finanzierung der deutschen Einheit eingeführt.", "en": "The solidarity surcharge was originally introduced to finance German reunification."}, {"de": "Für viele Steuerzahler entfällt der Solidaritätszuschlag mittlerweile.", "en": "Many taxpayers are now no longer required to pay the solidarity surcharge."}]},
  {id:1427,german:"die Steuerklasse",level:"B2",english:"tax bracket, tax class",pos:"noun (f)",sentences:[{"de": "Verheiratete Paare können zwischen verschiedenen Steuerklassen wählen.", "en": "Married couples can choose between different tax classes."}, {"de": "Die Steuerklasse hat Einfluss auf die Höhe des monatlichen Nettolohns.", "en": "The tax class influences the level of the monthly net salary."}]},
  {id:1428,german:"abziehen",level:"B2",english:"to deduct, to subtract, to pull off",pos:"verb",sentences:[{"de": "Von dem Bruttogehalt werden Steuern und Sozialabgaben abgezogen.", "en": "Taxes and social security contributions are deducted from the gross salary."}, {"de": "Er zog die Kosten für Arbeitsmittel von der Steuer ab.", "en": "He deducted the costs for work equipment from his taxes."}]},
  {id:1429,german:"einbehalten",level:"B2",english:"to withhold, to retain, to keep back",pos:"verb",sentences:[{"de": "Der Arbeitgeber behält die Lohnsteuer direkt vom Gehalt ein.", "en": "The employer withholds the wage tax directly from the salary."}, {"de": "Die Kaution wurde wegen der Schäden in der Wohnung einbehalten.", "en": "The deposit was retained because of the damage in the apartment."}]},
  {id:1430,german:"die Arbeitszeit",level:"B2",english:"working hours",pos:"noun (f)",sentences:[{"de": "Die gesetzliche Arbeitszeit beträgt in Deutschland maximal acht Stunden pro Tag.", "en": "The statutory working hours in Germany are a maximum of eight hours per day."}, {"de": "Flexible Arbeitszeit erleichtert die Vereinbarkeit von Familie und Beruf.", "en": "Flexible working hours make it easier to balance family and work."}]},
  {id:1431,german:"das Arbeitszeitkonto",level:"B2",english:"working time account, flexitime account",pos:"noun (n)",sentences:[{"de": "Auf seinem Arbeitszeitkonto hatte er 20 Überstunden angesammelt.", "en": "He had accumulated 20 hours of overtime in his working time account."}, {"de": "Das Arbeitszeitkonto ermöglicht es, Mehrarbeit flexibel auszugleichen.", "en": "The working time account makes it possible to compensate for overtime flexibly."}]},
  {id:1432,german:"die Überstundenvergütung",level:"B2",english:"overtime pay",pos:"noun (f)",sentences:[{"de": "Die Überstundenvergütung ist im Arbeitsvertrag klar geregelt.", "en": "Overtime pay is clearly regulated in the employment contract."}, {"de": "Er bat seinen Vorgesetzten um die Auszahlung seiner Überstundenvergütung.", "en": "He asked his supervisor for payment of his overtime pay."}]},
  {id:1433,german:"der Urlaubsanspruch",level:"B2",english:"holiday entitlement, annual leave entitlement",pos:"noun (m)",sentences:[{"de": "In Deutschland besteht ein gesetzlicher Urlaubsanspruch von mindestens 20 Tagen.", "en": "In Germany, the statutory holiday entitlement is at least 20 days."}, {"de": "Ihr Urlaubsanspruch verfällt am Ende des Jahres.", "en": "Her holiday entitlement expires at the end of the year."}]},
  {id:1434,german:"der Jahresurlaub",level:"B2",english:"annual holiday, annual leave",pos:"noun (m)",sentences:[{"de": "Sie plant ihren Jahresurlaub immer Monate im Voraus.", "en": "She always plans her annual holiday months in advance."}, {"de": "Der Jahresurlaub beträgt in ihrem Unternehmen 30 Tage.", "en": "Annual leave in her company is 30 days."}]},
  {id:1435,german:"der Sonderurlaub",level:"B2",english:"special leave",pos:"noun (m)",sentences:[{"de": "Bei Heirat haben Arbeitnehmer in der Regel Anspruch auf Sonderurlaub.", "en": "Employees are generally entitled to special leave on marriage."}, {"de": "Er beantragte Sonderurlaub wegen eines Todesfalles in der Familie.", "en": "He applied for special leave due to a bereavement in the family."}]},
  {id:1436,german:"die Elternzeit",level:"B2",english:"parental leave",pos:"noun (f)",sentences:[{"de": "Immer mehr Väter nehmen Elternzeit, um sich um ihre Kinder zu kümmern.", "en": "More and more fathers are taking parental leave to look after their children."}, {"de": "Sie kehrte nach der Elternzeit in Teilzeit in ihren Beruf zurück.", "en": "She returned to work part-time after parental leave."}]},
  {id:1437,german:"das Elterngeld",level:"B2",english:"parental allowance, parental benefit",pos:"noun (n)",sentences:[{"de": "Das Elterngeld beträgt in der Regel 65 Prozent des letzten Nettoeinkommens.", "en": "Parental allowance is generally 65 percent of the last net income."}, {"de": "Elterngeld kann von beiden Elternteilen in Anspruch genommen werden.", "en": "Parental benefit can be claimed by both parents."}]},
  {id:1438,german:"das Kindergeld",level:"B2",english:"child benefit",pos:"noun (n)",sentences:[{"de": "In Deutschland wird Kindergeld für jedes Kind bis zum 18. Lebensjahr gezahlt.", "en": "In Germany, child benefit is paid for every child until the age of 18."}, {"de": "Das Kindergeld soll Familien bei den Kosten für ihre Kinder unterstützen.", "en": "Child benefit is intended to support families with the costs of raising children."}]},
  {id:1439,german:"das Kurzarbeitergeld",level:"B2",english:"short-time working benefit",pos:"noun (n)",sentences:[{"de": "Während der Krise halfen viele Unternehmen ihren Mitarbeitern durch Kurzarbeitergeld.", "en": "During the crisis, many companies helped their employees through short-time working benefit."}, {"de": "Das Kurzarbeitergeld verhinderte in der Pandemie Massenentlassungen.", "en": "Short-time working benefit prevented mass redundancies during the pandemic."}]},
  {id:1440,german:"das Arbeitslosengeld",level:"B2",english:"unemployment benefit",pos:"noun (n)",sentences:[{"de": "Nach der Kündigung bezog er mehrere Monate lang Arbeitslosengeld.", "en": "After being made redundant, he received unemployment benefit for several months."}, {"de": "Der Anspruch auf Arbeitslosengeld hängt von der Dauer der vorherigen Beschäftigung ab.", "en": "Entitlement to unemployment benefit depends on the length of previous employment."}]},
  {id:1441,german:"die Grundsicherung",level:"B2",english:"basic income support, basic security",pos:"noun (f)",sentences:[{"de": "Grundsicherung soll das Existenzminimum der Bevölkerung sichern.", "en": "Basic income support is intended to safeguard the minimum subsistence level of the population."}, {"de": "Ältere Menschen ohne ausreichende Rente können Grundsicherung beantragen.", "en": "Elderly people without a sufficient pension can apply for basic income support."}]},
  {id:1442,german:"das Sozialgeld",level:"B2",english:"social welfare payment",pos:"noun (n)",sentences:[{"de": "Sozialgeld wird an Kinder in Bedarfsgemeinschaften ausgezahlt.", "en": "Social welfare payments are paid to children in benefit communities."}, {"de": "Die Höhe des Sozialgeldes richtet sich nach dem Alter des Kindes.", "en": "The amount of the social welfare payment depends on the age of the child."}]},
  {id:1443,german:"die Rente",level:"B2",english:"pension, retirement",pos:"noun (f)",sentences:[{"de": "Er geht in zwei Jahren in Rente und freut sich darauf.", "en": "He retires in two years and is looking forward to it."}, {"de": "Die Höhe der Rente hängt von den eingezahlten Beiträgen ab.", "en": "The amount of the pension depends on the contributions paid in."}]},
  {id:1444,german:"die Altersrente",level:"B2",english:"old-age pension",pos:"noun (f)",sentences:[{"de": "Ab 67 Jahren hat man in Deutschland Anspruch auf die volle Altersrente.", "en": "At 67, people in Germany are entitled to the full old-age pension."}, {"de": "Ihre Altersrente wird aufgrund der vielen Beitragsjahre recht hoch sein.", "en": "Her old-age pension will be quite high due to the many years of contributions."}]},
  {id:1445,german:"die Erwerbsminderungsrente",level:"B2",english:"reduced earning capacity pension",pos:"noun (f)",sentences:[{"de": "Nach dem Unfall konnte er nicht mehr arbeiten und beantragte Erwerbsminderungsrente.", "en": "After the accident, he could no longer work and applied for a reduced earning capacity pension."}, {"de": "Die Erwerbsminderungsrente wird gezahlt, wenn man weniger als drei Stunden täglich arbeiten kann.", "en": "The reduced earning capacity pension is paid when a person can work less than three hours a day."}]},
  {id:1446,german:"die Betriebsrente",level:"B2",english:"company pension, occupational pension",pos:"noun (f)",sentences:[{"de": "Viele Arbeitgeber bieten ihren Mitarbeitern eine Betriebsrente als Zusatzleistung an.", "en": "Many employers offer their employees a company pension as an additional benefit."}, {"de": "Die Betriebsrente ergänzt die gesetzliche Rentenversicherung.", "en": "The company pension supplements the statutory pension insurance."}]},
  {id:1447,german:"die private Rentenversicherung",level:"B2",english:"private pension insurance",pos:"noun phrase (f)",sentences:[{"de": "Wer früh mit einer privaten Rentenversicherung beginnt, profitiert vom Zinseszinseffekt.", "en": "Those who start a private pension insurance early benefit from the compound interest effect."}, {"de": "Die private Rentenversicherung dient als Ergänzung zur gesetzlichen Rente.", "en": "Private pension insurance serves as a supplement to the statutory pension."}]},
  {id:1448,german:"der Rentenbescheid",level:"B2",english:"pension notice, pension decision",pos:"noun (m)",sentences:[{"de": "Sie erhielt kurz vor ihrem 67. Geburtstag ihren Rentenbescheid.", "en": "She received her pension notice shortly before her 67th birthday."}, {"de": "Gegen einen fehlerhaften Rentenbescheid kann man Widerspruch einlegen.", "en": "An objection can be filed against an incorrect pension notice."}]},
  {id:1449,german:"die Renteninformation",level:"B2",english:"pension information",pos:"noun (f)",sentences:[{"de": "Die Deutsche Rentenversicherung schickt jährlich Renteninformationen an die Versicherten.", "en": "Deutsche Rentenversicherung sends annual pension information to insured persons."}, {"de": "Anhand der Renteninformation kann man seinen voraussichtlichen Rentenanspruch ermitteln.", "en": "The pension information can be used to determine one's expected pension entitlement."}]},
  {id:1450,german:"der Renteneintritt",level:"B2",english:"retirement, start of pension",pos:"noun (m)",sentences:[{"de": "Viele Menschen planen ihren Renteneintritt sorgfältig im Voraus.", "en": "Many people carefully plan their retirement well in advance."}, {"de": "Das Rentenalter bestimmt den regulären Zeitpunkt des Renteneintritts.", "en": "The pension age determines the regular time of retirement."}]},
  {id:1451,german:"das Rentenalter",level:"B2",english:"retirement age, pension age",pos:"noun (n)",sentences:[{"de": "Das Rentenalter wurde schrittweise auf 67 Jahre angehoben.", "en": "The retirement age was gradually raised to 67."}, {"de": "Diskussionen über eine weitere Anhebung des Rentenalters werden kontrovers geführt.", "en": "Discussions about a further increase in the retirement age are highly controversial."}]},
  {id:1452,german:"die Lebenserwartung",level:"B2",english:"life expectancy",pos:"noun (f)",sentences:[{"de": "Die Lebenserwartung in Deutschland ist in den letzten Jahrzehnten deutlich gestiegen.", "en": "Life expectancy in Germany has risen significantly in recent decades."}, {"de": "Eine gesunde Lebensweise kann die Lebenserwartung verlängern.", "en": "A healthy lifestyle can extend life expectancy."}]},
  {id:1453,german:"die Pflegeleistung",level:"B2",english:"care benefit, nursing care benefit",pos:"noun (f)",sentences:[{"de": "Die Pflegekasse übernimmt verschiedene Pflegeleistungen je nach Pflegegrad.", "en": "The long-term care insurance covers various care benefits depending on the care level."}, {"de": "Pflegeleistungen können ambulant oder stationär erbracht werden.", "en": "Care benefits can be provided on an outpatient or inpatient basis."}]},
  {id:1454,german:"die Pflegestufe",level:"B2",english:"care level, nursing care level",pos:"noun (f)",sentences:[{"de": "Sein Vater wurde in Pflegestufe 3 eingestuft, da er intensive Betreuung benötigt.", "en": "His father was classified at care level 3 as he requires intensive care."}, {"de": "Die Pflegestufe bestimmt, wie viel Unterstützung eine Person erhält.", "en": "The care level determines how much support a person receives."}]},
  {id:1455,german:"das Pflegeheim",level:"B2",english:"nursing home, care home",pos:"noun (n)",sentences:[{"de": "Ihre Großmutter lebt seit zwei Jahren in einem Pflegeheim.", "en": "Her grandmother has been living in a nursing home for two years."}, {"de": "Die Kosten für ein Pflegeheim können sehr hoch sein.", "en": "The costs of a nursing home can be very high."}]},
  {id:1456,german:"die ambulante Pflege",level:"B2",english:"outpatient care, home nursing care",pos:"noun phrase (f)",sentences:[{"de": "Ambulante Pflege ermöglicht es, zu Hause gepflegt zu werden.", "en": "Outpatient care makes it possible to be cared for at home."}, {"de": "Viele ältere Menschen bevorzugen ambulante Pflege gegenüber einem Pflegeheim.", "en": "Many elderly people prefer home nursing care to a nursing home."}]},
  {id:1457,german:"die stationäre Pflege",level:"B2",english:"inpatient care, residential care",pos:"noun phrase (f)",sentences:[{"de": "Stationäre Pflege ist notwendig, wenn der Pflegebedarf zu hoch für häusliche Betreuung ist.", "en": "Inpatient care is necessary when the care needs are too high for home care."}, {"de": "Die Kosten für stationäre Pflege werden teilweise von der Pflegeversicherung übernommen.", "en": "The costs of inpatient care are partly covered by the long-term care insurance."}]},
  {id:1458,german:"die Pflegeperson",level:"B2",english:"carer, caregiver",pos:"noun (f)",sentences:[{"de": "Als Pflegeperson für ihre Mutter erhielt sie finanzielle Unterstützung.", "en": "As a carer for her mother, she received financial support."}, {"de": "Pflegepersonen leisten einen wichtigen Beitrag für die Gesellschaft.", "en": "Caregivers make an important contribution to society."}]},
  {id:1459,german:"der/die Pflegebedürftige",level:"B2",english:"person in need of care",pos:"noun (m/f)",sentences:[{"de": "Pflegebedürftige haben Anspruch auf Leistungen der Pflegeversicherung.", "en": "Persons in need of care are entitled to benefits from the long-term care insurance."}, {"de": "Die Zahl der Pflegebedürftigen wird aufgrund der alternden Bevölkerung weiter steigen.", "en": "The number of people in need of care will continue to rise due to the ageing population."}]},
  {id:1460,german:"der Grad der Behinderung",level:"B2",english:"degree of disability",pos:"noun phrase (m)",sentences:[{"de": "Ab einem Grad der Behinderung von 50 gilt man als schwerbehindert.", "en": "A degree of disability of 50 or more is classified as severely disabled."}, {"de": "Der Grad der Behinderung wird vom Versorgungsamt festgestellt.", "en": "The degree of disability is determined by the welfare office."}]},
  {id:1461,german:"der Schwerbehindertenausweis",level:"B2",english:"severe disability ID card",pos:"noun (m)",sentences:[{"de": "Mit dem Schwerbehindertenausweis hat man Anspruch auf besondere Vergünstigungen.", "en": "With the severe disability ID card, one is entitled to special benefits."}, {"de": "Er beantragte einen Schwerbehindertenausweis beim zuständigen Amt.", "en": "He applied for a severe disability ID card at the responsible office."}]},
  {id:1462,german:"die Barrierefreiheit",level:"B2",english:"accessibility, barrier-free access",pos:"noun (f)",sentences:[{"de": "Barrierefreiheit in öffentlichen Gebäuden ist gesetzlich vorgeschrieben.", "en": "Accessibility in public buildings is required by law."}, {"de": "Das neue Museum wurde von Anfang an auf Barrierefreiheit ausgelegt.", "en": "The new museum was designed with accessibility in mind from the outset."}]},
  {id:1463,german:"die Therapie",level:"B2",english:"therapy",pos:"noun (f)",sentences:[{"de": "Er begann eine Therapie, um seine Angstzustände zu behandeln.", "en": "He began therapy to treat his anxiety."}, {"de": "Die Therapie hat ihm geholfen, mit dem Trauma umzugehen.", "en": "Therapy helped him to deal with the trauma."}]},
  {id:1464,german:"die Physiotherapie",level:"B2",english:"physiotherapy",pos:"noun (f)",sentences:[{"de": "Nach der Operation benötigt sie mehrere Wochen Physiotherapie.", "en": "After the operation, she needs several weeks of physiotherapy."}, {"de": "Physiotherapie kann bei Rückenbeschwerden sehr wirksam sein.", "en": "Physiotherapy can be very effective for back problems."}]},
  {id:1465,german:"die Ergotherapie",level:"B2",english:"occupational therapy",pos:"noun (f)",sentences:[{"de": "Ergotherapie hilft Patienten, ihre alltäglichen Fähigkeiten zurückzugewinnen.", "en": "Occupational therapy helps patients to regain their everyday abilities."}, {"de": "Das Kind erhält Ergotherapie, um seine Feinmotorik zu verbessern.", "en": "The child receives occupational therapy to improve its fine motor skills."}]},
  {id:1466,german:"die Psychotherapie",level:"B2",english:"psychotherapy",pos:"noun (f)",sentences:[{"de": "Psychotherapie ist eine wirksame Behandlung für Depressionen.", "en": "Psychotherapy is an effective treatment for depression."}, {"de": "Sie entschloss sich, eine Psychotherapie zu beginnen, um ihre Probleme aufzuarbeiten.", "en": "She decided to start psychotherapy to work through her problems."}]},
  {id:1467,german:"die Beratungsstelle",level:"B2",english:"advice centre, counselling centre",pos:"noun (f)",sentences:[{"de": "Die Beratungsstelle bietet kostenlose Hilfe für Menschen in schwierigen Lebenssituationen.", "en": "The counselling centre offers free help to people in difficult life situations."}, {"de": "Er wandte sich an eine Beratungsstelle für Suchtprobleme.", "en": "He turned to an advice centre for addiction problems."}]},
  {id:1468,german:"die Sozialberatung",level:"B2",english:"social counselling",pos:"noun (f)",sentences:[{"de": "Die Sozialberatung half ihr, die ihr zustehenden Leistungen zu beantragen.", "en": "Social counselling helped her to apply for the benefits she was entitled to."}, {"de": "Viele Organisationen bieten kostenlose Sozialberatung an.", "en": "Many organisations offer free social counselling."}]},
  {id:1469,german:"die Schuldnerberatung",level:"B2",english:"debt counselling",pos:"noun (f)",sentences:[{"de": "Die Schuldnerberatung half ihm, einen Plan zur Schuldenbefreiung zu erstellen.", "en": "Debt counselling helped him to draw up a plan for becoming debt-free."}, {"de": "Wer in die Schuldenfalle geraten ist, sollte eine Schuldnerberatung aufsuchen.", "en": "Anyone who has fallen into the debt trap should seek debt counselling."}]},
  {id:1470,german:"die Verbraucherberatung",level:"B2",english:"consumer advice",pos:"noun (f)",sentences:[{"de": "Die Verbraucherzentrale bietet kostenlose Verbraucherberatung an.", "en": "The consumer advice centre offers free consumer advice."}, {"de": "Er kontaktierte die Verbraucherberatung wegen eines fehlerhaften Produkts.", "en": "He contacted the consumer advice service regarding a defective product."}]},
  {id:1471,german:"der Verbraucherschutz",level:"B2",english:"consumer protection",pos:"noun (m)",sentences:[{"de": "Strenge Verbraucherschutzgesetze schützen Käufer vor unlauteren Geschäftspraktiken.", "en": "Strict consumer protection laws protect buyers from unfair business practices."}, {"de": "Der Verbraucherschutz wurde in den letzten Jahren deutlich gestärkt.", "en": "Consumer protection has been significantly strengthened in recent years."}]},
  {id:1472,german:"die Verbraucherrechte",level:"B2",english:"consumer rights",pos:"noun (pl)",sentences:[{"de": "Verbraucherrechte umfassen unter anderem das Recht auf Gewährleistung.", "en": "Consumer rights include, among other things, the right to warranty."}, {"de": "In der EU genießen Verbraucher umfangreiche Verbraucherrechte.", "en": "In the EU, consumers enjoy extensive consumer rights."}]},
  {id:1473,german:"die Wohnsituation",level:"B2",english:"housing situation",pos:"noun (f)",sentences:[{"de": "Die Wohnsituation in Großstädten hat sich in den letzten Jahren verschlechtert.", "en": "The housing situation in major cities has deteriorated in recent years."}, {"de": "Viele Studierende klagen über ihre schwierige Wohnsituation.", "en": "Many students complain about their difficult housing situation."}]},
  {id:1474,german:"die Mietkosten",level:"B2",english:"rent costs",pos:"noun (pl)",sentences:[{"de": "Die Mietkosten in München gehören zu den höchsten in Deutschland.", "en": "Rent costs in Munich are among the highest in Germany."}, {"de": "Steigende Mietkosten belasten viele Haushalte finanziell stark.", "en": "Rising rent costs place a heavy financial burden on many households."}]},
  {id:1475,german:"die Nebenkosten",level:"B2",english:"additional costs, utility costs",pos:"noun (pl)",sentences:[{"de": "Neben der Kaltmiete kommen noch Nebenkosten für Wasser und Heizung hinzu.", "en": "In addition to the net rent, there are additional costs for water and heating."}, {"de": "Die Nebenkosten werden jährlich abgerechnet.", "en": "The utility costs are billed annually."}]},
  {id:1476,german:"die Betriebskosten",level:"B2",english:"operating costs, service charges",pos:"noun (pl)",sentences:[{"de": "Die Betriebskosten für das Gebäude sind in den letzten Jahren gestiegen.", "en": "The operating costs for the building have increased in recent years."}, {"de": "Zur Warmmiete kommen die Betriebskosten für Müllabfuhr und Hausmeister hinzu.", "en": "Service charges for waste collection and the caretaker are added to the gross rent."}]},
  {id:1477,german:"die Heizkostenabrechnung",level:"B2",english:"heating cost statement",pos:"noun (f)",sentences:[{"de": "Die jährliche Heizkostenabrechnung zeigte, dass sie zu viel vorausgezahlt hatten.", "en": "The annual heating cost statement showed that they had overpaid."}, {"de": "Eine detaillierte Heizkostenabrechnung ist für Mieter gesetzlich vorgeschrieben.", "en": "A detailed heating cost statement is required by law for tenants."}]},
  {id:1478,german:"die Nebenkostenabrechnung",level:"B2",english:"utility bill, service charge statement",pos:"noun (f)",sentences:[{"de": "Die Nebenkostenabrechnung muss dem Mieter spätestens zwölf Monate nach Jahresende zugestellt werden.", "en": "The service charge statement must be delivered to the tenant no later than twelve months after the end of the year."}, {"de": "Nach der Nebenkostenabrechnung erhielt sie eine Nachzahlung von 200 Euro.", "en": "After the utility bill, she received an additional payment of 200 euros."}]},
  {id:1479,german:"der Mietspiegel",level:"B2",english:"rent index",pos:"noun (m)",sentences:[{"de": "Der Mietspiegel gibt Auskunft über die ortsübliche Vergleichsmiete.", "en": "The rent index provides information on the locally customary comparative rent."}, {"de": "Vermieter dürfen die Miete nur bis zur Grenze des Mietspiegels erhöhen.", "en": "Landlords may only increase the rent up to the limit set by the rent index."}]},
  {id:1480,german:"die Mieterhöhung",level:"B2",english:"rent increase",pos:"noun (f)",sentences:[{"de": "Der Vermieter kündigte eine Mieterhöhung von 10 Prozent an.", "en": "The landlord announced a rent increase of 10 percent."}, {"de": "Eine Mieterhöhung muss schriftlich und mit ausreichend Vorlauf angekündigt werden.", "en": "A rent increase must be announced in writing and with sufficient notice."}]},
  {id:1481,german:"die Eigenbedarfskündigung",level:"B2",english:"eviction for personal use",pos:"noun (f)",sentences:[{"de": "Der Vermieter sprach eine Eigenbedarfskündigung aus, weil sein Sohn in die Wohnung einziehen wollte.", "en": "The landlord issued an eviction for personal use because his son wanted to move into the flat."}, {"de": "Mieter können eine Eigenbedarfskündigung anfechten, wenn sie nicht rechtmäßig ist.", "en": "Tenants can challenge an eviction for personal use if it is not lawful."}]},
  {id:1482,german:"die Zwangsversteigerung",level:"B2",english:"forced auction, compulsory sale",pos:"noun (f)",sentences:[{"de": "Das Haus wurde nach der Insolvenz des Eigentümers zur Zwangsversteigerung freigegeben.", "en": "The house was released for forced auction after the owner's insolvency."}, {"de": "Bei einer Zwangsversteigerung können Immobilien oft günstiger erworben werden.", "en": "Properties can often be acquired more cheaply at a forced auction."}]},
  {id:1483,german:"das Wohngeld",level:"B2",english:"housing benefit",pos:"noun (n)",sentences:[{"de": "Einkommensschwache Haushalte können Wohngeld beantragen.", "en": "Low-income households can apply for housing benefit."}, {"de": "Das Wohngeld soll dazu beitragen, die Wohnkosten für bedürftige Menschen zu senken.", "en": "Housing benefit is intended to help reduce housing costs for people in need."}]},
  {id:1484,german:"die Sozialhilfe",level:"B2",english:"social welfare, income support",pos:"noun (f)",sentences:[{"de": "Sozialhilfe wird an Menschen gezahlt, die sich selbst nicht finanzieren können.", "en": "Social welfare is paid to people who cannot finance themselves."}, {"de": "Sie musste Sozialhilfe beantragen, nachdem sie ihre Arbeit verloren hatte.", "en": "She had to apply for income support after losing her job."}]},
  {id:1485,german:"der Grundfreibetrag",level:"B2",english:"basic tax allowance",pos:"noun (m)",sentences:[{"de": "Der Grundfreibetrag gibt an, wie viel Einkommen steuerfrei bleibt.", "en": "The basic tax allowance indicates how much income remains tax-free."}, {"de": "Der Grundfreibetrag wird regelmäßig an die Inflation angepasst.", "en": "The basic tax allowance is regularly adjusted for inflation."}]},
  {id:1486,german:"der Steuersatz",level:"B2",english:"tax rate",pos:"noun (m)",sentences:[{"de": "Der Steuersatz steigt mit zunehmendem Einkommen progressiv an.", "en": "The tax rate increases progressively with rising income."}, {"de": "In Deutschland gibt es unterschiedliche Steuersätze für verschiedene Warengruppen.", "en": "In Germany, there are different tax rates for different product groups."}]},
  {id:1487,german:"das zu versteuernde Einkommen",level:"B2",english:"taxable income",pos:"noun phrase (n)",sentences:[{"de": "Das zu versteuernde Einkommen ergibt sich nach Abzug aller Freibeträge und Werbungskosten.", "en": "Taxable income is calculated after deducting all allowances and income-related expenses."}, {"de": "Wer das zu versteuernde Einkommen senkt, zahlt weniger Steuern.", "en": "Those who reduce their taxable income pay less tax."}]},
  {id:1488,german:"die Steuerlast",level:"B2",english:"tax burden",pos:"noun (f)",sentences:[{"de": "Viele Bürger empfinden die Steuerlast in Deutschland als zu hoch.", "en": "Many citizens consider the tax burden in Germany to be too high."}, {"de": "Durch kluge Steuergestaltung lässt sich die Steuerlast legal senken.", "en": "Through clever tax planning, the tax burden can be legally reduced."}]},
  {id:1489,german:"die Steuererleichterung",level:"B2",english:"tax relief",pos:"noun (f)",sentences:[{"de": "Die Regierung beschloss Steuererleichterungen für kleine und mittlere Unternehmen.", "en": "The government decided on tax relief for small and medium-sized enterprises."}, {"de": "Familien profitieren von verschiedenen Steuererleichterungen.", "en": "Families benefit from various forms of tax relief."}]},
  {id:1490,german:"die Steuerbefreiung",level:"B2",english:"tax exemption",pos:"noun (f)",sentences:[{"de": "Gemeinnützige Organisationen genießen in der Regel eine Steuerbefreiung.", "en": "Non-profit organisations generally enjoy tax exemption."}, {"de": "Für bestimmte Einnahmen gibt es eine gesetzliche Steuerbefreiung.", "en": "There is a statutory tax exemption for certain types of income."}]},
  {id:1491,german:"die Abgabe",level:"B2",english:"levy, charge, tax; submission",pos:"noun (f)",sentences:[{"de": "Neben Steuern gibt es noch zahlreiche andere Abgaben, die Bürger zahlen müssen.", "en": "In addition to taxes, there are numerous other levies that citizens must pay."}, {"de": "Die Abgabe der Steuererklärung muss bis Ende Juli erfolgen.", "en": "The submission of the tax return must be made by the end of July."}]},
  {id:1492,german:"der Haushalt",level:"B2",english:"household; budget; parliament",pos:"noun (m)",sentences:[{"de": "Der Bundeshaushalt wird jährlich vom Parlament verabschiedet.", "en": "The federal budget is approved by parliament annually."}, {"de": "Ein Haushalt mit zwei Personen hat in der Regel niedrigere Pro-Kopf-Kosten.", "en": "A two-person household generally has lower per capita costs."}]},
  {id:1493,german:"der Staatshaushalt",level:"B2",english:"state budget, government budget",pos:"noun (m)",sentences:[{"de": "Der Staatshaushalt muss sorgfältig geplant werden, um alle Ausgaben zu decken.", "en": "The government budget must be carefully planned to cover all expenditure."}, {"de": "Ein ausgeglichener Staatshaushalt ist das Ziel vieler Regierungen.", "en": "A balanced government budget is the goal of many governments."}]},
  {id:1494,german:"das Haushaltsdefizit",level:"B2",english:"budget deficit",pos:"noun (n)",sentences:[{"de": "Das Haushaltsdefizit muss durch Kredite oder Steuererhöhungen finanziert werden.", "en": "The budget deficit must be financed through loans or tax increases."}, {"de": "Viele europäische Länder kämpfen mit einem hohen Haushaltsdefizit.", "en": "Many European countries are struggling with a high budget deficit."}]},
  {id:1495,german:"der Haushaltsüberschuss",level:"B2",english:"budget surplus",pos:"noun (m)",sentences:[{"de": "Der Haushaltsüberschuss wurde genutzt, um Schulden zu tilgen.", "en": "The budget surplus was used to pay off debt."}, {"de": "In guten Wirtschaftsjahren gelingt es manchmal, einen Haushaltsüberschuss zu erzielen.", "en": "In good economic years, it is sometimes possible to achieve a budget surplus."}]},
  {id:1496,german:"die Staatsverschuldung",level:"B2",english:"national debt, public debt",pos:"noun (f)",sentences:[{"de": "Die Staatsverschuldung vieler Länder ist im Zuge der Pandemie stark gestiegen.", "en": "The national debt of many countries has risen sharply in the wake of the pandemic."}, {"de": "Hohe Staatsverschuldung kann zukünftige Generationen belasten.", "en": "High public debt can burden future generations."}]},
  {id:1497,german:"die Sparmaßnahme",level:"B2",english:"austerity measure, cost-cutting measure",pos:"noun (f)",sentences:[{"de": "Die Regierung beschloss drastische Sparmaßnahmen, um das Defizit zu senken.", "en": "The government decided on drastic austerity measures to reduce the deficit."}, {"de": "Die Sparmaßnahmen trafen vor allem sozial schwächere Bevölkerungsgruppen.", "en": "The austerity measures hit particularly socially weaker sections of the population."}]},
  {id:1498,german:"die Austeritätspolitik",level:"B2",english:"austerity policy",pos:"noun (f)",sentences:[{"de": "Die Austeritätspolitik der 2010er Jahre war in Europa sehr umstritten.", "en": "The austerity policy of the 2010s was very controversial in Europe."}, {"de": "Kritiker argumentieren, dass Austeritätspolitik Wirtschaftswachstum hemmt.", "en": "Critics argue that austerity policy hampers economic growth."}]},
  {id:1499,german:"der Wirtschaftsaufschwung",level:"B2",english:"economic upturn, economic boom",pos:"noun (m)",sentences:[{"de": "Nach der Krise erlebte das Land einen kräftigen Wirtschaftsaufschwung.", "en": "After the crisis, the country experienced a strong economic upturn."}, {"de": "Günstige Zinsen und hohe Nachfrage trieben den Wirtschaftsaufschwung voran.", "en": "Low interest rates and high demand drove the economic boom forward."}]},
  {id:1500,german:"die Wirtschaftskrise",level:"B2",english:"economic crisis",pos:"noun (f)",sentences:[{"de": "Die Wirtschaftskrise führte zu einem starken Anstieg der Arbeitslosigkeit.", "en": "The economic crisis led to a sharp rise in unemployment."}, {"de": "In einer Wirtschaftskrise sind staatliche Konjunkturprogramme wichtig.", "en": "Government stimulus programmes are important during an economic crisis."}]},
  {id:1501,german:"die Finanzkrise",level:"B2",english:"financial crisis",pos:"noun (f)",sentences:[{"de": "Die Finanzkrise von 2008 hatte weltweite Auswirkungen auf die Wirtschaft.", "en": "The financial crisis of 2008 had worldwide effects on the economy."}, {"de": "Nach der Finanzkrise wurden strengere Regeln für Banken eingeführt.", "en": "After the financial crisis, stricter rules for banks were introduced."}]},
  {id:1502,german:"die Bankenrettung",level:"B2",english:"bank bailout",pos:"noun (f)",sentences:[{"de": "Die Bankenrettung kostete die Steuerzahler Milliarden von Euro.", "en": "The bank bailout cost taxpayers billions of euros."}, {"de": "Die Bankenrettung war politisch umstritten, aber wirtschaftlich notwendig.", "en": "The bank bailout was politically controversial but economically necessary."}]},
  {id:1503,german:"der Rettungsschirm",level:"B2",english:"rescue package, bailout fund",pos:"noun (m)",sentences:[{"de": "Die EU spannte einen Rettungsschirm für verschuldete Mitgliedsstaaten.", "en": "The EU set up a rescue package for indebted member states."}, {"de": "Der Rettungsschirm sollte verhindern, dass das Land Bankrott geht.", "en": "The bailout fund was intended to prevent the country from going bankrupt."}]},
  {id:1504,german:"die Währungsunion",level:"B2",english:"monetary union, currency union",pos:"noun (f)",sentences:[{"de": "Die Europäische Währungsunion wurde 1999 offiziell gegründet.", "en": "The European Monetary Union was officially founded in 1999."}, {"de": "Eine Währungsunion erfordert eine enge wirtschaftliche Koordination.", "en": "A monetary union requires close economic coordination."}]},
  {id:1505,german:"der Wechselkurs",level:"B2",english:"exchange rate",pos:"noun (m)",sentences:[{"de": "Der Wechselkurs zwischen Euro und Dollar schwankt täglich.", "en": "The exchange rate between the euro and the dollar fluctuates daily."}, {"de": "Ein günstiger Wechselkurs kann den Export ankurbeln.", "en": "A favourable exchange rate can stimulate exports."}]},
  {id:1506,german:"die Kaufkraft",level:"B2",english:"purchasing power",pos:"noun (f)",sentences:[{"de": "Inflation vermindert die Kaufkraft der Bevölkerung.", "en": "Inflation reduces the purchasing power of the population."}, {"de": "Die Kaufkraft in Ostdeutschland ist noch immer niedriger als im Westen.", "en": "Purchasing power in eastern Germany is still lower than in the west."}]},
  {id:1507,german:"der Verbraucherpreisindex",level:"B2",english:"consumer price index (CPI)",pos:"noun (m)",sentences:[{"de": "Der Verbraucherpreisindex misst die durchschnittliche Preisentwicklung.", "en": "The consumer price index measures average price developments."}, {"de": "Stieg der Verbraucherpreisindex stark an, spricht man von Inflation.", "en": "If the consumer price index rises sharply, this is referred to as inflation."}]},
  {id:1508,german:"die Teuerungsrate",level:"B2",english:"inflation rate, rate of price increase",pos:"noun (f)",sentences:[{"de": "Die Teuerungsrate erreichte im letzten Jahr einen historischen Höchstwert.", "en": "The inflation rate reached a historic high last year."}, {"de": "Eine hohe Teuerungsrate belastet besonders einkommensschwache Haushalte.", "en": "A high rate of price increase places a particular burden on low-income households."}]},
  {id:1509,german:"die Lohnsteigerung",level:"B2",english:"wage increase",pos:"noun (f)",sentences:[{"de": "Die Gewerkschaft forderte eine Lohnsteigerung von 4 Prozent.", "en": "The trade union demanded a wage increase of 4 percent."}, {"de": "Lohnsteigerungen über der Inflationsrate bedeuten eine reale Einkommensverbesserung.", "en": "Wage increases above the inflation rate mean a real improvement in income."}]},
  {id:1510,german:"die Tarifrunde",level:"B2",english:"pay round, collective bargaining round",pos:"noun (f)",sentences:[{"de": "In der aktuellen Tarifrunde verhandeln Gewerkschaft und Arbeitgeber über neue Löhne.", "en": "In the current pay round, the union and employers are negotiating new wages."}, {"de": "Die Tarifrunde im öffentlichen Dienst zog sich über mehrere Monate hin.", "en": "The collective bargaining round in the public sector dragged on for several months."}]},
  {id:1511,german:"der Streik",level:"B2",english:"strike",pos:"noun (m)",sentences:[{"de": "Die Lokführer traten in einen Streik, um höhere Gehälter zu fordern.", "en": "Train drivers went on strike to demand higher wages."}, {"de": "Der Streik legte den gesamten Bahnverkehr für zwei Tage lahm.", "en": "The strike brought the entire rail network to a standstill for two days."}]},
  {id:1512,german:"das Streikrecht",level:"B2",english:"right to strike",pos:"noun (n)",sentences:[{"de": "Das Streikrecht ist in Deutschland verfassungsrechtlich geschützt.", "en": "The right to strike is protected under constitutional law in Germany."}, {"de": "Beamte haben in Deutschland kein Streikrecht.", "en": "Civil servants in Germany do not have the right to strike."}]},
  {id:1513,german:"der Arbeitgeberverband",level:"B2",english:"employers' association",pos:"noun (m)",sentences:[{"de": "Der Arbeitgeberverband verhandelt im Namen der Unternehmen mit den Gewerkschaften.", "en": "The employers' association negotiates with trade unions on behalf of companies."}, {"de": "Viele mittelständische Betriebe sind Mitglied in einem Arbeitgeberverband.", "en": "Many medium-sized companies are members of an employers' association."}]},
  {id:1514,german:"die Tarifautonomie",level:"B2",english:"collective bargaining autonomy",pos:"noun (f)",sentences:[{"de": "Die Tarifautonomie garantiert, dass Gewerkschaften und Arbeitgeber frei verhandeln können.", "en": "Collective bargaining autonomy guarantees that trade unions and employers can negotiate freely."}, {"de": "Die Tarifautonomie ist ein wichtiges Merkmal der deutschen Arbeitsbeziehungen.", "en": "Collective bargaining autonomy is an important feature of German labour relations."}]},
  {id:1515,german:"die Schlichtung",level:"B2",english:"arbitration, mediation, conciliation",pos:"noun (f)",sentences:[{"de": "Nach dem Scheitern der Verhandlungen wurde ein Schlichtungsverfahren eingeleitet.", "en": "After the negotiations broke down, an arbitration procedure was initiated."}, {"de": "Durch die Schlichtung konnte ein langer Arbeitskampf vermieden werden.", "en": "Through mediation, a lengthy industrial dispute was avoided."}]},
  {id:1516,german:"der/die Schlichter/-in",level:"B2",english:"arbitrator, mediator, conciliator",pos:"noun (m/f)",sentences:[{"de": "Der Schlichter erarbeitete einen Kompromissvorschlag, dem beide Seiten zustimmen konnten.", "en": "The mediator drew up a compromise proposal that both sides could agree to."}, {"de": "Als neutrale Schlichterin versuchte sie, den Konflikt zu lösen.", "en": "As a neutral conciliator, she tried to resolve the conflict."}]},
  {id:1517,german:"die Betriebsvereinbarung",level:"B2",english:"works agreement, company agreement",pos:"noun (f)",sentences:[{"de": "Die Betriebsvereinbarung regelt flexible Arbeitszeiten im Unternehmen.", "en": "The works agreement regulates flexible working hours in the company."}, {"de": "Eine Betriebsvereinbarung muss zwischen Arbeitgeber und Betriebsrat ausgehandelt werden.", "en": "A works agreement must be negotiated between the employer and the works council."}]},
  {id:1518,german:"der Betriebsrat",level:"B2",english:"works council",pos:"noun (m)",sentences:[{"de": "Der Betriebsrat vertritt die Interessen der Arbeitnehmer gegenüber dem Arbeitgeber.", "en": "The works council represents the interests of employees vis-à-vis the employer."}, {"de": "Bei größeren Personalentscheidungen muss der Betriebsrat konsultiert werden.", "en": "The works council must be consulted on major personnel decisions."}]},
  {id:1519,german:"die Mitbestimmung",level:"B2",english:"co-determination, worker participation",pos:"noun (f)",sentences:[{"de": "Mitbestimmung gibt Arbeitnehmern das Recht, an wichtigen Entscheidungen beteiligt zu werden.", "en": "Co-determination gives employees the right to participate in important decisions."}, {"de": "Das deutsche Modell der Mitbestimmung gilt international als vorbildlich.", "en": "The German model of co-determination is internationally regarded as exemplary."}]},
  {id:1520,german:"das Betriebsverfassungsgesetz",level:"B2",english:"Works Constitution Act",pos:"noun (n)",sentences:[{"de": "Das Betriebsverfassungsgesetz regelt die Rechte und Pflichten des Betriebsrats.", "en": "The Works Constitution Act regulates the rights and duties of the works council."}, {"de": "Das Betriebsverfassungsgesetz ist eine wichtige Grundlage für die Mitbestimmung in Deutschland.", "en": "The Works Constitution Act is an important basis for co-determination in Germany."}]},
  {id:1521,german:"der Arbeitsschutz",level:"B2",english:"occupational health and safety",pos:"noun (m)",sentences:[{"de": "Arbeitgeber sind gesetzlich verpflichtet, den Arbeitsschutz zu gewährleisten.", "en": "Employers are legally obliged to ensure occupational health and safety."}, {"de": "Regelmäßige Schulungen sind ein wichtiger Bestandteil des Arbeitsschutzes.", "en": "Regular training courses are an important component of occupational health and safety."}]},
  {id:1522,german:"die Arbeitssicherheit",level:"B2",english:"workplace safety, occupational safety",pos:"noun (f)",sentences:[{"de": "Arbeitssicherheit hat in Industrie- und Bauunternehmen oberste Priorität.", "en": "Workplace safety has top priority in industrial and construction companies."}, {"de": "Die Arbeitssicherheit wurde durch neue Schutzmaßnahmen erheblich verbessert.", "en": "Occupational safety was considerably improved through new protective measures."}]},
  {id:1523,german:"die Gefährdungsbeurteilung",level:"B2",english:"risk assessment",pos:"noun (f)",sentences:[{"de": "Jeder Arbeitgeber ist verpflichtet, eine Gefährdungsbeurteilung für alle Arbeitsplätze durchzuführen.", "en": "Every employer is obliged to carry out a risk assessment for all workplaces."}, {"de": "Die Gefährdungsbeurteilung hilft dabei, potenzielle Risiken frühzeitig zu erkennen.", "en": "The risk assessment helps to identify potential risks at an early stage."}]},
  {id:1524,german:"die Schutzausrüstung",level:"B2",english:"protective equipment, PPE",pos:"noun (f)",sentences:[{"de": "Auf der Baustelle ist das Tragen von Schutzausrüstung Pflicht.", "en": "Wearing protective equipment is mandatory on the construction site."}, {"de": "Die persönliche Schutzausrüstung muss regelmäßig auf ihren Zustand geprüft werden.", "en": "Personal protective equipment must be regularly checked for its condition."}]},
  {id:1525,german:"der Arbeitsunfall",level:"B2",english:"workplace accident, industrial accident",pos:"noun (m)",sentences:[{"de": "Nach dem Arbeitsunfall wurde er in das nächste Krankenhaus eingeliefert.", "en": "After the workplace accident, he was admitted to the nearest hospital."}, {"de": "Arbeitsunfälle müssen dem Arbeitgeber und der Berufsgenossenschaft gemeldet werden.", "en": "Workplace accidents must be reported to the employer and the employers' liability insurance association."}]},
  {id:1526,german:"die Berufskrankheit",level:"B2",english:"occupational disease, work-related illness",pos:"noun (f)",sentences:[{"de": "Lärmbedingter Hörverlust ist eine häufige Berufskrankheit in der Industrie.", "en": "Noise-induced hearing loss is a common occupational disease in industry."}, {"de": "Bei einer anerkannten Berufskrankheit übernimmt die Berufsgenossenschaft die Kosten.", "en": "In the case of a recognised occupational disease, the employers' liability insurance association covers the costs."}]},
  {id:1527,german:"die Unfallversicherung",level:"B2",english:"accident insurance",pos:"noun (f)",sentences:[{"de": "Die gesetzliche Unfallversicherung schützt Arbeitnehmer bei Arbeitsunfällen.", "en": "Statutory accident insurance protects employees in the event of workplace accidents."}, {"de": "Neben der gesetzlichen gibt es auch private Unfallversicherungen.", "en": "In addition to statutory accident insurance, there are also private accident insurance policies."}]},
  {id:1528,german:"die Suchtprävention",level:"B2",english:"addiction prevention",pos:"noun (f)",sentences:[{"de": "Viele Unternehmen bieten Programme zur Suchtprävention für ihre Mitarbeiter an.", "en": "Many companies offer addiction prevention programmes for their employees."}, {"de": "Suchtprävention beginnt am besten schon in der Schule.", "en": "Addiction prevention is best started in schools."}]},
  {id:1529,german:"die Gesundheitsförderung",level:"B2",english:"health promotion",pos:"noun (f)",sentences:[{"de": "Betriebliche Gesundheitsförderung senkt Krankheitstage und steigert die Produktivität.", "en": "Workplace health promotion reduces sick days and increases productivity."}, {"de": "Gesundheitsförderung umfasst Maßnahmen wie Sport, Ernährungsberatung und Stressbewältigung.", "en": "Health promotion includes measures such as sport, nutritional advice and stress management."}]},
  {id:1530,german:"das betriebliche Gesundheitsmanagement",level:"B2",english:"occupational health management",pos:"noun phrase (n)",sentences:[{"de": "Betriebliches Gesundheitsmanagement umfasst alle Maßnahmen zur Förderung der Mitarbeitergesundheit.", "en": "Occupational health management encompasses all measures to promote employee health."}, {"de": "Ein gutes betriebliches Gesundheitsmanagement reduziert Fehlzeiten und erhöht die Mitarbeiterzufriedenheit.", "en": "Good occupational health management reduces absenteeism and increases employee satisfaction."}]},
  {id:1531,german:"die Work-Life-Balance",level:"B2",english:"work-life balance",pos:"noun (f)",sentences:[{"de": "Eine gute Work-Life-Balance ist für viele Arbeitnehmer wichtiger als ein hohes Gehalt.", "en": "A good work-life balance is more important to many employees than a high salary."}, {"de": "Flexible Arbeitszeiten und Homeoffice tragen zur Verbesserung der Work-Life-Balance bei.", "en": "Flexible working hours and working from home contribute to improving work-life balance."}]},
  {id:1532,german:"das Burnout",level:"B2",english:"burnout",pos:"noun (n)",sentences:[{"de": "Burnout ist eine ernste Erkrankung, die professionelle Behandlung erfordert.", "en": "Burnout is a serious condition that requires professional treatment."}, {"de": "Chronischer Stress und mangelnde Erholung können zu einem Burnout führen.", "en": "Chronic stress and insufficient recovery can lead to burnout."}]},
  {id:1533,german:"der Stress",level:"B2",english:"stress",pos:"noun (m)",sentences:[{"de": "Der Stress im Büro hat in den letzten Jahren deutlich zugenommen.", "en": "Stress at the office has increased significantly in recent years."}, {"de": "Regelmäßige Pausen und Sport helfen dabei, den Stress abzubauen.", "en": "Regular breaks and exercise help to reduce stress."}]},
  {id:1534,german:"die Entspannung",level:"B2",english:"relaxation",pos:"noun (f)",sentences:[{"de": "Nach einem langen Arbeitstag sucht sie die Entspannung beim Yoga.", "en": "After a long working day, she seeks relaxation through yoga."}, {"de": "Die Entspannung des Körpers ist genauso wichtig wie die des Geistes.", "en": "The relaxation of the body is just as important as that of the mind."}]},
  {id:1535,german:"die Erholung",level:"B2",english:"recovery, recuperation, rest",pos:"noun (f)",sentences:[{"de": "Für eine vollständige Erholung braucht der Körper ausreichend Schlaf.", "en": "For a full recovery, the body needs sufficient sleep."}, {"de": "Der Urlaub diente der Erholung nach einem anstrengenden Semester.", "en": "The holiday served as recuperation after an exhausting semester."}]},
  {id:1536,german:"der Ausgleich",level:"B2",english:"balance, compensation, equalisation",pos:"noun (m)",sentences:[{"de": "Sport ist für ihn ein wichtiger Ausgleich zum stressigen Alltag.", "en": "Sport is an important balance for him against his stressful daily routine."}, {"de": "Die Stadt strebt einen sozialen Ausgleich zwischen den verschiedenen Stadtteilen an.", "en": "The city is striving for a social equalisation between the different districts."}]},
  {id:1537,german:"die Freizeitgestaltung",level:"B2",english:"leisure activities, use of free time",pos:"noun (f)",sentences:[{"de": "Die Freizeitgestaltung der Jugendlichen hat sich durch digitale Medien stark verändert.", "en": "Young people's leisure activities have changed greatly due to digital media."}, {"de": "Eine sinnvolle Freizeitgestaltung ist wichtig für das psychische Wohlbefinden.", "en": "Meaningful use of free time is important for psychological well-being."}]},
  {id:1538,german:"die Vereinbarkeit von Familie und Beruf",level:"B2",english:"work-life balance, reconciliation of family and work",pos:"noun phrase (f)",sentences:[{"de": "Die Vereinbarkeit von Familie und Beruf bleibt in Deutschland eine große Herausforderung.", "en": "The reconciliation of family and work remains a major challenge in Germany."}, {"de": "Flexible Arbeitszeiten verbessern die Vereinbarkeit von Familie und Beruf erheblich.", "en": "Flexible working hours significantly improve the work-life balance."}]},
  {id:1539,german:"die Kinderbetreuung",level:"B2",english:"childcare",pos:"noun (f)",sentences:[{"de": "Der Mangel an Kinderbetreuungsplätzen hindert viele Eltern daran, Vollzeit zu arbeiten.", "en": "The shortage of childcare places prevents many parents from working full-time."}, {"de": "Die Kosten für die Kinderbetreuung belasten viele Familien finanziell stark.", "en": "The cost of childcare puts a heavy financial burden on many families."}]},
  {id:1540,german:"der Kindergarten",level:"B2",english:"kindergarten, nursery school",pos:"noun (m)",sentences:[{"de": "Ab drei Jahren haben Kinder in Deutschland einen Anspruch auf einen Kindergartenplatz.", "en": "From the age of three, children in Germany have a right to a kindergarten place."}, {"de": "Im Kindergarten lernen die Kinder spielerisch den Umgang mit anderen.", "en": "In kindergarten, children learn to interact with others through play."}]},
  {id:1541,german:"die Krippe",level:"B2",english:"crèche, nursery",pos:"noun (f)",sentences:[{"de": "Immer mehr Eltern bringen ihre Kleinkinder bereits in eine Krippe.", "en": "More and more parents are already taking their toddlers to a crèche."}, {"de": "Die Krippe bietet Kindern unter drei Jahren Betreuung und Förderung.", "en": "The nursery offers care and support to children under three years of age."}]},
  {id:1542,german:"der Hort",level:"B2",english:"after-school care, extended day care",pos:"noun (m)",sentences:[{"de": "Nach der Schule geht ihr Sohn in den Hort, bis sie von der Arbeit zurückkommt.", "en": "After school, her son goes to after-school care until she returns from work."}, {"de": "Der Hort bietet den Kindern Mittagessen und Hilfe bei den Hausaufgaben.", "en": "The after-school care centre provides children with lunch and help with homework."}]},
  {id:1543,german:"die Ganztagsbetreuung",level:"B2",english:"all-day care, full-time childcare",pos:"noun (f)",sentences:[{"de": "Die Einführung der Ganztagsbetreuung an Schulen ist politisch umstritten.", "en": "The introduction of all-day care in schools is politically controversial."}, {"de": "Dank der Ganztagsbetreuung können beide Elternteile Vollzeit arbeiten.", "en": "Thanks to full-time childcare, both parents can work full-time."}]},
  {id:1544,german:"die Tagespflege",level:"B2",english:"day fostering, childminding",pos:"noun (f)",sentences:[{"de": "Tagespflege ist eine Alternative zum Kindergarten für Kinder unter drei Jahren.", "en": "Childminding is an alternative to nursery school for children under three."}, {"de": "Die Tagespflegeperson betreut täglich bis zu fünf Kinder in ihrem eigenen Zuhause.", "en": "The childminder looks after up to five children a day in her own home."}]},
  {id:1545,german:"das Au-pair",level:"B2",english:"au pair",pos:"noun (n)",sentences:[{"de": "Die Familie hat ein Au-pair aus Frankreich aufgenommen, das ihnen im Haushalt hilft.", "en": "The family has taken in an au pair from France who helps them in the household."}, {"de": "Als Au-pair erhält man Unterkunft und Verpflegung sowie ein kleines Taschengeld.", "en": "As an au pair, you receive board and lodging as well as a small allowance."}]},
  {id:1546,german:"die Haushaltshilfe",level:"B2",english:"domestic help, household assistant",pos:"noun (f)",sentences:[{"de": "Nach ihrer Operation war sie auf eine Haushaltshilfe angewiesen.", "en": "After her operation, she was dependent on domestic help."}, {"de": "Eine Haushaltshilfe kann berufstätigen Eltern viel Zeit und Energie sparen.", "en": "A household assistant can save working parents a lot of time and energy."}]},
  {id:1547,german:"die Betreuungsperson",level:"B2",english:"carer, caregiver, minder",pos:"noun (f)",sentences:[{"de": "Für Kleinkinder ist eine feste Betreuungsperson besonders wichtig.", "en": "A consistent caregiver is especially important for young children."}, {"de": "Die Betreuungsperson sollte über entsprechende pädagogische Kenntnisse verfügen.", "en": "The carer should have appropriate pedagogical knowledge."}]},
  {id:1548,german:"das soziale Netzwerk",level:"B2",english:"social network",pos:"noun (n)",sentences:[{"de": "Ein stabiles soziales Netzwerk kann in schwierigen Zeiten eine große Stütze sein.", "en": "A stable social network can be a great support in difficult times."}, {"de": "Ältere Menschen verlieren oft ihr soziales Netzwerk nach dem Renteneintritt.", "en": "Older people often lose their social network after retirement."}]},
  {id:1549,german:"die Nachbarschaft",level:"B2",english:"neighbourhood",pos:"noun (f)",sentences:[{"de": "In ihrer Nachbarschaft kennen sich fast alle Bewohner persönlich.", "en": "In her neighbourhood, almost all residents know each other personally."}, {"de": "Ein gutes Verhältnis zur Nachbarschaft trägt zum Wohlbefinden bei.", "en": "A good relationship with the neighbourhood contributes to well-being."}]},
  {id:1550,german:"die Gemeinschaft",level:"B2",english:"community",pos:"noun (f)",sentences:[{"de": "In einer Gemeinschaft übernimmt jedes Mitglied Verantwortung für das Ganze.", "en": "In a community, every member takes responsibility for the whole."}, {"de": "Die Gemeinschaft des Dorfes unterstützte die betroffene Familie nach dem Brand.", "en": "The village community supported the affected family after the fire."}]},
  {id:1551,german:"die Solidarität",level:"B2",english:"solidarity",pos:"noun (f)",sentences:[{"de": "In der Krise bewies die Bevölkerung große Solidarität mit den Betroffenen.", "en": "During the crisis, the population showed great solidarity with those affected."}, {"de": "Solidarität bedeutet, füreinander einzustehen, auch wenn es einem selbst schwer fällt.", "en": "Solidarity means standing up for each other, even when it is difficult for oneself."}]},
  {id:1552,german:"das Ehrenamt",level:"B2",english:"voluntary work, honorary post",pos:"noun (n)",sentences:[{"de": "Sie engagiert sich seit Jahren im Ehrenamt bei der Feuerwehr.", "en": "She has been doing voluntary work with the fire brigade for years."}, {"de": "Das Ehrenamt ist ein wichtiger Pfeiler der Zivilgesellschaft.", "en": "Voluntary work is an important pillar of civil society."}]},
  {id:1553,german:"die Freiwilligenarbeit",level:"B2",english:"voluntary work, volunteering",pos:"noun (f)",sentences:[{"de": "Freiwilligenarbeit bietet die Möglichkeit, soziale Verantwortung zu übernehmen.", "en": "Volunteering offers the opportunity to take on social responsibility."}, {"de": "Viele Organisationen sind auf Freiwilligenarbeit angewiesen.", "en": "Many organisations depend on voluntary work."}]},
  {id:1554,german:"der/die Freiwillige",level:"B2",english:"volunteer",pos:"noun (m/f)",sentences:[{"de": "Hunderte Freiwillige halfen beim Aufbau der Flutschutzwände.", "en": "Hundreds of volunteers helped to build the flood barriers."}, {"de": "Der Verein sucht dringend Freiwillige für seine sozialen Projekte.", "en": "The association urgently needs volunteers for its social projects."}]},
  {id:1555,german:"die Spendenbereitschaft",level:"B2",english:"willingness to donate",pos:"noun (f)",sentences:[{"de": "Nach dem Erdbeben war die Spendenbereitschaft in der Bevölkerung besonders hoch.", "en": "After the earthquake, the willingness to donate among the population was particularly high."}, {"de": "Eine glaubwürdige Organisation kann die Spendenbereitschaft der Menschen stärken.", "en": "A credible organisation can strengthen people's willingness to donate."}]},
  {id:1556,german:"die Wohlfahrtsorganisation",level:"B2",english:"welfare organisation",pos:"noun (f)",sentences:[{"de": "Wohlfahrtsorganisationen leisten unverzichtbare Arbeit für bedürftige Menschen.", "en": "Welfare organisations do indispensable work for people in need."}, {"de": "Die Wohlfahrtsorganisation betreibt mehrere Suppenküchen in der Stadt.", "en": "The welfare organisation runs several soup kitchens in the city."}]},
  {id:1557,german:"das Rote Kreuz",level:"B2",english:"Red Cross",pos:"noun (n)",sentences:[{"de": "Das Rote Kreuz leistet weltweit humanitäre Hilfe in Krisengebieten.", "en": "The Red Cross provides humanitarian aid in crisis zones worldwide."}, {"de": "Nach dem Unfall wurde er vom Roten Kreuz medizinisch versorgt.", "en": "After the accident, he received medical treatment from the Red Cross."}]},
  {id:1558,german:"der/die Sozialarbeiter/-in",level:"B2",english:"social worker",pos:"noun (m/f)",sentences:[{"de": "Die Sozialarbeiterin betreut Familien in schwierigen Lebenssituationen.", "en": "The social worker supports families in difficult life situations."}, {"de": "Sozialarbeiter spielen eine wichtige Rolle bei der Unterstützung von obdachlosen Menschen.", "en": "Social workers play an important role in supporting homeless people."}]},
  {id:1559,german:"der/die Sozialpädagoge/-in",level:"B2",english:"social pedagogue, social educator",pos:"noun (m/f)",sentences:[{"de": "Der Sozialpädagoge arbeitet eng mit Jugendlichen aus schwierigen Verhältnissen zusammen.", "en": "The social educator works closely with young people from difficult backgrounds."}, {"de": "Sozialpädagogen sind in Schulen, Jugendeinrichtungen und Beratungsstellen tätig.", "en": "Social pedagogues work in schools, youth facilities and counselling centres."}]},
  {id:1560,german:"die Jugendhilfe",level:"B2",english:"youth welfare, youth services",pos:"noun (f)",sentences:[{"de": "Das Jugendamt ist für die Umsetzung der Jugendhilfe in Deutschland verantwortlich.", "en": "The youth welfare office is responsible for implementing youth services in Germany."}, {"de": "Die Jugendhilfe unterstützt Kinder und Jugendliche, deren Wohl gefährdet ist.", "en": "Youth welfare supports children and young people whose well-being is at risk."}]},
  {id:1561,german:"die Erziehungsberatung",level:"B2",english:"parenting counselling, educational advice",pos:"noun (f)",sentences:[{"de": "Bei Problemen mit ihrem Kind haben die Eltern die Erziehungsberatung aufgesucht.", "en": "When they had problems with their child, the parents sought parenting counselling."}, {"de": "Die Erziehungsberatung bietet kostenlose Unterstützung für Familien an.", "en": "Parenting counselling offers free support for families."}]},
  {id:1562,german:"die Familienberatung",level:"B2",english:"family counselling",pos:"noun (f)",sentences:[{"de": "Die Familienberatung hilft Familien, Konflikte konstruktiv zu lösen.", "en": "Family counselling helps families to resolve conflicts constructively."}, {"de": "Nach der Scheidung nahmen beide Elternteile die Familienberatung in Anspruch.", "en": "After the divorce, both parents made use of family counselling."}]},
  {id:1563,german:"die Krisenintervention",level:"B2",english:"crisis intervention",pos:"noun (f)",sentences:[{"de": "Speziell ausgebildete Fachkräfte leisten Krisenintervention in Notfallsituationen.", "en": "Specially trained specialists provide crisis intervention in emergency situations."}, {"de": "Die rechtzeitige Krisenintervention kann schlimmere Folgen verhindern.", "en": "Timely crisis intervention can prevent more serious consequences."}]},
  {id:1564,german:"die Notaufnahme",level:"B2",english:"emergency admission; emergency accommodation",pos:"noun (f)",sentences:[{"de": "Er wurde nach dem Unfall sofort in die Notaufnahme des Krankenhauses gebracht.", "en": "After the accident, he was immediately taken to the hospital's emergency admission."}, {"de": "Die Notaufnahme für obdachlose Menschen ist an kalten Winternächten überfüllt.", "en": "The emergency accommodation for homeless people is overcrowded on cold winter nights."}]},
  {id:1565,german:"die Unterkunft",level:"B2",english:"accommodation, lodging",pos:"noun (f)",sentences:[{"de": "Die Gemeinde stellte den Geflüchteten vorübergehend eine Unterkunft zur Verfügung.", "en": "The municipality provided the refugees with temporary accommodation."}, {"de": "Er sucht eine günstige Unterkunft für seine Reise nach Berlin.", "en": "He is looking for affordable lodging for his trip to Berlin."}]},
  {id:1566,german:"die Erstaufnahme",level:"B2",english:"initial reception, first admission",pos:"noun (f)",sentences:[{"de": "In der Erstaufnahmeeinrichtung werden Asylsuchende zunächst registriert.", "en": "In the initial reception facility, asylum seekers are first registered."}, {"de": "Die Kapazitäten der Erstaufnahme sind oft nicht ausreichend.", "en": "The capacity of the initial reception is often not sufficient."}]},
  {id:1567,german:"die Flüchtlingsunterkunft",level:"B2",english:"refugee accommodation",pos:"noun (f)",sentences:[{"de": "Die Flüchtlingsunterkunft am Stadtrand wurde von Ehrenamtlichen unterstützt.", "en": "The refugee accommodation on the outskirts of town was supported by volunteers."}, {"de": "In der Flüchtlingsunterkunft leben Menschen aus über zwanzig verschiedenen Ländern.", "en": "People from more than twenty different countries live in the refugee accommodation."}]},
  {id:1568,german:"die Asylbewerbung",level:"B2",english:"asylum application",pos:"noun (f)",sentences:[{"de": "Er stellte nach seiner Ankunft in Deutschland sofort eine Asylbewerbung.", "en": "He submitted an asylum application immediately after his arrival in Germany."}, {"de": "Die Bearbeitung einer Asylbewerbung kann mehrere Monate dauern.", "en": "Processing an asylum application can take several months."}]},
  {id:1569,german:"das Asylverfahren",level:"B2",english:"asylum procedure",pos:"noun (n)",sentences:[{"de": "Während des laufenden Asylverfahrens ist die Abschiebung ausgesetzt.", "en": "During ongoing asylum procedures, deportation is suspended."}, {"de": "Das Asylverfahren soll sicherstellen, dass Schutzbedürftige anerkannt werden.", "en": "The asylum procedure is designed to ensure that those in need of protection are recognised."}]},
  {id:1570,german:"die Abschiebung",level:"B2",english:"deportation, expulsion",pos:"noun (f)",sentences:[{"de": "Die geplante Abschiebung wurde vom Verwaltungsgericht kurzfristig gestoppt.", "en": "The planned deportation was stopped at short notice by the administrative court."}, {"de": "Menschenrechtsorganisationen kritisieren Abschiebungen in unsichere Länder.", "en": "Human rights organisations criticise deportations to unsafe countries."}]},
  {id:1571,german:"die Duldung",level:"B2",english:"toleration, temporary suspension of deportation",pos:"noun (f)",sentences:[{"de": "Er lebt seit Jahren mit einer Duldung in Deutschland, ohne einen sicheren Aufenthaltsstatus zu haben.", "en": "He has been living in Germany for years with a toleration status, without a secure residence status."}, {"de": "Die Duldung ist kein Aufenthaltstitel, sondern nur eine vorübergehende Maßnahme.", "en": "Toleration is not a residence permit, but only a temporary measure."}]},
  {id:1572,german:"die Aufenthaltserlaubnis",level:"B2",english:"residence permit",pos:"noun (f)",sentences:[{"de": "Sie hat nach drei Jahren endlich eine unbefristete Aufenthaltserlaubnis erhalten.", "en": "After three years, she has finally received an unlimited residence permit."}, {"de": "Für die Verlängerung der Aufenthaltserlaubnis muss man bestimmte Voraussetzungen erfüllen.", "en": "To extend the residence permit, certain requirements must be met."}]},
  {id:1573,german:"die Niederlassungserlaubnis",level:"B2",english:"settlement permit, permanent residence permit",pos:"noun (f)",sentences:[{"de": "Die Niederlassungserlaubnis gibt Ausländern das Recht auf unbefristeten Aufenthalt in Deutschland.", "en": "The settlement permit gives foreigners the right to live in Germany indefinitely."}, {"de": "Nach fünf Jahren rechtmäßigen Aufenthalts kann man eine Niederlassungserlaubnis beantragen.", "en": "After five years of lawful residence, one can apply for a settlement permit."}]},
  {id:1574,german:"die Einbürgerung",level:"B2",english:"naturalisation",pos:"noun (f)",sentences:[{"de": "Nach acht Jahren Aufenthalt stellte er einen Antrag auf Einbürgerung.", "en": "After eight years of residence, he applied for naturalisation."}, {"de": "Die Einbürgerung setzt ausreichende Deutschkenntnisse voraus.", "en": "Naturalisation requires sufficient knowledge of German."}]},
  {id:1575,german:"die Staatsangehörigkeit",level:"B2",english:"nationality, citizenship",pos:"noun (f)",sentences:[{"de": "Sie hat die deutsche Staatsangehörigkeit durch Einbürgerung erworben.", "en": "She acquired German citizenship through naturalisation."}, {"de": "Kinder in Deutschland erhalten die Staatsangehörigkeit ihrer Eltern.", "en": "Children in Germany receive their parents' nationality."}]},
  {id:1576,german:"der Pass",level:"B2",english:"passport",pos:"noun (m)",sentences:[{"de": "Ohne gültigen Pass kann man die meisten internationalen Grenzen nicht überschreiten.", "en": "Without a valid passport, one cannot cross most international borders."}, {"de": "Sein Pass war abgelaufen, daher musste er ihn vor der Reise verlängern lassen.", "en": "His passport had expired, so he had to renew it before the trip."}]},
  {id:1577,german:"die Identität",level:"B2",english:"identity",pos:"noun (f)",sentences:[{"de": "Die kulturelle Identität eines Menschen wird durch Sprache, Traditionen und Geschichte geprägt.", "en": "A person's cultural identity is shaped by language, traditions and history."}, {"de": "Jugendliche suchen in der Pubertät oft nach ihrer eigenen Identität.", "en": "Young people often search for their own identity during puberty."}]},
  {id:1578,german:"die Herkunft",level:"B2",english:"origin, background, descent",pos:"noun (f)",sentences:[{"de": "Menschen unterschiedlicher Herkunft bereichern eine Gesellschaft.", "en": "People of different origins enrich a society."}, {"de": "Unabhängig von seiner sozialen Herkunft hat jeder das Recht auf Bildung.", "en": "Regardless of their social background, everyone has the right to education."}]},
  {id:1579,german:"der Migrationshintergrund",level:"B2",english:"migration background",pos:"noun (m)",sentences:[{"de": "Etwa ein Viertel der Bevölkerung in Deutschland hat einen Migrationshintergrund.", "en": "About a quarter of the population in Germany has a migration background."}, {"de": "Kinder mit Migrationshintergrund haben in der Schule oft sprachliche Nachteile.", "en": "Children with a migration background often have linguistic disadvantages at school."}]},
  {id:1580,german:"die Zweisprachigkeit",level:"B2",english:"bilingualism",pos:"noun (f)",sentences:[{"de": "Zweisprachigkeit gilt als Vorteil im Berufsleben und stärkt die kognitiven Fähigkeiten.", "en": "Bilingualism is considered an advantage in professional life and strengthens cognitive abilities."}, {"de": "In der Schweiz ist die Zweisprachigkeit in vielen Regionen selbstverständlich.", "en": "In Switzerland, bilingualism is taken for granted in many regions."}]},
  {id:1581,german:"die Mehrsprachigkeit",level:"B2",english:"multilingualism",pos:"noun (f)",sentences:[{"de": "Die Europäische Union fördert aktiv die Mehrsprachigkeit ihrer Bürgerinnen und Bürger.", "en": "The European Union actively promotes multilingualism among its citizens."}, {"de": "Mehrsprachigkeit ist in einer globalisierten Welt ein großer Vorteil.", "en": "Multilingualism is a great advantage in a globalised world."}]},
  {id:1582,german:"die Bildungssprache",level:"B2",english:"academic language, educational language",pos:"noun (f)",sentences:[{"de": "Schüler mit Migrationshintergrund haben oft Schwierigkeiten mit der Bildungssprache.", "en": "Pupils with a migration background often have difficulties with academic language."}, {"de": "Die Bildungssprache unterscheidet sich deutlich von der gesprochenen Alltagssprache.", "en": "Academic language differs significantly from spoken everyday language."}]},
  {id:1583,german:"die Alltagssprache",level:"B2",english:"everyday language, colloquial language",pos:"noun (f)",sentences:[{"de": "In der Alltagssprache werden Grammatikregeln oft weniger streng eingehalten.", "en": "In everyday language, grammar rules are often adhered to less strictly."}, {"de": "Das Wort ist in der Alltagssprache gebräuchlich, aber in formellen Texten selten.", "en": "The word is common in colloquial language but rare in formal texts."}]},
  {id:1584,german:"die Fachsprache",level:"B2",english:"technical language, specialist language",pos:"noun (f)",sentences:[{"de": "Die Fachsprache der Medizin ist für Laien oft schwer verständlich.", "en": "The technical language of medicine is often difficult for laypeople to understand."}, {"de": "In der juristischen Fachsprache haben viele Wörter eine ganz spezifische Bedeutung.", "en": "In legal technical language, many words have a very specific meaning."}]},
  {id:1585,german:"der Dialekt",level:"B2",english:"dialect",pos:"noun (m)",sentences:[{"de": "In Bayern wird neben dem Standarddeutschen auch ein ausgeprägter Dialekt gesprochen.", "en": "In Bavaria, a distinct dialect is spoken alongside standard German."}, {"de": "Der Dialekt kann ein Hindernis bei der Kommunikation zwischen verschiedenen Regionen sein.", "en": "Dialect can be a barrier to communication between different regions."}]},
  {id:1586,german:"der Akzent",level:"B2",english:"accent",pos:"noun (m)",sentences:[{"de": "Obwohl sie perfektes Deutsch spricht, hat sie noch einen leichten Akzent.", "en": "Although she speaks perfect German, she still has a slight accent."}, {"de": "Ein Akzent verrät oft, aus welcher Region oder welchem Land jemand stammt.", "en": "An accent often reveals which region or country someone comes from."}]},
  {id:1587,german:"die Aussprache",level:"B2",english:"pronunciation",pos:"noun (f)",sentences:[{"de": "Eine korrekte Aussprache ist beim Sprachenlernen besonders wichtig.", "en": "Correct pronunciation is especially important when learning languages."}, {"de": "Die deutsche Aussprache des Buchstabens R fällt vielen Lernenden schwer.", "en": "The German pronunciation of 'r' is difficult for many learners."}]},
  {id:1588,german:"die Grammatik",level:"B2",english:"grammar",pos:"noun (f)",sentences:[{"de": "Die deutsche Grammatik mit ihren vier Fällen ist für viele Lernende eine Herausforderung.", "en": "German grammar with its four cases is a challenge for many learners."}, {"de": "Im Unterricht wurde besonders viel Zeit auf die Grammatik verwendet.", "en": "A particularly large amount of time was devoted to grammar in class."}]},
  {id:1589,german:"der Wortschatz",level:"B2",english:"vocabulary",pos:"noun (m)",sentences:[{"de": "Wer täglich liest, erweitert automatisch seinen Wortschatz.", "en": "Anyone who reads daily automatically expands their vocabulary."}, {"de": "Für das B2-Niveau wird ein aktiver Wortschatz von etwa 4000 Wörtern erwartet.", "en": "For B2 level, an active vocabulary of around 4000 words is expected."}]},
  {id:1590,german:"die Rechtschreibung",level:"B2",english:"spelling, orthography",pos:"noun (f)",sentences:[{"de": "Die Rechtschreibreform von 1996 hat das Deutsche stark verändert.", "en": "The spelling reform of 1996 changed German significantly."}, {"de": "In formellen Texten ist eine korrekte Rechtschreibung unerlässlich.", "en": "Correct spelling is essential in formal texts."}]},
  {id:1591,german:"die Interpunktion",level:"B2",english:"punctuation",pos:"noun (f)",sentences:[{"de": "Eine falsche Interpunktion kann den Sinn eines Satzes vollständig verändern.", "en": "Incorrect punctuation can completely change the meaning of a sentence."}, {"de": "Im Deutschen gelten eigene Regeln für die Interpunktion bei Nebensätzen.", "en": "In German, there are specific rules for punctuation with subordinate clauses."}]},
  {id:1592,german:"die Verständigung",level:"B2",english:"communication, understanding, agreement",pos:"noun (f)",sentences:[{"de": "Ohne gemeinsame Sprache ist die Verständigung zwischen Menschen sehr schwierig.", "en": "Without a common language, communication between people is very difficult."}, {"de": "Die Verständigung über die wichtigsten Punkte gelang nach langen Verhandlungen.", "en": "Agreement on the most important points was reached after lengthy negotiations."}]},
  {id:1593,german:"das Missverständnis",level:"B2",english:"misunderstanding",pos:"noun (n)",sentences:[{"de": "Das Missverständnis entstand, weil sie unterschiedliche Bedeutungen mit dem Begriff verbanden.", "en": "The misunderstanding arose because they associated different meanings with the term."}, {"de": "Ein offenes Gespräch kann viele Missverständnisse aus der Welt schaffen.", "en": "An open conversation can clear up many misunderstandings."}]},
  {id:1594,german:"die Klarheit",level:"B2",english:"clarity",pos:"noun (f)",sentences:[{"de": "Klarheit in der Kommunikation ist entscheidend für eine effektive Zusammenarbeit.", "en": "Clarity in communication is crucial for effective collaboration."}, {"de": "Er bat um Klarheit darüber, welche Aufgaben er übernehmen sollte.", "en": "He asked for clarity about which tasks he should take on."}]},
  {id:1595,german:"die Deutlichkeit",level:"B2",english:"clarity, distinctness",pos:"noun (f)",sentences:[{"de": "Die Deutlichkeit seiner Aussprache machte das Referat sehr gut verständlich.", "en": "The distinctness of his pronunciation made the presentation very easy to understand."}, {"de": "Mit aller Deutlichkeit wies sie auf die Risiken des Projekts hin.", "en": "She pointed out the risks of the project with all clarity."}]},
  {id:1596,german:"die Präzision",level:"B2",english:"precision",pos:"noun (f)",sentences:[{"de": "Wissenschaftliche Texte erfordern höchste Präzision in der Formulierung.", "en": "Scientific texts require the utmost precision in their formulation."}, {"de": "Die Präzision seiner Arbeit beeindruckte alle Kollegen.", "en": "The precision of his work impressed all colleagues."}]},
  {id:1597,german:"die Vollständigkeit",level:"B2",english:"completeness",pos:"noun (f)",sentences:[{"de": "Die Vollständigkeit der Bewerbungsunterlagen ist Voraussetzung für die Bearbeitung.", "en": "The completeness of the application documents is a prerequisite for processing."}, {"de": "Der Bericht wurde wegen fehlender Vollständigkeit zurückgeschickt.", "en": "The report was sent back due to lack of completeness."}]},
  {id:1598,german:"die Korrektheit",level:"B2",english:"correctness, accuracy",pos:"noun (f)",sentences:[{"de": "Die sprachliche Korrektheit eines Textes lässt sich mit einem Korrekturprogramm überprüfen.", "en": "The linguistic correctness of a text can be checked with a correction programme."}, {"de": "Politische Korrektheit ist in öffentlichen Debatten ein viel diskutiertes Thema.", "en": "Political correctness is a much-discussed topic in public debates."}]},
  {id:1599,german:"die Formulierung",level:"B2",english:"formulation, wording, phrasing",pos:"noun (f)",sentences:[{"de": "Die geschickte Formulierung des Angebots überzeugte den Kunden.", "en": "The skilful wording of the offer convinced the customer."}, {"de": "Er arbeitete lange an der richtigen Formulierung seiner Kritik.", "en": "He worked for a long time on the right phrasing of his criticism."}]},
  {id:1600,german:"der Ausdruck",level:"B2",english:"expression",pos:"noun (m)",sentences:[{"de": "Dieser Ausdruck ist in der deutschen Alltagssprache sehr gebräuchlich.", "en": "This expression is very common in everyday German."}, {"de": "Die Schriftstellerin wählte ihre Ausdrücke mit großer Sorgfalt.", "en": "The writer chose her expressions with great care."}]},
  {id:1601,german:"der Stil",level:"B2",english:"style",pos:"noun (m)",sentences:[{"de": "Der Stil eines Textes verrät viel über den Autor und seinen Hintergrund.", "en": "The style of a text reveals a lot about the author and their background."}, {"de": "Sie schreibt in einem klaren, sachlichen Stil ohne unnötige Ausschmückungen.", "en": "She writes in a clear, factual style without unnecessary embellishments."}]},
  {id:1602,german:"die Textsorte",level:"B2",english:"text type, genre",pos:"noun (f)",sentences:[{"de": "Für jede Textsorte gibt es spezifische sprachliche Merkmale und Konventionen.", "en": "Each text type has specific linguistic features and conventions."}, {"de": "Im B2-Kurs lernt man, verschiedene Textsorten zu verfassen.", "en": "In the B2 course, one learns to write various text types."}]},
  {id:1603,german:"die Zusammenfassung",level:"B2",english:"summary",pos:"noun (f)",sentences:[{"de": "Am Ende des Kapitels gibt es eine Zusammenfassung der wichtigsten Punkte.", "en": "At the end of the chapter, there is a summary of the main points."}, {"de": "Er schrieb eine kurze Zusammenfassung des Artikels für seinen Chef.", "en": "He wrote a brief summary of the article for his boss."}]},
  {id:1604,german:"die Inhaltsangabe",level:"B2",english:"summary, synopsis",pos:"noun (f)",sentences:[{"de": "Die Schüler mussten eine Inhaltsangabe des Romans schreiben.", "en": "The pupils had to write a synopsis of the novel."}, {"de": "Eine gute Inhaltsangabe gibt den wesentlichen Inhalt ohne persönliche Wertung wieder.", "en": "A good summary reproduces the essential content without personal evaluation."}]},
  {id:1605,german:"der Kommentar",level:"B2",english:"comment, commentary",pos:"noun (m)",sentences:[{"de": "Der Kommentar des Journalisten zur Wahlnacht war sehr treffend.", "en": "The journalist's commentary on election night was very apt."}, {"de": "Sie bat ihre Kollegen um konstruktive Kommentare zu ihrem Entwurf.", "en": "She asked her colleagues for constructive comments on her draft."}]},
  {id:1606,german:"die Stellungnahme",level:"B2",english:"statement, position paper, opinion",pos:"noun (f)",sentences:[{"de": "Die Regierung gab eine offizielle Stellungnahme zu den Vorwürfen heraus.", "en": "The government issued an official statement on the allegations."}, {"de": "Im Aufsatz sollte jeder Schüler eine begründete Stellungnahme formulieren.", "en": "In the essay, each pupil was supposed to formulate a reasoned opinion."}]},
  {id:1607,german:"die Argumentation",level:"B2",english:"argumentation, line of argument",pos:"noun (f)",sentences:[{"de": "Seine Argumentation war logisch aufgebaut und gut belegt.", "en": "His line of argument was logically structured and well substantiated."}, {"de": "Eine überzeugende Argumentation braucht stichhaltige Belege und Beispiele.", "en": "A convincing argumentation needs sound evidence and examples."}]},
  {id:1608,german:"die Schlussfolgerung",level:"B2",english:"conclusion",pos:"noun (f)",sentences:[{"de": "Die Schlussfolgerung des Autors war überraschend und provokant.", "en": "The author's conclusion was surprising and provocative."}, {"de": "Aus den Daten lässt sich keine eindeutige Schlussfolgerung ziehen.", "en": "No clear conclusion can be drawn from the data."}]},
  {id:1609,german:"die These",level:"B2",english:"thesis, proposition",pos:"noun (f)",sentences:[{"de": "Sie stellte die These auf, dass der Klimawandel auch kulturelle Ursachen hat.", "en": "She put forward the thesis that climate change also has cultural causes."}, {"de": "Die These des Wissenschaftlers wurde von der Fachwelt kontrovers diskutiert.", "en": "The scientist's thesis was controversially discussed by the academic community."}]},
  {id:1610,german:"das Argument",level:"B2",english:"argument",pos:"noun (n)",sentences:[{"de": "Er brachte überzeugende Argumente für seine Position vor.", "en": "He put forward convincing arguments in favour of his position."}, {"de": "Das stärkste Argument gegen die Maßnahme ist die fehlende wissenschaftliche Grundlage.", "en": "The strongest argument against the measure is the lack of a scientific basis."}]},
  {id:1611,german:"der Beweis",level:"B2",english:"proof, evidence",pos:"noun (m)",sentences:[{"de": "Die Staatsanwaltschaft legte eindeutige Beweise für die Schuld des Angeklagten vor.", "en": "The prosecution presented clear evidence of the defendant's guilt."}, {"de": "Ohne Beweis können die Vorwürfe nicht aufrechterhalten werden.", "en": "Without evidence, the allegations cannot be maintained."}]},
  {id:1612,german:"das Beispiel",level:"B2",english:"example",pos:"noun (n)",sentences:[{"de": "Er nannte mehrere Beispiele aus der Praxis, um seine Theorie zu veranschaulichen.", "en": "He cited several practical examples to illustrate his theory."}, {"de": "Zum Beispiel könnte man das Problem durch mehr Investitionen in Bildung lösen.", "en": "For example, the problem could be solved through greater investment in education."}]},
  {id:1613,german:"die Illustration",level:"B2",english:"illustration",pos:"noun (f)",sentences:[{"de": "Die Illustration im Lehrbuch hilft, komplizierte Zusammenhänge zu verstehen.", "en": "The illustration in the textbook helps to understand complicated relationships."}, {"de": "Als Illustration für seine These zog er historische Beispiele heran.", "en": "As an illustration of his thesis, he drew on historical examples."}]},
  {id:1614,german:"die Metapher",level:"B2",english:"metaphor",pos:"noun (f)",sentences:[{"de": "Die Metapher vom Lebensweg ist in der deutschen Literatur sehr verbreitet.", "en": "The metaphor of the life path is very common in German literature."}, {"de": "Er nutzte eine eindrucksvolle Metapher, um seine Gefühle zu beschreiben.", "en": "He used a striking metaphor to describe his feelings."}]},
  {id:1615,german:"das Symbol",level:"B2",english:"symbol",pos:"noun (n)",sentences:[{"de": "Die Taube ist ein weltweit bekanntes Symbol für Frieden.", "en": "The dove is a universally known symbol for peace."}, {"de": "In der Literatur wird Wasser häufig als Symbol für Erneuerung und Reinheit verwendet.", "en": "In literature, water is often used as a symbol for renewal and purity."}]},
  {id:1616,german:"die Interpretation",level:"B2",english:"interpretation",pos:"noun (f)",sentences:[{"de": "Die Interpretation des Gedichts ist Gegenstand wissenschaftlicher Diskussionen.", "en": "The interpretation of the poem is the subject of academic discussions."}, {"de": "Er hat eine sehr persönliche Interpretation des Begriffs Freiheit entwickelt.", "en": "He has developed a very personal interpretation of the concept of freedom."}]},
  {id:1617,german:"die Kritik",level:"B2",english:"criticism, critique",pos:"noun (f)",sentences:[{"de": "Konstruktive Kritik ist wichtig für die persönliche Weiterentwicklung.", "en": "Constructive criticism is important for personal development."}, {"de": "Die Filmkritik in der Zeitung war vernichtend für das neue Werk des Regisseurs.", "en": "The film critique in the newspaper was devastating for the director's new work."}]},
  {id:1618,german:"die Bewertung",level:"B2",english:"evaluation, assessment, rating",pos:"noun (f)",sentences:[{"de": "Die Bewertung der Prüfungsarbeit erfolgt nach einem festen Kriterienkatalog.", "en": "The assessment of the exam paper is carried out according to a fixed set of criteria."}, {"de": "Kundenbewertungen im Internet beeinflussen die Kaufentscheidungen vieler Menschen.", "en": "Customer ratings on the internet influence the purchasing decisions of many people."}]},
  {id:1619,german:"die Einschätzung",level:"B2",english:"assessment, estimation, judgement",pos:"noun (f)",sentences:[{"de": "Seine Einschätzung der Lage erwies sich als zutreffend.", "en": "His assessment of the situation proved to be accurate."}, {"de": "Nach Einschätzung der Experten wird die Wirtschaft im nächsten Jahr wachsen.", "en": "According to the experts' judgement, the economy will grow next year."}]},
  {id:1620,german:"die Perspektive",level:"B2",english:"perspective, viewpoint",pos:"noun (f)",sentences:[{"de": "Aus einer anderen Perspektive betrachtet erscheint das Problem viel einfacher.", "en": "Viewed from a different perspective, the problem appears much simpler."}, {"de": "Die Perspektive der Betroffenen wird in der Debatte oft ignoriert.", "en": "The perspective of those affected is often ignored in the debate."}]},
  {id:1621,german:"der Standpunkt",level:"B2",english:"standpoint, point of view",pos:"noun (m)",sentences:[{"de": "Sie vertrat ihren Standpunkt überzeugend und ließ sich nicht beirren.", "en": "She defended her standpoint convincingly and was not deterred."}, {"de": "Von einem rein wirtschaftlichen Standpunkt aus gesehen ist die Entscheidung nachvollziehbar.", "en": "From a purely economic point of view, the decision is understandable."}]},
  {id:1622,german:"die Meinung",level:"B2",english:"opinion",pos:"noun (f)",sentences:[{"de": "Jeder hat das Recht, seine Meinung frei zu äußern.", "en": "Everyone has the right to express their opinion freely."}, {"de": "Die Meinungen über die neue Stadtplanung gehen weit auseinander.", "en": "Opinions about the new urban planning differ widely."}]},
  {id:1623,german:"die Überzeugung",level:"B2",english:"conviction, belief",pos:"noun (f)",sentences:[{"de": "Er handelt stets nach seiner inneren Überzeugung, auch wenn es unpopulär ist.", "en": "He always acts according to his inner conviction, even when it is unpopular."}, {"de": "Die Überzeugung, das Richtige zu tun, gab ihr die nötige Stärke.", "en": "The conviction of doing the right thing gave her the necessary strength."}]},
  {id:1624,german:"die Einstellung",level:"B2",english:"attitude, setting, employment",pos:"noun (f)",sentences:[{"de": "Eine positive Einstellung zur Arbeit beeinflusst die Leistung erheblich.", "en": "A positive attitude to work has a considerable influence on performance."}, {"de": "Die Einstellung neuer Mitarbeiter wurde aufgrund der wirtschaftlichen Lage gestoppt.", "en": "The employment of new staff was halted due to the economic situation."}]},
  {id:1625,german:"die Haltung",level:"B2",english:"posture, attitude, stance",pos:"noun (f)",sentences:[{"de": "Die Haltung der Regierung zu diesem Thema ist klar und unmissverständlich.", "en": "The government's stance on this issue is clear and unambiguous."}, {"de": "Eine aufrechte Haltung vermittelt Selbstsicherheit und Kompetenz.", "en": "An upright posture conveys self-confidence and competence."}]},
  {id:1626,german:"das Vorurteil",level:"B2",english:"prejudice",pos:"noun (n)",sentences:[{"de": "Vorurteile gegenüber bestimmten Gruppen entstehen oft durch mangelnde Kenntnisse.", "en": "Prejudices against certain groups often arise from a lack of knowledge."}, {"de": "Es ist wichtig, Vorurteile zu hinterfragen und kritisch zu reflektieren.", "en": "It is important to question and critically reflect on prejudices."}]},
  {id:1627,german:"die Diskriminierung",level:"B2",english:"discrimination",pos:"noun (f)",sentences:[{"de": "Diskriminierung aufgrund der Religion oder Herkunft ist in Deutschland gesetzlich verboten.", "en": "Discrimination on the grounds of religion or origin is prohibited by law in Germany."}, {"de": "Die Organisation setzt sich aktiv gegen jede Form von Diskriminierung ein.", "en": "The organisation actively works against all forms of discrimination."}]},
  {id:1628,german:"der Rassismus",level:"B2",english:"racism",pos:"noun (m)",sentences:[{"de": "Rassismus ist ein gesamtgesellschaftliches Problem, das alle angehen müssen.", "en": "Racism is a societal problem that everyone must address."}, {"de": "Struktureller Rassismus zeigt sich in ungleichen Chancen und Behandlungen.", "en": "Structural racism manifests itself in unequal opportunities and treatment."}]},
  {id:1629,german:"der Sexismus",level:"B2",english:"sexism",pos:"noun (m)",sentences:[{"de": "Sexismus im Arbeitsumfeld kann die Karriere von Frauen erheblich behindern.", "en": "Sexism in the workplace can significantly hinder women's careers."}, {"de": "Viele Frauen haben von sexistischen Kommentaren und Verhaltensweisen berichtet.", "en": "Many women have reported sexist comments and behaviour."}]},
  {id:1630,german:"die Gleichstellung",level:"B2",english:"equality, equal treatment",pos:"noun (f)",sentences:[{"de": "Die Gleichstellung von Männern und Frauen ist im Grundgesetz verankert.", "en": "The equality of men and women is enshrined in the Basic Law."}, {"de": "Trotz gesetzlicher Regelungen ist die Gleichstellung in der Praxis noch nicht erreicht.", "en": "Despite legal regulations, equality has not yet been achieved in practice."}]},
  {id:1631,german:"die Chancengleichheit",level:"B2",english:"equal opportunities",pos:"noun (f)",sentences:[{"de": "Bildungspolitik sollte auf die Förderung von Chancengleichheit ausgerichtet sein.", "en": "Education policy should be geared towards promoting equal opportunities."}, {"de": "Soziale Herkunft darf die Chancengleichheit eines Kindes nicht beeinträchtigen.", "en": "Social background must not impair a child's equal opportunities."}]},
  {id:1632,german:"die Gerechtigkeit",level:"B2",english:"justice, fairness",pos:"noun (f)",sentences:[{"de": "Soziale Gerechtigkeit bedeutet, dass alle Menschen gleiche Chancen haben sollten.", "en": "Social justice means that all people should have equal opportunities."}, {"de": "Das Urteil wurde von vielen als ein Zeichen für Gerechtigkeit gewertet.", "en": "The verdict was seen by many as a sign of justice."}]},
  {id:1633,german:"die Ungerechtigkeit",level:"B2",english:"injustice, unfairness",pos:"noun (f)",sentences:[{"de": "Die soziale Ungerechtigkeit in vielen Ländern nimmt trotz wirtschaftlichen Wachstums zu.", "en": "Social injustice in many countries is increasing despite economic growth."}, {"de": "Sie empfand es als große Ungerechtigkeit, dass ihr Kollege mehr verdiente.", "en": "She felt it was a great injustice that her colleague earned more."}]},
  {id:1634,german:"die Demokratie",level:"B2",english:"democracy",pos:"noun (f)",sentences:[{"de": "Eine lebendige Demokratie braucht aktive Bürgerinnen und Bürger.", "en": "A vibrant democracy needs active citizens."}, {"de": "Die Demokratie ist die Regierungsform, die die Grundrechte der Menschen am besten schützt.", "en": "Democracy is the form of government that best protects people's fundamental rights."}]},
  {id:1635,german:"die Partizipation",level:"B2",english:"participation",pos:"noun (f)",sentences:[{"de": "Die Partizipation der Bevölkerung an politischen Entscheidungen ist ein Grundprinzip der Demokratie.", "en": "The participation of the population in political decisions is a fundamental principle of democracy."}, {"de": "Digitale Plattformen ermöglichen eine neue Form der politischen Partizipation.", "en": "Digital platforms enable a new form of political participation."}]},
  {id:1636,german:"die Bürgerbeteiligung",level:"B2",english:"citizen participation, civic engagement",pos:"noun (f)",sentences:[{"de": "Bei der Stadtplanung setzt die Gemeinde auf eine breite Bürgerbeteiligung.", "en": "In urban planning, the municipality relies on broad citizen participation."}, {"de": "Bürgerbeteiligung stärkt das Vertrauen in demokratische Prozesse.", "en": "Civic engagement strengthens trust in democratic processes."}]},
  {id:1637,german:"die Zivilgesellschaft",level:"B2",english:"civil society",pos:"noun (f)",sentences:[{"de": "Eine starke Zivilgesellschaft ist ein wichtiges Gegengewicht zur staatlichen Macht.", "en": "A strong civil society is an important counterweight to state power."}, {"de": "Vereine, NGOs und Bürgergruppen bilden das Rückgrat der Zivilgesellschaft.", "en": "Associations, NGOs and citizens' groups form the backbone of civil society."}]},
  {id:1638,german:"die Transparenz",level:"B2",english:"transparency",pos:"noun (f)",sentences:[{"de": "Transparenz in der Politik bedeutet, dass Entscheidungsprozesse nachvollziehbar sein müssen.", "en": "Transparency in politics means that decision-making processes must be comprehensible."}, {"de": "Das Unternehmen setzt auf Transparenz gegenüber seinen Aktionären.", "en": "The company is committed to transparency with its shareholders."}]},
  {id:1639,german:"die Rechenschaftspflicht",level:"B2",english:"accountability",pos:"noun (f)",sentences:[{"de": "Politikerinnen und Politiker unterliegen einer Rechenschaftspflicht gegenüber den Wählerinnen und Wählern.", "en": "Politicians are subject to accountability to the voters."}, {"de": "Die Rechenschaftspflicht öffentlicher Institutionen ist in einer Demokratie unverzichtbar.", "en": "The accountability of public institutions is indispensable in a democracy."}]},
  {id:1640,german:"die Korruption",level:"B2",english:"corruption",pos:"noun (f)",sentences:[{"de": "Korruption untergräbt das Vertrauen der Bevölkerung in staatliche Institutionen.", "en": "Corruption undermines the population's trust in state institutions."}, {"de": "Internationale Organisationen bemühen sich um die Bekämpfung von Korruption weltweit.", "en": "International organisations are working to combat corruption worldwide."}]},
  {id:1641,german:"die Bürokratie",level:"B2",english:"bureaucracy",pos:"noun (f)",sentences:[{"de": "Unternehmer klagen häufig über die übermäßige Bürokratie in Deutschland.", "en": "Entrepreneurs frequently complain about excessive bureaucracy in Germany."}, {"de": "Der Abbau von Bürokratie ist ein zentrales Ziel der aktuellen Regierung.", "en": "The reduction of bureaucracy is a central goal of the current government."}]},
  {id:1642,german:"die Verwaltung",level:"B2",english:"administration, management",pos:"noun (f)",sentences:[{"de": "Die städtische Verwaltung ist für die Ausstellung von Personalausweisen zuständig.", "en": "The city administration is responsible for issuing identity cards."}, {"de": "Eine effiziente Verwaltung ist Grundlage für das Funktionieren eines Staates.", "en": "Efficient administration is the basis for the functioning of a state."}]},
  {id:1643,german:"die öffentliche Verwaltung",level:"B2",english:"public administration",pos:"noun (f)",sentences:[{"de": "Die öffentliche Verwaltung wird zunehmend digitalisiert, um Prozesse zu beschleunigen.", "en": "Public administration is increasingly being digitalised to speed up processes."}, {"de": "Beschäftigte in der öffentlichen Verwaltung genießen besondere Beschäftigungssicherheit.", "en": "Employees in public administration enjoy particular employment security."}]},
  {id:1644,german:"das Ministerium",level:"B2",english:"ministry, department",pos:"noun (n)",sentences:[{"de": "Das Bundesministerium für Gesundheit ist für die Gesundheitspolitik verantwortlich.", "en": "The Federal Ministry of Health is responsible for health policy."}, {"de": "Das Ministerium hat neue Richtlinien für die Bildungseinrichtungen herausgegeben.", "en": "The ministry has issued new guidelines for educational institutions."}]},
  {id:1645,german:"das Gericht",level:"B2",english:"court; dish, meal",pos:"noun (n)",sentences:[{"de": "Das Gericht entschied, dass die Kündigung rechtmäßig war.", "en": "The court decided that the dismissal was lawful."}, {"de": "Das traditionelle Gericht wurde nach einem alten Familienrezept zubereitet.", "en": "The traditional dish was prepared according to an old family recipe."}]},
  {id:1646,german:"das Strafrecht",level:"B2",english:"criminal law",pos:"noun (n)",sentences:[{"de": "Das Strafrecht definiert, welche Handlungen als Verbrechen gelten und wie sie bestraft werden.", "en": "Criminal law defines which actions are considered crimes and how they are punished."}, {"de": "Im Strafrecht gilt grundsätzlich die Unschuldsvermutung.", "en": "In criminal law, the presumption of innocence applies as a basic principle."}]},
  {id:1647,german:"das Zivilrecht",level:"B2",english:"civil law",pos:"noun (n)",sentences:[{"de": "Das Zivilrecht regelt die Beziehungen zwischen Privatpersonen und Unternehmen.", "en": "Civil law governs the relationships between private individuals and companies."}, {"de": "Im Zivilrecht streiten die Parteien um Rechte und Ansprüche.", "en": "In civil law, the parties dispute rights and claims."}]},
  {id:1648,german:"die Klage",level:"B2",english:"lawsuit, legal action; complaint",pos:"noun (f)",sentences:[{"de": "Er reichte eine Klage gegen seinen ehemaligen Arbeitgeber ein.", "en": "He filed a lawsuit against his former employer."}, {"de": "Die Klage über den Lärm der Nachbarn wurde beim Vermieter vorgebracht.", "en": "The complaint about the neighbours' noise was raised with the landlord."}]},
  {id:1649,german:"die Anklage",level:"B2",english:"charge, accusation, prosecution",pos:"noun (f)",sentences:[{"de": "Die Staatsanwaltschaft erhob Anklage wegen Betruges gegen den Manager.", "en": "The public prosecutor brought charges of fraud against the manager."}, {"de": "Unter der Anklage des Diebstahls wurde er vor Gericht gestellt.", "en": "He was brought to court on charges of theft."}]},
  {id:1650,german:"die Verurteilung",level:"B2",english:"conviction, sentencing",pos:"noun (f)",sentences:[{"de": "Die Verurteilung des Angeklagten zu drei Jahren Haft sorgte für Diskussionen.", "en": "The defendant's conviction and sentencing to three years in prison caused debate."}, {"de": "Eine Verurteilung wegen dieses Verbrechens kann bis zu zehn Jahre Haft bedeuten.", "en": "A conviction for this crime can mean up to ten years in prison."}]},
  {id:1651,german:"die Freiheitsstrafe",level:"B2",english:"prison sentence, custodial sentence",pos:"noun (f)",sentences:[{"de": "Für das schwere Vergehen erhielt er eine Freiheitsstrafe von fünf Jahren.", "en": "For the serious offence, he received a custodial sentence of five years."}, {"de": "Das Gericht verhängte eine Freiheitsstrafe auf Bewährung.", "en": "The court imposed a suspended prison sentence."}]},
  {id:1652,german:"die Geldstrafe",level:"B2",english:"fine",pos:"noun (f)",sentences:[{"de": "Für das Parken im Halteverbot erhielt er eine Geldstrafe von fünfzig Euro.", "en": "He received a fine of fifty euros for parking in a no-stopping zone."}, {"de": "Das Gericht verurteilte ihn zu einer hohen Geldstrafe statt zu einer Freiheitsstrafe.", "en": "The court sentenced him to a heavy fine instead of a prison sentence."}]},
  {id:1653,german:"die Bewährung",level:"B2",english:"probation",pos:"noun (f)",sentences:[{"de": "Die Freiheitsstrafe wurde zur Bewährung ausgesetzt, da es sich um einen Ersttäter handelte.", "en": "The prison sentence was suspended on probation as it was a first-time offender."}, {"de": "Er muss sich während der Bewährung regelmäßig beim Bewährungshelfer melden.", "en": "During probation, he must regularly report to his probation officer."}]},
  {id:1654,german:"die Rehabilitation",level:"B2",english:"rehabilitation",pos:"noun (f)",sentences:[{"de": "Nach dem Herzinfarkt war er zur Rehabilitation in einer Spezialklinik.", "en": "After the heart attack, he went to a specialist clinic for rehabilitation."}, {"de": "Die Rehabilitation von Straftätern soll ihre Wiedereingliederung in die Gesellschaft ermöglichen.", "en": "The rehabilitation of offenders is intended to enable their reintegration into society."}]},
  {id:1655,german:"der Strafvollzug",level:"B2",english:"prison service, execution of sentence",pos:"noun (m)",sentences:[{"de": "Der Strafvollzug soll sowohl bestrafen als auch resozialisieren.", "en": "The execution of sentence should both punish and rehabilitate."}, {"de": "Reformen im Strafvollzug zielen darauf ab, die Rückfallquote zu senken.", "en": "Reforms in the prison service aim to reduce the rate of reoffending."}]},
  {id:1656,german:"die Justizvollzugsanstalt",level:"B2",english:"prison, correctional facility",pos:"noun (f)",sentences:[{"de": "Die Justizvollzugsanstalt bietet Insassen Berufsausbildungsprogramme an.", "en": "The correctional facility offers inmates vocational training programmes."}, {"de": "In der Justizvollzugsanstalt sind derzeit mehr Gefangene als die Kapazität vorsieht.", "en": "The prison currently holds more inmates than its capacity allows."}]},
  {id:1657,german:"die Resozialisierung",level:"B2",english:"rehabilitation, reintegration into society",pos:"noun (f)",sentences:[{"de": "Die Resozialisierung von Straftätern ist ein zentrales Ziel des deutschen Strafvollzugs.", "en": "The reintegration of offenders into society is a central aim of the German prison system."}, {"de": "Ohne ausreichende Unterstützung gelingt die Resozialisierung selten.", "en": "Without adequate support, reintegration into society rarely succeeds."}]},
  {id:1658,german:"die Mediation",level:"B2",english:"mediation",pos:"noun (f)",sentences:[{"de": "Durch Mediation konnten die Streitparteien eine für beide Seiten akzeptable Lösung finden.", "en": "Through mediation, the parties to the dispute were able to find a solution acceptable to both sides."}, {"de": "Mediation ist oft schneller und kostengünstiger als ein Gerichtsverfahren.", "en": "Mediation is often faster and less expensive than court proceedings."}]},
  {id:1659,german:"die außergerichtliche Einigung",level:"B2",english:"out-of-court settlement",pos:"noun (f)",sentences:[{"de": "Die Parteien erzielten eine außergerichtliche Einigung und vermieden so den Prozess.", "en": "The parties reached an out-of-court settlement, thereby avoiding the trial."}, {"de": "Eine außergerichtliche Einigung spart Zeit, Geld und nervliche Belastung.", "en": "An out-of-court settlement saves time, money and stress."}]},
  {id:1660,german:"die Streitbeilegung",level:"B2",english:"dispute resolution, settlement",pos:"noun (f)",sentences:[{"de": "Die außergerichtliche Streitbeilegung wird in vielen Ländern aktiv gefördert.", "en": "Out-of-court dispute resolution is actively promoted in many countries."}, {"de": "Es gibt verschiedene Verfahren zur Streitbeilegung, darunter Mediation und Schiedsverfahren.", "en": "There are various procedures for dispute resolution, including mediation and arbitration."}]},
  {id:1661,german:"der/die Mediator/-in",level:"B2",english:"mediator",pos:"noun (m/f)",sentences:[{"de": "Der Mediator hilft den streitenden Parteien, gemeinsam eine Lösung zu erarbeiten.", "en": "The mediator helps the disputing parties to work out a solution together."}, {"de": "Ein guter Mediator bleibt stets neutral und beeinflusst die Parteien nicht.", "en": "A good mediator always remains neutral and does not influence the parties."}]},
  {id:1662,german:"das Schiedsverfahren",level:"B2",english:"arbitration proceedings",pos:"noun (n)",sentences:[{"de": "Das Schiedsverfahren ermöglicht eine schnelle und vertrauliche Lösung von Streitigkeiten.", "en": "Arbitration proceedings enable a quick and confidential resolution of disputes."}, {"de": "Viele internationale Verträge enthalten eine Klausel für das Schiedsverfahren.", "en": "Many international contracts contain a clause for arbitration proceedings."}]},
  {id:1663,german:"das Schiedsgericht",level:"B2",english:"arbitration court, arbitral tribunal",pos:"noun (n)",sentences:[{"de": "Das Schiedsgericht entschied zugunsten des klagenden Unternehmens.", "en": "The arbitral tribunal decided in favour of the claimant company."}, {"de": "Ein Schiedsgericht ist eine Alternative zum staatlichen Gericht.", "en": "An arbitral tribunal is an alternative to state courts."}]},
  {id:1664,german:"die Integration",level:"B2",english:"integration",pos:"noun (f)",sentences:[{"de": "Die Integration von Zuwanderern ist eine der größten Herausforderungen unserer Zeit.", "en": "The integration of immigrants is one of the greatest challenges of our time."}, {"de": "Sprachkenntnisse sind der Schlüssel für eine erfolgreiche Integration.", "en": "Language skills are the key to successful integration."}]},
  {id:1665,german:"der/die Nachfolger/-in",level:"B2",english:"successor",pos:"noun (m/f)",sentences:[{"de": "Der Nachfolger des bisherigen Vorsitzenden wurde auf der Jahreshauptversammlung gewählt.", "en": "The successor to the previous chairman was elected at the annual general meeting."}, {"de": "Sie gilt als die wahrscheinlichste Nachfolgerin des scheidenden Direktors.", "en": "She is considered the most likely successor to the outgoing director."}]},
  {id:1666,german:"der/die Schwerbehinderte",level:"B2",english:"severely disabled person",pos:"noun (m/f)",sentences:[{"de": "Schwerbehinderte haben in Deutschland besondere Rechte auf dem Arbeitsmarkt.", "en": "Severely disabled people have special rights in the German labour market."}, {"de": "Unternehmen ab 20 Mitarbeitern sind verpflichtet, Schwerbehinderte zu beschäftigen.", "en": "Companies with 20 or more employees are obliged to employ severely disabled persons."}]},
  {id:1667,german:"die Inklusion",level:"B2",english:"inclusion",pos:"noun (f)",sentences:[{"de": "Inklusion bedeutet, dass Menschen mit Behinderungen vollständig an der Gesellschaft teilhaben können.", "en": "Inclusion means that people with disabilities can fully participate in society."}, {"de": "Die Inklusion in Schulen wird durch einen Mangel an Ressourcen oft erschwert.", "en": "Inclusion in schools is often hampered by a lack of resources."}]},
  {id:1668,german:"die Diversität",level:"B2",english:"diversity",pos:"noun (f)",sentences:[{"de": "Diversität in Teams fördert Kreativität und Innovation.", "en": "Diversity in teams promotes creativity and innovation."}, {"de": "Das Unternehmen hat eine Strategie zur Förderung von Diversität entwickelt.", "en": "The company has developed a strategy to promote diversity."}]},
  {id:1669,german:"die Gleichberechtigung",level:"B2",english:"equal rights",pos:"noun (f)",sentences:[{"de": "Die Gleichberechtigung von Mann und Frau ist noch nicht in allen Bereichen verwirklicht.", "en": "Equal rights for men and women have not yet been realised in all areas."}, {"de": "Für die Gleichberechtigung aller Menschen unabhängig von ihrer Herkunft einzutreten ist wichtig.", "en": "It is important to stand up for equal rights for all people regardless of their origin."}]},
  {id:1670,german:"die Unternehmensführung",level:"B2",english:"company management, corporate governance",pos:"noun (f)",sentences:[{"de": "Gute Unternehmensführung kombiniert strategisches Denken mit sozialer Verantwortung.", "en": "Good corporate governance combines strategic thinking with social responsibility."}, {"de": "Die Unternehmensführung hat entschieden, den Standort ins Ausland zu verlagern.", "en": "Company management has decided to relocate the site abroad."}]},
  {id:1671,german:"die Geschäftsstrategie",level:"B2",english:"business strategy",pos:"noun (f)",sentences:[{"de": "Das Unternehmen muss seine Geschäftsstrategie anpassen, um wettbewerbsfähig zu bleiben.", "en": "The company must adapt its business strategy to remain competitive."}, {"de": "Eine klare Geschäftsstrategie ist die Voraussetzung für langfristigen Erfolg.", "en": "A clear business strategy is the prerequisite for long-term success."}]},
  {id:1672,german:"das Geschäftsmodell",level:"B2",english:"business model",pos:"noun (n)",sentences:[{"de": "Das Geschäftsmodell des Unternehmens basiert auf Abonnementgebühren statt Einmalzahlungen.", "en": "The company's business model is based on subscription fees rather than one-off payments."}, {"de": "Digitale Plattformen haben viele traditionelle Geschäftsmodelle grundlegend verändert.", "en": "Digital platforms have fundamentally changed many traditional business models."}]},
  {id:1673,german:"die Wertschöpfungskette",level:"B2",english:"value chain",pos:"noun (f)",sentences:[{"de": "Das Unternehmen kontrolliert die gesamte Wertschöpfungskette vom Rohstoff bis zum Endprodukt.", "en": "The company controls the entire value chain from raw material to finished product."}, {"de": "Outsourcing kann bestimmte Glieder der Wertschöpfungskette effizienter gestalten.", "en": "Outsourcing can make certain links in the value chain more efficient."}]},
  {id:1674,german:"die Kernkompetenz",level:"B2",english:"core competence",pos:"noun (f)",sentences:[{"de": "Das Unternehmen konzentriert sich auf seine Kernkompetenz in der Softwareentwicklung.", "en": "The company focuses on its core competence in software development."}, {"de": "Aufgaben außerhalb der Kernkompetenz werden häufig ausgelagert.", "en": "Tasks outside the core competence are frequently outsourced."}]},
  {id:1675,german:"die Wettbewerbsfähigkeit",level:"B2",english:"competitiveness",pos:"noun (f)",sentences:[{"de": "Deutschland muss seine Wettbewerbsfähigkeit durch Innovationen stärken.", "en": "Germany must strengthen its competitiveness through innovation."}, {"de": "Hohe Produktionskosten gefährden die Wettbewerbsfähigkeit der heimischen Industrie.", "en": "High production costs threaten the competitiveness of domestic industry."}]},
  {id:1676,german:"die Marktposition",level:"B2",english:"market position",pos:"noun (f)",sentences:[{"de": "Das Unternehmen hat seine Marktposition durch gezielte Akquisitionen ausgebaut.", "en": "The company has expanded its market position through targeted acquisitions."}, {"de": "Eine starke Marktposition bietet Schutz vor dem Wettbewerb.", "en": "A strong market position provides protection against competition."}]},
  {id:1677,german:"die Marktstrategie",level:"B2",english:"market strategy",pos:"noun (f)",sentences:[{"de": "Die neue Marktstrategie zielt auf jüngere Zielgruppen ab.", "en": "The new market strategy targets younger demographics."}, {"de": "Eine erfolgreiche Marktstrategie erfordert eine gründliche Analyse der Konkurrenz.", "en": "A successful market strategy requires a thorough analysis of the competition."}]},
  {id:1678,german:"die Expansion",level:"B2",english:"expansion",pos:"noun (f)",sentences:[{"de": "Die Expansion in neue Märkte ist mit erheblichen Risiken verbunden.", "en": "Expansion into new markets involves considerable risks."}, {"de": "Das Unternehmen plant eine Expansion nach Südostasien.", "en": "The company is planning an expansion into Southeast Asia."}]},
  {id:1679,german:"die Fusion",level:"B2",english:"merger, fusion",pos:"noun (f)",sentences:[{"de": "Die Fusion der beiden Banken schuf das größte Finanzinstitut des Landes.", "en": "The merger of the two banks created the country's largest financial institution."}, {"de": "Bei einer Fusion müssen die Unternehmenskulturen sorgfältig aufeinander abgestimmt werden.", "en": "In a merger, the corporate cultures must be carefully aligned."}]},
  {id:1680,german:"die Übernahme",level:"B2",english:"takeover, acquisition",pos:"noun (f)",sentences:[{"de": "Die feindliche Übernahme des Konkurrenten wurde vom Kartellamt genehmigt.", "en": "The hostile takeover of the competitor was approved by the cartel office."}, {"de": "Nach der Übernahme durch den Großkonzern wurden Stellen abgebaut.", "en": "Following the acquisition by the large corporation, jobs were cut."}]},
  {id:1681,german:"die Insolvenz",level:"B2",english:"insolvency, bankruptcy",pos:"noun (f)",sentences:[{"de": "Das Unternehmen musste nach jahrelangen Verlusten Insolvenz anmelden.", "en": "The company had to file for insolvency after years of losses."}, {"de": "Die Insolvenz des Zulieferers gefährdete die gesamte Produktionskette.", "en": "The insolvency of the supplier endangered the entire production chain."}]},
  {id:1682,german:"die Liquidation",level:"B2",english:"liquidation",pos:"noun (f)",sentences:[{"de": "Nach der Insolvenz wurde die Liquidation des Unternehmens eingeleitet.", "en": "After insolvency, the liquidation of the company was initiated."}, {"de": "Bei der Liquidation werden alle Vermögenswerte verkauft und die Schulden beglichen.", "en": "During liquidation, all assets are sold and debts settled."}]},
  {id:1683,german:"die Restrukturierung",level:"B2",english:"restructuring",pos:"noun (f)",sentences:[{"de": "Die Restrukturierung des Konzerns führte zu erheblichem Stellenabbau.", "en": "The restructuring of the group led to significant job cuts."}, {"de": "Eine umfassende Restrukturierung soll das Unternehmen wieder profitabel machen.", "en": "A comprehensive restructuring is intended to make the company profitable again."}]},
  {id:1684,german:"das Outsourcing",level:"B2",english:"outsourcing",pos:"noun (n)",sentences:[{"de": "Durch Outsourcing können Unternehmen Kosten senken und sich auf ihr Kerngeschäft konzentrieren.", "en": "Through outsourcing, companies can reduce costs and focus on their core business."}, {"de": "Das Outsourcing der IT-Abteilung war umstritten, da es zum Jobabbau führte.", "en": "The outsourcing of the IT department was controversial as it led to job losses."}]},
  {id:1685,german:"das Offshoring",level:"B2",english:"offshoring",pos:"noun (n)",sentences:[{"de": "Viele Unternehmen betreiben Offshoring, um von günstigeren Arbeitskräften zu profitieren.", "en": "Many companies practise offshoring to benefit from cheaper labour."}, {"de": "Offshoring kann kurzfristig Kosten sparen, birgt aber langfristige Risiken.", "en": "Offshoring can save costs in the short term but carries long-term risks."}]},
  {id:1686,german:"die Globalisierung",level:"B2",english:"globalisation",pos:"noun (f)",sentences:[{"de": "Die Globalisierung hat den Welthandel enorm ausgeweitet und Millionen aus der Armut befreit.", "en": "Globalisation has enormously expanded world trade and lifted millions out of poverty."}, {"de": "Kritiker der Globalisierung beklagen wachsende Ungleichheiten zwischen Ländern.", "en": "Critics of globalisation deplore growing inequalities between countries."}]},
  {id:1687,german:"der Freihandel",level:"B2",english:"free trade",pos:"noun (m)",sentences:[{"de": "Freihandel fördert den wirtschaftlichen Austausch und Wohlstand zwischen Nationen.", "en": "Free trade promotes economic exchange and prosperity between nations."}, {"de": "Die Debatte über Freihandel versus Protektionismus ist so alt wie die Wirtschaft selbst.", "en": "The debate about free trade versus protectionism is as old as the economy itself."}]},
  {id:1688,german:"das Freihandelsabkommen",level:"B2",english:"free trade agreement",pos:"noun (n)",sentences:[{"de": "Das Freihandelsabkommen zwischen der EU und Kanada war jahrelang umstritten.", "en": "The free trade agreement between the EU and Canada was controversial for years."}, {"de": "Durch das Freihandelsabkommen entfallen viele Zölle auf Waren zwischen den Ländern.", "en": "The free trade agreement eliminates many tariffs on goods between the countries."}]},
  {id:1689,german:"die Handelsbilanz",level:"B2",english:"trade balance",pos:"noun (f)",sentences:[{"de": "Deutschland weist seit Jahren eine positive Handelsbilanz auf.", "en": "Germany has had a positive trade balance for years."}, {"de": "Die Handelsbilanz zeigt das Verhältnis zwischen Exporten und Importen eines Landes.", "en": "The trade balance shows the ratio of exports to imports for a country."}]},
  {id:1690,german:"das Handelsbilanzdefizit",level:"B2",english:"trade deficit",pos:"noun (n)",sentences:[{"de": "Die USA kämpfen mit einem anhaltenden Handelsbilanzdefizit gegenüber China.", "en": "The USA is struggling with a persistent trade deficit with China."}, {"de": "Ein hohes Handelsbilanzdefizit kann die Währung eines Landes schwächen.", "en": "A high trade deficit can weaken a country's currency."}]},
  {id:1691,german:"der Handelsüberschuss",level:"B2",english:"trade surplus",pos:"noun (m)",sentences:[{"de": "Der deutsche Handelsüberschuss ist einer der höchsten weltweit und wird international kritisiert.", "en": "The German trade surplus is one of the highest in the world and is criticised internationally."}, {"de": "Ein dauerhafter Handelsüberschuss deutet auf eine starke Exportwirtschaft hin.", "en": "A sustained trade surplus indicates a strong export economy."}]},
  {id:1692,german:"die Wirtschaftspolitik",level:"B2",english:"economic policy",pos:"noun (f)",sentences:[{"de": "Die Wirtschaftspolitik der neuen Regierung setzt auf Investitionen in Infrastruktur.", "en": "The new government's economic policy focuses on investment in infrastructure."}, {"de": "Wirtschaftspolitische Entscheidungen haben direkte Auswirkungen auf das Leben der Bürger.", "en": "Economic policy decisions have a direct impact on the lives of citizens."}]},
  {id:1693,german:"die Fiskalpolitik",level:"B2",english:"fiscal policy",pos:"noun (f)",sentences:[{"de": "Die expansive Fiskalpolitik der Regierung soll die Konjunktur ankurbeln.", "en": "The government's expansionary fiscal policy is intended to stimulate the economy."}, {"de": "Fiskalpolitik umfasst alle staatlichen Maßnahmen zu Steuern und Ausgaben.", "en": "Fiscal policy encompasses all government measures relating to taxation and expenditure."}]},
  {id:1694,german:"die Geldpolitik",level:"B2",english:"monetary policy",pos:"noun (f)",sentences:[{"de": "Die Geldpolitik der Europäischen Zentralbank beeinflusst die Inflation in der gesamten Eurozone.", "en": "The monetary policy of the European Central Bank influences inflation throughout the eurozone."}, {"de": "Eine lockere Geldpolitik mit niedrigen Zinsen soll Investitionen fördern.", "en": "A loose monetary policy with low interest rates is intended to encourage investment."}]},
  {id:1695,german:"die Zentralbank",level:"B2",english:"central bank",pos:"noun (f)",sentences:[{"de": "Die Zentralbank hat die Aufgabe, die Preisstabilität zu gewährleisten.", "en": "The central bank has the task of ensuring price stability."}, {"de": "Zentralbanken können durch Zinsentscheidungen die Wirtschaft stark beeinflussen.", "en": "Central banks can strongly influence the economy through interest rate decisions."}]},
  {id:1696,german:"die Europäische Zentralbank",level:"B2",english:"European Central Bank (ECB)",pos:"noun (f)",sentences:[{"de": "Die Europäische Zentralbank hat ihren Sitz in Frankfurt am Main.", "en": "The European Central Bank is headquartered in Frankfurt am Main."}, {"de": "Die Europäische Zentralbank entscheidet über die Zinspolitik für alle Länder der Eurozone.", "en": "The European Central Bank decides on interest rate policy for all countries in the eurozone."}]},
  {id:1697,german:"der Leitzins",level:"B2",english:"key interest rate, base rate",pos:"noun (m)",sentences:[{"de": "Die EZB hat den Leitzins angehoben, um die hohe Inflation einzudämmen.", "en": "The ECB raised the key interest rate to curb high inflation."}, {"de": "Ein niedriger Leitzins soll Kredite günstiger und Investitionen attraktiver machen.", "en": "A low base rate is intended to make loans cheaper and investments more attractive."}]},
  {id:1698,german:"die Liquidität",level:"B2",english:"liquidity",pos:"noun (f)",sentences:[{"de": "Die Liquidität des Unternehmens war gefährdet, als die Großaufträge ausblieben.", "en": "The company's liquidity was at risk when major orders failed to materialise."}, {"de": "Banken müssen ausreichend Liquidität vorhalten, um Kundenabhebungen bedienen zu können.", "en": "Banks must maintain sufficient liquidity to be able to service customer withdrawals."}]},
  {id:1699,german:"die Solvenz",level:"B2",english:"solvency",pos:"noun (f)",sentences:[{"de": "Die Solvenz eines Unternehmens zeigt, ob es langfristig in der Lage ist, seinen Verbindlichkeiten nachzukommen.", "en": "The solvency of a company shows whether it is able to meet its liabilities in the long term."}, {"de": "Strenge Solvenzanforderungen sollen das Finanzsystem stabiler machen.", "en": "Strict solvency requirements are intended to make the financial system more stable."}]},
  {id:1700,german:"die Kapitalanlage",level:"B2",english:"capital investment",pos:"noun (f)",sentences:[{"de": "Immobilien gelten als sichere Kapitalanlage in Zeiten niedriger Zinsen.", "en": "Real estate is considered a safe capital investment in times of low interest rates."}, {"de": "Er hat seine Ersparnisse in verschiedene Kapitalanlagen investiert, um das Risiko zu streuen.", "en": "He has invested his savings in various capital investments to spread the risk."}]},
  {id:1701,german:"das Portfolio",level:"B2",english:"portfolio",pos:"noun (n)",sentences:[{"de": "Ein gut diversifiziertes Portfolio reduziert das finanzielle Risiko erheblich.", "en": "A well-diversified portfolio significantly reduces financial risk."}, {"de": "Sie bat einen Finanzberater, ihr Portfolio zu überprüfen und anzupassen.", "en": "She asked a financial adviser to review and adjust her portfolio."}]},
  {id:1702,german:"die Rendite",level:"B2",english:"return, yield",pos:"noun (f)",sentences:[{"de": "Die Rendite der Staatsanleihen ist in den letzten Jahren deutlich gesunken.", "en": "The yield on government bonds has fallen significantly in recent years."}, {"de": "Anleger suchen nach Möglichkeiten, eine höhere Rendite bei vertretbarem Risiko zu erzielen.", "en": "Investors are looking for ways to achieve a higher return at an acceptable risk."}]},
  {id:1703,german:"das Risikomanagement",level:"B2",english:"risk management",pos:"noun (n)",sentences:[{"de": "Ein effektives Risikomanagement ist für Unternehmen in unsicheren Zeiten unverzichtbar.", "en": "Effective risk management is indispensable for companies in uncertain times."}, {"de": "Das Risikomanagement der Bank hatte die Gefahr frühzeitig erkannt und entsprechende Maßnahmen eingeleitet.", "en": "The bank's risk management had identified the danger early and initiated appropriate measures."}]},
];
export default WORDS_B2;